fn timestamp_ceil_unit(table: &Table, arg: &ConcatArg) -> Result<char, Error> {
    let text = match arg {
        ConcatArg::Literal(Scalar::Null) => return Err(Error::new("invalid unit 'null'")),
        ConcatArg::Literal(Scalar::Text(text)) => text.clone(),
        ConcatArg::Literal(Scalar::Char(unit)) => {
            if *unit == 0 {
                return Err(Error::new("invalid unit 'null'"));
            }
            char::from_u32(u32::from(*unit))
                .unwrap_or('\u{0}')
                .to_string()
        }
        ConcatArg::Column(name) => {
            let Some(index) = table.column_index(name) else {
                return Err(Error::new(format!("Invalid column: {name}")));
            };
            let actual = qdb_types::type_name(table.meta.columns[index].tag);
            let expected = if actual == "STRING" {
                "STRING constant"
            } else {
                "STRING"
            };
            return Err(Error::new(format!(
                "expression type mismatch, expected: {expected}, actual: {actual}"
            )));
        }
        ConcatArg::Literal(other) => {
            return Err(Error::new(format!(
                "expression type mismatch, expected: STRING, actual: {}",
                literal_sql_type(other)
            )));
        }
    };
    let mut chars = text.chars();
    match (chars.next(), chars.next()) {
        (None, _) => Err(Error::new("invalid unit 'null'")),
        (Some(unit), None)
            if matches!(
                unit,
                'n' | 'U' | 'T' | 's' | 'm' | 'h' | 'd' | 'w' | 'M' | 'y'
            ) =>
        {
            Ok(unit)
        }
        (Some(unit), None) => Err(Error::new(format!("invalid unit '{unit}'"))),
        _ => Err(Error::new(format!(
            "inconvertible value: `{text}` [STRING -> CHAR]"
        ))),
    }
}

fn timestamp_ceil_micros(unit: char, micros: i64) -> i64 {
    let step = |unit: char, size: i64| timestamp_floor_micros(unit, 1, micros) + size;
    match unit {
        'n' | 'U' => micros,
        'T' => step('T', 1_000),
        's' => step('s', 1_000_000),
        'm' => step('m', 60 * 1_000_000),
        'h' => step('h', 3_600 * 1_000_000),
        'd' => step('d', DATEADD_DAY),
        'w' => step('w', 7 * DATEADD_DAY),
        'M' => {
            let (mut year, mut month, _, _) = dateadd_parts(micros);
            month += 1;
            if month == 13 {
                month = 1;
                year += 1;
            }
            qdb_types::unix_days_from_civil(year, month, 1).unwrap_or(0) * DATEADD_DAY
        }
        'y' => {
            let (year, _, _, _) = dateadd_parts(micros);
            qdb_types::unix_days_from_civil(year + 1, 1, 1).unwrap_or(0) * DATEADD_DAY
        }
        _ => micros,
    }
}

fn resolve_timestamp_floor(
    table: &Table,
    expr: &TimestampFloorExpr,
) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 2
        || !matches!(
            &expr.args[0],
            ConcatArg::Literal(Scalar::Null | Scalar::Text(_) | Scalar::Char(_))
        )
    {
        return Err(Error::new(format!(
            "there is no matching function `timestamp_floor` with the argument types: ({})",
            timestamp_floor_types(table, &expr.args)?
        )));
    }
    let (unit, stride) = timestamp_floor_unit(&expr.args[0])?;
    Ok(ResolvedProj::TimestampFloor {
        label: expr.label.clone(),
        unit,
        stride,
        value: date_trunc_timestamp(table, &expr.args[1])?,
    })
}

fn timestamp_floor_types(table: &Table, args: &[ConcatArg]) -> Result<String, Error> {
    let mut names = Vec::with_capacity(args.len());
    for arg in args {
        names.push(timestamp_floor_arg_type(table, arg)?);
    }
    Ok(names.join(", "))
}

fn timestamp_floor_arg_type(table: &Table, arg: &ConcatArg) -> Result<&'static str, Error> {
    match arg {
        ConcatArg::Column(name) => {
            let Some(index) = table.column_index(name) else {
                return Err(Error::new(format!("Invalid column: {name}")));
            };
            Ok(qdb_types::type_name(table.meta.columns[index].tag))
        }
        ConcatArg::Literal(Scalar::Char(_)) => Ok("CHAR"),
        ConcatArg::Literal(Scalar::Text(text)) if text.chars().count() == 1 => Ok("CHAR"),
        ConcatArg::Literal(Scalar::Text(_)) => Ok("STRING"),
        ConcatArg::Literal(Scalar::Long(number)) if i32::try_from(*number).is_ok() => Ok("INT"),
        ConcatArg::Literal(Scalar::Long(_)) => Ok("LONG"),
        ConcatArg::Literal(Scalar::Double(_)) => Ok("DOUBLE"),
        ConcatArg::Literal(Scalar::Boolean(_)) => Ok("BOOLEAN"),
        ConcatArg::Literal(Scalar::Timestamp(_)) => Ok("TIMESTAMP"),
        ConcatArg::Literal(Scalar::Null) => Ok("NULL"),
        ConcatArg::Literal(_) => Ok("UNSUPPORTED"),
    }
}

fn timestamp_floor_unit(arg: &ConcatArg) -> Result<(char, i32), Error> {
    let text = match arg {
        ConcatArg::Literal(Scalar::Null) => return Err(Error::new("invalid unit 'null'")),
        ConcatArg::Literal(Scalar::Text(text)) => text.clone(),
        ConcatArg::Literal(Scalar::Char(unit)) => char::from_u32(u32::from(*unit))
            .unwrap_or('\u{0}')
            .to_string(),
        _ => return Err(Error::new("invalid unit ''")),
    };
    let (digits, unit) = match text.chars().count() {
        0 => return Err(Error::new("invalid unit ''")),
        1 => ("1", text.as_str()),
        _ => {
            let split = text.char_indices().next_back().map(|(i, _)| i).unwrap_or(0);
            (&text[..split], &text[split..])
        }
    };
    let stride = digits.parse::<i32>().ok().filter(|stride| *stride > 0);
    let unit = unit.chars().next().filter(|_| unit.chars().count() == 1);
    match (stride, unit) {
        (Some(stride), Some(unit))
            if matches!(
                unit,
                'n' | 'U' | 'T' | 's' | 'm' | 'h' | 'd' | 'w' | 'M' | 'y'
            ) =>
        {
            Ok((unit, stride))
        }
        _ => Err(Error::new(format!("invalid unit '{text}'"))),
    }
}

fn timestamp_floor_micros(unit: char, stride: i32, micros: i64) -> i64 {
    let stride = i64::from(stride);
    let floor_step = |step: i64| micros - micros.rem_euclid(step);
    match unit {
        'n' => {
            let nanos = micros * 1_000;
            let floored = nanos - nanos.rem_euclid(stride);
            floored / 1_000
        }
        'U' => floor_step(stride),
        'T' => floor_step(stride * 1_000),
        's' => floor_step(stride * 1_000_000),
        'm' => floor_step(stride * 60 * 1_000_000),
        'h' => floor_step(stride * 3_600 * 1_000_000),
        'd' => floor_step(stride * DATEADD_DAY),
        'w' => {
            let span = stride * 7 * DATEADD_DAY;
            let shifted = micros + 3 * DATEADD_DAY;
            micros - shifted.rem_euclid(span)
        }
        'M' => {
            let (year, month, _, _) = dateadd_parts(micros);
            let months = 12 * i64::from(year - 1970) + i64::from(month - 1);
            let floored = months.div_euclid(stride) * stride;
            let year = 1970 + i32::try_from(floored.div_euclid(12)).unwrap_or(0);
            let month = u32::try_from(floored.rem_euclid(12)).unwrap_or(0) + 1;
            qdb_types::unix_days_from_civil(year, month, 1).unwrap_or(0) * DATEADD_DAY
        }
        'y' => {
            let (year, _, _, _) = dateadd_parts(micros);
            let year = 1970 + (i64::from(year) - 1970).div_euclid(stride) * stride;
            qdb_types::unix_days_from_civil(i32::try_from(year).unwrap_or(1970), 1, 1).unwrap_or(0)
                * DATEADD_DAY
        }
        _ => micros,
    }
}

fn resolve_date_trunc(table: &Table, expr: &DateTruncExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 2 {
        return Err(Error::new(format!(
            "wrong number of arguments for function `date_trunc`; expected: 2, provided: {}",
            expr.args.len()
        )));
    }
    Ok(ResolvedProj::DateTrunc {
        label: expr.label.clone(),
        unit: date_trunc_unit(table, &expr.args[0])?,
        value: date_trunc_timestamp(table, &expr.args[1])?,
    })
}

fn date_trunc_unit(table: &Table, arg: &ConcatArg) -> Result<&'static str, Error> {
    let text = match arg {
        ConcatArg::Literal(Scalar::Null) => return Err(Error::new("invalid unit 'null'")),
        ConcatArg::Literal(Scalar::Text(text)) => text.clone(),
        ConcatArg::Literal(Scalar::Char(unit)) => char::from_u32(u32::from(*unit))
            .unwrap_or('\u{0}')
            .to_string(),
        ConcatArg::Column(name) => {
            let Some(index) = table.column_index(name) else {
                return Err(Error::new(format!("Invalid column: {name}")));
            };
            let actual = qdb_types::type_name(table.meta.columns[index].tag);
            let expected = if actual == "STRING" {
                "STRING constant"
            } else {
                "STRING"
            };
            return Err(Error::new(format!(
                "expression type mismatch, expected: {expected}, actual: {actual}"
            )));
        }
        ConcatArg::Literal(other) => {
            return Err(Error::new(format!(
                "expression type mismatch, expected: STRING, actual: {}",
                literal_sql_type(other)
            )));
        }
    };
    date_trunc_kind(&text).ok_or_else(|| Error::new(format!("invalid unit '{text}'")))
}

fn literal_sql_type(value: &Scalar) -> &'static str {
    match value {
        Scalar::Long(number) if i32::try_from(*number).is_ok() => "INT",
        Scalar::Long(_) => "LONG",
        Scalar::Double(_) => "DOUBLE",
        Scalar::Text(_) | Scalar::Char(_) => "STRING",
        Scalar::Boolean(_) => "BOOLEAN",
        _ => "UNSUPPORTED",
    }
}

fn date_trunc_kind(unit: &str) -> Option<&'static str> {
    if unit == "century" || unit == "centuries" {
        return Some("century");
    }
    const NAMES: &[&str] = &[
        "nanosecond",
        "microsecond",
        "millisecond",
        "second",
        "minute",
        "hour",
        "day",
        "week",
        "month",
        "quarter",
        "year",
        "decade",
        "millennium",
    ];
    NAMES.iter().copied().find(|name| {
        unit == *name
            || (unit.len() == name.len() + 1 && unit.starts_with(name) && unit.ends_with('s'))
    })
}

fn date_trunc_timestamp(table: &Table, arg: &ConcatArg) -> Result<DateDiffSide, Error> {
    if let ConcatArg::Column(name) = arg {
        if let Some(index) = table.column_index(name) {
            if table.meta.columns[index].tag == qdb_types::TAG_STRING {
                let sample = match table.columns[index].first() {
                    Some(Scalar::Text(text)) => text.as_str(),
                    _ => "",
                };
                return Err(Error::new(format!(
                    "inconvertible value: `{sample}` [STRING -> TIMESTAMP_NS]"
                )));
            }
        }
    }
    datediff_side(table, arg, "date_trunc", 2)
}

fn date_trunc_micros(unit: &str, micros: i64) -> i64 {
    let floor_step = |step: i64| micros - micros.rem_euclid(step);
    match unit {
        "nanosecond" | "microsecond" => micros,
        "millisecond" => floor_step(1_000),
        "second" => floor_step(1_000_000),
        "minute" => floor_step(60 * 1_000_000),
        "hour" => floor_step(3_600 * 1_000_000),
        "day" => micros.div_euclid(DATEADD_DAY) * DATEADD_DAY,
        "week" => {
            let days = micros.div_euclid(DATEADD_DAY);
            let weekday = i64::from(weekday_monday(micros));
            (days - (weekday - 1)) * DATEADD_DAY
        }
        "month" | "quarter" | "year" | "decade" | "century" | "millennium" => {
            let (mut year, mut month, _, _) = dateadd_parts(micros);
            match unit {
                "quarter" => month = ((month - 1) / 3) * 3 + 1,
                "year" | "decade" | "century" | "millennium" => {
                    month = 1;
                    year = match unit {
                        "decade" => (year / 10) * 10,
                        "century" => (((year + 99) / 100) * 100) - 99,
                        "millennium" => (((year + 999) / 1000) * 1000) - 999,
                        _ => year,
                    };
                }
                _ => {}
            }
            qdb_types::unix_days_from_civil(year, month, 1).unwrap_or(0) * DATEADD_DAY
        }
        _ => micros,
    }
}

fn resolve_week_of_year(table: &Table, expr: &WeekOfYearExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 1 {
        return Err(Error::new(format!(
            "wrong number of arguments for function `week_of_year`; expected: 1, provided: {}",
            expr.args.len()
        )));
    }
    Ok(ResolvedProj::WeekOfYear {
        label: expr.label.clone(),
        value: datediff_side(table, &expr.args[0], "week_of_year", 1)?,
    })
}

fn iso_week(micros: i64) -> i32 {
    let days = micros.div_euclid(DATEADD_DAY);
    let weekday = i64::from(weekday_monday(micros));
    let thursday = days + (4 - weekday);
    let (year, _, _) = qdb_types::civil_from_unix_days(thursday);
    let jan4 = qdb_types::unix_days_from_civil(year, 1, 4).unwrap_or(0);
    let jan4_index = (jan4 + 4).rem_euclid(7);
    let jan4_weekday = if jan4_index == 0 { 7 } else { jan4_index };
    let week1_thursday = jan4 + (4 - jan4_weekday);
    ((thursday - week1_thursday) / 7 + 1) as i32
}

