fn resolve_round(table: &Table, expr: &RoundExpr) -> Result<ResolvedProj, Error> {
    if expr.args.is_empty() || expr.args.len() > 2 {
        return Err(named_type_error(table, "round", &expr.args));
    }
    let input = round_input(table, &expr.args[0])
        .map_err(|_| named_type_error(table, "round", &expr.args))?;
    let scale = if expr.args.len() == 1 {
        RoundScale::Zero
    } else {
        match resolve_i32_count(table, &expr.args[1]) {
            Ok(CountArg::Null) => RoundScale::Null,
            Ok(CountArg::Fixed(0)) => RoundScale::Zero,
            Ok(CountArg::Fixed(scale)) => {
                let scale = i32::try_from(scale).unwrap_or(i32::MAX);
                if round_scale_in_range(scale) {
                    RoundScale::Fixed(scale)
                } else {
                    RoundScale::Null
                }
            }
            Ok(CountArg::ColumnInt { index })
                if table.meta.columns[index].tag != qdb_types::TAG_LONG =>
            {
                RoundScale::Column(index)
            }
            Ok(_) | Err(()) => return Err(named_type_error(table, "round", &expr.args)),
        }
    };
    Ok(ResolvedProj::Round {
        label: expr.label.clone(),
        input,
        scale,
    })
}

fn round_input(table: &Table, arg: &ConcatArg) -> Result<RoundInput, ()> {
    match arg {
        ConcatArg::Literal(Scalar::Null) => Ok(RoundInput::Null),
        ConcatArg::Literal(Scalar::Long(number)) => Ok(RoundInput::Long(*number)),
        ConcatArg::Literal(Scalar::Double(number)) => Ok(RoundInput::Double(*number)),
        ConcatArg::Column(name) => {
            let index = table.column_index(name).ok_or(())?;
            let tag = table.meta.columns[index].tag;
            if matches!(
                tag,
                qdb_types::TAG_BYTE
                    | qdb_types::TAG_SHORT
                    | qdb_types::TAG_INT
                    | qdb_types::TAG_LONG
                    | qdb_types::TAG_FLOAT
                    | qdb_types::TAG_DOUBLE
            ) {
                Ok(RoundInput::Column { index })
            } else {
                Err(())
            }
        }
        ConcatArg::Literal(_) => Err(()),
    }
}

fn named_type_error(table: &Table, name: &str, args: &[ConcatArg]) -> Error {
    let mut types = Vec::new();
    for arg in args {
        match concat_arg_type(table, arg) {
            Ok(type_name) => types.push(type_name),
            Err(err) => return err,
        }
    }
    Error::new(format!(
        "there is no matching function `{name}` with the argument types: ({})",
        types.join(", ")
    ))
}

fn resolve_abs(table: &Table, expr: &AbsExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 1 {
        return Err(abs_type_error(table, &expr.args));
    }
    let (input, result_tag) = match &expr.args[0] {
        ConcatArg::Literal(Scalar::Null) => (AbsInput::Null, qdb_types::TAG_INT),
        ConcatArg::Literal(Scalar::Long(number)) => (
            AbsInput::Long(*number),
            if i32::try_from(*number).is_ok() {
                qdb_types::TAG_INT
            } else {
                qdb_types::TAG_LONG
            },
        ),
        ConcatArg::Literal(Scalar::Double(number)) => {
            (AbsInput::Double(*number), qdb_types::TAG_DOUBLE)
        }
        ConcatArg::Column(name) => {
            let index = table
                .column_index(name)
                .ok_or_else(|| Error::new(format!("Invalid column: {name}")))?;
            let tag = table.meta.columns[index].tag;
            let result_tag = match tag {
                qdb_types::TAG_BYTE | qdb_types::TAG_SHORT => qdb_types::TAG_SHORT,
                qdb_types::TAG_INT => qdb_types::TAG_INT,
                qdb_types::TAG_LONG => qdb_types::TAG_LONG,
                qdb_types::TAG_FLOAT | qdb_types::TAG_DOUBLE => qdb_types::TAG_DOUBLE,
                _ => return Err(abs_type_error(table, &expr.args)),
            };
            (AbsInput::Column { index }, result_tag)
        }
        ConcatArg::Literal(_) => return Err(abs_type_error(table, &expr.args)),
    };
    Ok(ResolvedProj::Abs {
        label: expr.label.clone(),
        input,
        result_tag,
    })
}

fn abs_type_error(table: &Table, args: &[ConcatArg]) -> Error {
    let mut types = Vec::new();
    for arg in args {
        match concat_arg_type(table, arg) {
            Ok(type_name) => types.push(type_name),
            Err(err) => return err,
        }
    }
    Error::new(format!(
        "there is no matching function `abs` with the argument types: ({})",
        types.join(", ")
    ))
}

fn resolve_size_pretty(table: &Table, expr: &SizePrettyExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 1 {
        return Err(Error::new(format!(
            "wrong number of arguments for function `size_pretty`; expected: 1, provided: {}",
            expr.args.len()
        )));
    }
    let size = match resolve_count(table, &expr.args[0]) {
        Ok(CountArg::ColumnSymbol { .. }) | Err(()) => {
            let actual = concat_arg_type(table, &expr.args[0])?;
            return Err(Error::new(format!(
                "argument type mismatch for function `size_pretty` at #1 expected: LONG, actual: {actual}"
            )));
        }
        Ok(size) => size,
    };
    Ok(ResolvedProj::SizePretty {
        label: expr.label.clone(),
        size,
    })
}

fn resolve_quote_ident(table: &Table, expr: &QuoteIdentExpr) -> Result<ResolvedProj, Error> {
    Ok(ResolvedProj::QuoteIdent {
        label: expr.label.clone(),
        arg: resolve_one_text(table, &function_name(&expr.label), &expr.args)?,
    })
}

fn resolve_pad(table: &Table, expr: &PadExpr) -> Result<ResolvedProj, Error> {
    let name = function_name(&expr.label);
    let width = expr.args.get(1).and_then(|arg| pad_width(table, arg).ok());
    let fill_ok = expr.args.len() != 3
        || expr
            .args
            .get(2)
            .is_some_and(|arg| replace_text_ok(table, arg));
    if !matches!(expr.args.len(), 2 | 3)
        || expr
            .args
            .first()
            .is_none_or(|arg| !replace_text_ok(table, arg))
        || width.is_none()
        || !fill_ok
    {
        return Err(text_type_error(table, &name, &expr.args));
    }
    let fill = if expr.args.len() == 3 {
        Some(resolve_concat_arg(table, &expr.args[2])?)
    } else {
        None
    };
    Ok(ResolvedProj::Pad {
        label: expr.label.clone(),
        value: resolve_concat_arg(table, &expr.args[0])?,
        width: width.expect("width already checked"),
        fill,
        from_right: expr.from_right,
    })
}

fn pad_width(table: &Table, arg: &ConcatArg) -> Result<CountArg, ()> {
    match resolve_i32_count(table, arg)? {
        CountArg::ColumnSymbol { .. } => Err(()),
        width => Ok(width),
    }
}

fn resolve_split_part(table: &Table, expr: &SplitPartExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 3
        || expr
            .args
            .first()
            .is_none_or(|arg| !replace_text_ok(table, arg))
        || expr
            .args
            .get(1)
            .is_none_or(|arg| !replace_text_ok(table, arg))
        || split_index(&expr.args[2], table).is_err()
    {
        return Err(text_type_error(table, "split_part", &expr.args));
    }
    let index = match split_index(&expr.args[2], table).expect("index type already checked") {
        SplitIndex::Null => None,
        SplitIndex::Fixed(0) => {
            return Err(Error::new("field position must not be zero"));
        }
        SplitIndex::Fixed(index) => Some(index),
        SplitIndex::Column => {
            return Err(Error::new(
                "index must be either a constant expression or a placeholder",
            ));
        }
    };
    Ok(ResolvedProj::SplitPart {
        label: expr.label.clone(),
        value: resolve_concat_arg(table, &expr.args[0])?,
        delimiter: resolve_concat_arg(table, &expr.args[1])?,
        index,
    })
}

enum SplitIndex {
    Null,
    Fixed(i32),
    Column,
}

fn split_index(arg: &ConcatArg, table: &Table) -> Result<SplitIndex, ()> {
    match arg {
        ConcatArg::Literal(Scalar::Null) => Ok(SplitIndex::Null),
        ConcatArg::Literal(Scalar::Long(number)) => i32::try_from(*number)
            .map(SplitIndex::Fixed)
            .map_err(|_| ()),
        ConcatArg::Literal(_) => Err(()),
        ConcatArg::Column(name) => {
            let index = table.column_index(name).ok_or(())?;
            let tag = table.meta.columns[index].tag;
            if matches!(
                tag,
                qdb_types::TAG_BYTE | qdb_types::TAG_SHORT | qdb_types::TAG_INT
            ) {
                Ok(SplitIndex::Column)
            } else {
                Err(())
            }
        }
    }
}

fn resolve_strpos(table: &Table, expr: &StrPosExpr) -> Result<ResolvedProj, Error> {
    let name = expr
        .label
        .split_once('(')
        .map(|(name, _)| name.to_ascii_lowercase())
        .unwrap_or_else(|| "strpos".to_string());
    if expr.args.len() != 2 || expr.args.iter().any(|arg| !replace_text_ok(table, arg)) {
        return Err(text_type_error(table, &name, &expr.args));
    }
    Ok(ResolvedProj::StrPos {
        label: expr.label.clone(),
        value: resolve_concat_arg(table, &expr.args[0])?,
        needle: resolve_concat_arg(table, &expr.args[1])?,
        needle_null: matches!(expr.args[1], ConcatArg::Literal(Scalar::Null)),
    })
}

fn resolve_starts_with(table: &Table, expr: &StartsWithExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 2 || expr.args.iter().any(|arg| !replace_text_ok(table, arg)) {
        return Err(text_type_error(table, "starts_with", &expr.args));
    }
    Ok(ResolvedProj::StartsWith {
        label: expr.label.clone(),
        value: resolve_concat_arg(table, &expr.args[0])?,
        prefix: resolve_concat_arg(table, &expr.args[1])?,
    })
}

fn resolve_replace(table: &Table, expr: &ReplaceExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 3 || expr.args.iter().any(|arg| !replace_text_ok(table, arg)) {
        return Err(text_type_error(table, "replace", &expr.args));
    }
    let mode = if matches!(expr.args[2], ConcatArg::Literal(Scalar::Null))
        || matches!(expr.args[1], ConcatArg::Literal(Scalar::Null))
    {
        ReplaceMode::Null
    } else if matches!(&expr.args[1], ConcatArg::Literal(Scalar::Text(text)) if text.is_empty()) {
        ReplaceMode::Value(resolve_concat_arg(table, &expr.args[0])?)
    } else if matches!(expr.args[0], ConcatArg::Literal(Scalar::Null)) {
        ReplaceMode::Null
    } else if matches!(&expr.args[0], ConcatArg::Literal(Scalar::Text(text)) if text.is_empty()) {
        ReplaceMode::Empty
    } else {
        ReplaceMode::Run {
            value: resolve_concat_arg(table, &expr.args[0])?,
            old: resolve_concat_arg(table, &expr.args[1])?,
            new: resolve_concat_arg(table, &expr.args[2])?,
        }
    };
    Ok(ResolvedProj::Replace {
        label: expr.label.clone(),
        mode,
    })
}

fn replace_text_ok(table: &Table, arg: &ConcatArg) -> bool {
    match arg {
        ConcatArg::Literal(Scalar::Text(_)) | ConcatArg::Literal(Scalar::Null) => true,
        ConcatArg::Literal(_) => false,
        ConcatArg::Column(name) => table.column_index(name).is_some_and(|index| {
            matches!(
                table.meta.columns[index].tag,
                qdb_types::TAG_STRING
                    | qdb_types::TAG_SYMBOL
                    | qdb_types::TAG_VARCHAR
                    | qdb_types::TAG_CHAR
            )
        }),
    }
}

fn text_type_error(table: &Table, name: &str, args: &[ConcatArg]) -> Error {
    let mut types = Vec::new();
    for arg in args {
        match replace_arg_type(table, arg) {
            Ok(type_name) => types.push(type_name),
            Err(err) => return err,
        }
    }
    Error::new(format!(
        "there is no matching function `{name}` with the argument types: ({})",
        types.join(", ")
    ))
}

fn replace_arg_type(table: &Table, arg: &ConcatArg) -> Result<String, Error> {
    match arg {
        ConcatArg::Literal(Scalar::Null) => Ok("NULL".to_string()),
        ConcatArg::Literal(Scalar::Text(text)) if text.encode_utf16().count() == 1 => {
            Ok("CHAR".to_string())
        }
        ConcatArg::Literal(Scalar::Text(_)) => Ok("STRING".to_string()),
        ConcatArg::Literal(Scalar::Long(number)) => {
            if i32::try_from(*number).is_ok() {
                Ok("INT".to_string())
            } else {
                Ok("LONG".to_string())
            }
        }
        ConcatArg::Literal(Scalar::Double(_)) => Ok("DOUBLE".to_string()),
        ConcatArg::Literal(_) => Ok("STRING".to_string()),
        ConcatArg::Column(name) => {
            let index = table
                .column_index(name)
                .ok_or_else(|| Error::new(format!("Invalid column: {name}")))?;
            Ok(qdb_types::type_name(table.meta.columns[index].tag).to_string())
        }
    }
}

fn resolve_trim(table: &Table, expr: &TrimExpr) -> Result<ResolvedProj, Error> {
    let name = match expr.end {
        TrimEnd::Left => "ltrim",
        TrimEnd::Right => "rtrim",
        TrimEnd::Both => "trim",
    };
    Ok(ResolvedProj::Trim {
        label: expr.label.clone(),
        arg: resolve_one_text(table, name, &expr.args)?,
        end: expr.end,
    })
}

fn resolve_substr(table: &Table, expr: &SubstrExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 3 {
        return Err(side_type_error(table, "substring", &expr.args));
    }
    let text = resolve_concat_arg(table, &expr.args[0])?;
    if !side_text_arg(&expr.args[0], &text) {
        return Err(side_type_error(table, "substring", &expr.args));
    }
    let start = match resolve_i32_count(table, &expr.args[1]) {
        Ok(count) => count,
        Err(()) => return Err(side_type_error(table, "substring", &expr.args)),
    };
    let len = match resolve_i32_count(table, &expr.args[2]) {
        Ok(count) => count,
        Err(()) => return Err(side_type_error(table, "substring", &expr.args)),
    };
    let mode = if matches!(expr.args[0], ConcatArg::Literal(Scalar::Null))
        || matches!(start, CountArg::Null)
        || matches!(len, CountArg::Null)
    {
        SubstrMode::Null
    } else if let CountArg::Fixed(len_value) = len {
        if len_value < 0 {
            return Err(Error::new("negative substring length is not allowed"));
        }
        if len_value == 0 {
            SubstrMode::Empty
        } else if let CountArg::Fixed(start_value) = start {
            let start_i = i32::try_from(start_value).unwrap_or(i32::MAX);
            let len_i = i32::try_from(len_value).unwrap_or(i32::MAX);
            if start_i.wrapping_add(len_i) < 1 {
                SubstrMode::Null
            } else {
                SubstrMode::Slice { text, start, len }
            }
        } else {
            SubstrMode::Slice { text, start, len }
        }
    } else {
        SubstrMode::Slice { text, start, len }
    };
    Ok(ResolvedProj::Substr {
        label: expr.label.clone(),
        mode,
    })
}

fn resolve_i32_count(table: &Table, arg: &ConcatArg) -> Result<CountArg, ()> {
    match resolve_count(table, arg)? {
        CountArg::Fixed(number) if i32::try_from(number).is_err() => Err(()),
        CountArg::ColumnInt { index } if table.meta.columns[index].tag == qdb_types::TAG_LONG => {
            Err(())
        }
        count => Ok(count),
    }
}

fn reject_negative_substring(table: &Table, row: usize, item: &ResolvedProj) -> Result<(), Error> {
    if let ResolvedProj::Substr {
        mode: SubstrMode::Slice { len, .. },
        ..
    } = item
    {
        if count_of(table, row, len).is_some_and(|len| len < 0) {
            return Err(Error::new("negative substring length is not allowed"));
        }
    }
    Ok(())
}

fn resolve_side(table: &Table, expr: &SideExpr) -> Result<ResolvedProj, Error> {
    let name = if expr.from_right { "right" } else { "left" };
    if expr.args.len() != 2 {
        return Err(side_type_error(table, name, &expr.args));
    }
    let text = resolve_concat_arg(table, &expr.args[0])?;
    if !side_text_arg(&expr.args[0], &text) {
        return Err(side_type_error(table, name, &expr.args));
    }
    let count = match resolve_count(table, &expr.args[1]) {
        Ok(count) => count,
        Err(()) => return Err(side_type_error(table, name, &expr.args)),
    };
    Ok(ResolvedProj::Side {
        label: expr.label.clone(),
        from_right: expr.from_right,
        text,
        count,
    })
}

fn side_text_arg(arg: &ConcatArg, resolved: &ResolvedArg) -> bool {
    match arg {
        ConcatArg::Literal(Scalar::Text(_)) | ConcatArg::Literal(Scalar::Null) => true,
        ConcatArg::Literal(_) => false,
        ConcatArg::Column(_) => side_text_ok(resolved),
    }
}

fn side_text_ok(arg: &ResolvedArg) -> bool {
    match arg {
        ResolvedArg::Text(_) | ResolvedArg::Null => true,
        ResolvedArg::Column { tag, .. } => matches!(
            *tag,
            qdb_types::TAG_STRING
                | qdb_types::TAG_SYMBOL
                | qdb_types::TAG_VARCHAR
                | qdb_types::TAG_CHAR
        ),
    }
}

fn resolve_count(table: &Table, arg: &ConcatArg) -> Result<CountArg, ()> {
    match arg {
        ConcatArg::Literal(Scalar::Null) => Ok(CountArg::Null),
        ConcatArg::Literal(Scalar::Long(number)) => Ok(CountArg::Fixed(*number)),
        ConcatArg::Literal(_) => Err(()),
        ConcatArg::Column(name) => {
            let index = table.column_index(name).ok_or(())?;
            let tag = table.meta.columns[index].tag;
            if matches!(
                tag,
                qdb_types::TAG_BYTE
                    | qdb_types::TAG_SHORT
                    | qdb_types::TAG_INT
                    | qdb_types::TAG_LONG
            ) {
                return Ok(CountArg::ColumnInt { index });
            }
            if tag == qdb_types::TAG_SYMBOL {
                let mut keys = Vec::new();
                for value in &table.columns[index] {
                    if value.is_null() || keys.contains(value) {
                        continue;
                    }
                    keys.push(value.clone());
                }
                return Ok(CountArg::ColumnSymbol { index, keys });
            }
            Err(())
        }
    }
}

fn side_type_error(table: &Table, name: &str, args: &[ConcatArg]) -> Error {
    let mut types = Vec::new();
    for arg in args {
        match side_arg_type(table, arg) {
            Ok(type_name) => types.push(type_name),
            Err(err) => return err,
        }
    }
    Error::new(format!(
        "there is no matching function `{name}` with the argument types: ({})",
        types.join(", ")
    ))
}

fn side_arg_type(table: &Table, arg: &ConcatArg) -> Result<String, Error> {
    match arg {
        ConcatArg::Literal(Scalar::Null) => Ok("NULL".to_string()),
        ConcatArg::Literal(Scalar::Long(number)) => {
            if i32::try_from(*number).is_ok() {
                Ok("INT".to_string())
            } else {
                Ok("LONG".to_string())
            }
        }
        ConcatArg::Literal(Scalar::Double(_)) => Ok("DOUBLE".to_string()),
        ConcatArg::Literal(_) => Ok("STRING".to_string()),
        ConcatArg::Column(name) => {
            let index = table
                .column_index(name)
                .ok_or_else(|| Error::new(format!("Invalid column: {name}")))?;
            Ok(qdb_types::type_name(table.meta.columns[index].tag).to_string())
        }
    }
}

fn resolve_upper(table: &Table, expr: &UpperExpr) -> Result<ResolvedProj, Error> {
    Ok(ResolvedProj::Upper {
        label: expr.label.clone(),
        arg: resolve_one_text(table, &function_name(&expr.label), &expr.args)?,
    })
}

fn resolve_lower(table: &Table, expr: &LowerExpr) -> Result<ResolvedProj, Error> {
    Ok(ResolvedProj::Lower {
        label: expr.label.clone(),
        arg: resolve_one_text(table, &function_name(&expr.label), &expr.args)?,
    })
}

fn function_name(label: &str) -> String {
    label
        .split_once('(')
        .map(|(name, _)| name)
        .unwrap_or(label)
        .to_ascii_lowercase()
}

fn resolve_one_text(table: &Table, name: &str, args: &[ConcatArg]) -> Result<ResolvedArg, Error> {
    if args.len() != 1 {
        let types = args
            .iter()
            .map(|arg| concat_arg_type(table, arg))
            .collect::<Result<Vec<_>, _>>()?
            .join(", ");
        return Err(Error::new(format!(
            "there is no matching function `{name}` with the argument types: ({types})"
        )));
    }
    let arg = resolve_concat_arg(table, &args[0])?;
    if let ResolvedArg::Column { tag, .. } = &arg {
        if !matches!(
            *tag,
            qdb_types::TAG_STRING
                | qdb_types::TAG_SYMBOL
                | qdb_types::TAG_VARCHAR
                | qdb_types::TAG_CHAR
        ) {
            return Err(Error::new(format!(
                "there is no matching function `{name}` with the argument types: ({})",
                qdb_types::type_name(*tag)
            )));
        }
    }
    Ok(arg)
}

fn resolve_length(table: &Table, expr: &LengthExpr) -> Result<ResolvedProj, Error> {
    if expr.bytes {
        return resolve_length_bytes(table, expr);
    }
    if expr.args.len() != 1 {
        let types = expr
            .args
            .iter()
            .map(|arg| concat_arg_type(table, arg))
            .collect::<Result<Vec<_>, _>>()?
            .join(", ");
        return Err(Error::new(format!(
            "there is no matching function `length` with the argument types: ({types})"
        )));
    }
    let arg = resolve_concat_arg(table, &expr.args[0])?;
    if let ResolvedArg::Column { tag, .. } = &arg {
        if !matches!(
            *tag,
            qdb_types::TAG_STRING
                | qdb_types::TAG_SYMBOL
                | qdb_types::TAG_VARCHAR
                | qdb_types::TAG_CHAR
        ) {
            return Err(Error::new(format!(
                "there is no matching function `length` with the argument types: ({})",
                qdb_types::type_name(*tag)
            )));
        }
    }
    Ok(ResolvedProj::Length {
        label: expr.label.clone(),
        arg,
        bytes: false,
    })
}

fn resolve_length_bytes(table: &Table, expr: &LengthExpr) -> Result<ResolvedProj, Error> {
    if expr.args.len() != 1 {
        return Err(Error::new(format!(
            "wrong number of arguments for function `length_bytes`; expected: 1, provided: {}",
            expr.args.len()
        )));
    }
    length_bytes_arg(table, &expr.args[0])?;
    Ok(ResolvedProj::Length {
        label: expr.label.clone(),
        arg: resolve_concat_arg(table, &expr.args[0])?,
        bytes: true,
    })
}

fn length_bytes_arg(table: &Table, arg: &ConcatArg) -> Result<(), Error> {
    let accepted = match arg {
        ConcatArg::Literal(Scalar::Null | Scalar::Text(_)) => true,
        ConcatArg::Literal(_) => false,
        ConcatArg::Column(name) => {
            let index = table
                .column_index(name)
                .ok_or_else(|| Error::new(format!("Invalid column: {name}")))?;
            matches!(
                table.meta.columns[index].tag,
                qdb_types::TAG_STRING | qdb_types::TAG_VARCHAR | qdb_types::TAG_CHAR
            )
        }
    };
    if accepted {
        return Ok(());
    }
    let actual = concat_arg_type(table, arg)?;
    Err(Error::new(format!(
        "argument type mismatch for function `length_bytes` at #1 expected: VARCHAR, actual: {actual}"
    )))
}

fn concat_arg_type(table: &Table, arg: &ConcatArg) -> Result<String, Error> {
    match arg {
        ConcatArg::Literal(Scalar::Null) => Ok("NULL".to_string()),
        ConcatArg::Literal(Scalar::Text(text)) if text.encode_utf16().count() == 1 => {
            Ok("CHAR".to_string())
        }
        ConcatArg::Literal(Scalar::Long(number)) => {
            if i32::try_from(*number).is_ok() {
                Ok("INT".to_string())
            } else {
                Ok("LONG".to_string())
            }
        }
        ConcatArg::Literal(Scalar::Double(_)) => Ok("DOUBLE".to_string()),
        ConcatArg::Literal(_) => Ok("STRING".to_string()),
        ConcatArg::Column(name) => {
            let index = table
                .column_index(name)
                .ok_or_else(|| Error::new(format!("Invalid column: {name}")))?;
            Ok(qdb_types::type_name(table.meta.columns[index].tag).to_string())
        }
    }
}

fn resolve_concat_arg(table: &Table, arg: &ConcatArg) -> Result<ResolvedArg, Error> {
    match arg {
        ConcatArg::Literal(Scalar::Text(text)) => Ok(ResolvedArg::Text(text.clone())),
        ConcatArg::Literal(_) => Ok(ResolvedArg::Null),
        ConcatArg::Column(name) => {
            let index = table
                .column_index(name)
                .ok_or_else(|| Error::new(format!("Invalid column: {name}")))?;
            Ok(ResolvedArg::Column {
                index,
                tag: table.meta.columns[index].tag,
            })
        }
    }
}

fn eval_checked(table: &Table, row: usize, item: &ResolvedProj) -> Result<Scalar, Error> {
    match item {
        ResolvedProj::Sin { input, .. } => sin_scalar(table, row, input),
        ResolvedProj::Cos { input, .. } => cos_scalar(table, row, input),
        ResolvedProj::Tan { input, .. } => tan_scalar(table, row, input),
        ResolvedProj::Asin { input, .. } => asin_scalar(table, row, input),
        ResolvedProj::Acos { input, .. } => acos_scalar(table, row, input),
        ResolvedProj::Atan { input, .. } => atan_scalar(table, row, input),
        ResolvedProj::Atan2 { y, x, .. } => atan2_scalar(table, row, y, x),
        ResolvedProj::Degrees { input, .. } => degrees_scalar(table, row, input),
        ResolvedProj::Radians { input, .. } => radians_scalar(table, row, input),
        ResolvedProj::Cot { input, .. } => cot_scalar(table, row, input),
        _ => Ok(eval_resolved(table, row, item)),
    }
}

fn eval_resolved(table: &Table, row: usize, item: &ResolvedProj) -> Scalar {
    match item {
        ResolvedProj::Column { index } => table.columns[*index][row].clone(),
        ResolvedProj::Concat { args, .. } => Scalar::Text(
            args.iter()
                .map(|arg| match arg {
                    ResolvedArg::Text(text) => text.clone(),
                    ResolvedArg::Null => String::new(),
                    ResolvedArg::Column { index, tag } => {
                        cast_concat(&table.columns[*index][row], *tag)
                    }
                })
                .collect(),
        ),
        ResolvedProj::Length { arg, bytes, .. } => {
            Scalar::Int(text_length(table, row, arg, *bytes))
        }
        ResolvedProj::Lower { arg, .. } => match text_of(table, row, arg) {
            Some(text) => Scalar::Text(text.to_lowercase()),
            None => Scalar::Null,
        },
        ResolvedProj::Upper { arg, .. } => match text_of(table, row, arg) {
            Some(text) => Scalar::Text(text.to_uppercase()),
            None => Scalar::Null,
        },
        ResolvedProj::Side {
            from_right,
            text,
            count,
            ..
        } => match (text_of(table, row, text), count_of(table, row, count)) {
            (Some(text), Some(count)) => Scalar::Text(take_chars(&text, count, *from_right)),
            _ => Scalar::Null,
        },
        ResolvedProj::Substr { mode, .. } => match mode {
            SubstrMode::Null => Scalar::Null,
            SubstrMode::Empty => Scalar::Text(String::new()),
            SubstrMode::Slice { text, start, len } => {
                match (
                    text_of(table, row, text),
                    count_of(table, row, start),
                    count_of(table, row, len),
                ) {
                    (Some(text), Some(start), Some(len)) => {
                        Scalar::Text(substring_utf16(&text, start, len))
                    }
                    _ => Scalar::Null,
                }
            }
        },
        ResolvedProj::Floor { input, wide, .. } => floor_value(table, row, input, *wide),
        ResolvedProj::Ceil { input, wide, .. } => ceil_value(table, row, input, *wide),
        ResolvedProj::Sign { input, .. } => sign_value(table, row, input),
        ResolvedProj::Power { base, exponent, .. } => power_value(table, row, base, exponent),
        ResolvedProj::Log { input, .. } => log_value(table, row, input, f64::log10),
        ResolvedProj::Exp { input, .. } => log_value(table, row, input, f64::exp),
        ResolvedProj::Pi { .. } => Scalar::Double(std::f64::consts::PI),
        ResolvedProj::Greatest {
            args, result_tag, ..
        } => greatest_value(table, row, args, *result_tag),
        ResolvedProj::Least {
            args, result_tag, ..
        } => least_value(table, row, args, *result_tag),
        ResolvedProj::Ln { input, .. } => log_value(table, row, input, f64::ln),
        ResolvedProj::Sin { input, .. } => match sin_scalar(table, row, input) {
            Ok(value) => value,
            Err(_) => Scalar::Null,
        },
        ResolvedProj::Cos { input, .. } => match cos_scalar(table, row, input) {
            Ok(value) => value,
            Err(_) => Scalar::Null,
        },
        ResolvedProj::Tan { input, .. } => match tan_scalar(table, row, input) {
            Ok(value) => value,
            Err(_) => Scalar::Null,
        },
        ResolvedProj::Asin { input, .. } => match asin_scalar(table, row, input) {
            Ok(value) => value,
            Err(_) => Scalar::Null,
        },
        ResolvedProj::Acos { input, .. } => match acos_scalar(table, row, input) {
            Ok(value) => value,
            Err(_) => Scalar::Null,
        },
        ResolvedProj::Atan { input, .. } => match atan_scalar(table, row, input) {
            Ok(value) => value,
            Err(_) => Scalar::Null,
        },
        ResolvedProj::Atan2 { y, x, .. } => match atan2_scalar(table, row, y, x) {
            Ok(value) => value,
            Err(_) => Scalar::Null,
        },
        ResolvedProj::Degrees { input, .. } => match degrees_scalar(table, row, input) {
            Ok(value) => value,
            Err(_) => Scalar::Null,
        },
        ResolvedProj::Radians { input, .. } => match radians_scalar(table, row, input) {
            Ok(value) => value,
            Err(_) => Scalar::Null,
        },
        ResolvedProj::Cot { input, .. } => match cot_scalar(table, row, input) {
            Ok(value) => value,
            Err(_) => Scalar::Null,
        },
        ResolvedProj::Typeof { name, .. } => Scalar::Text(name.clone()),
        ResolvedProj::Not { input, .. } => match input {
            NotInput::Const(value) => Scalar::Boolean(*value),
            NotInput::Column(index) => match &table.columns[*index][row] {
                Scalar::Boolean(value) => Scalar::Boolean(!value),
                _ => Scalar::Boolean(true),
            },
        },
        ResolvedProj::Sqrt { input, .. } => match sqrt_number(table, row, input) {
            Some(value) => {
                let result = value.sqrt();
                if result.is_nan() {
                    Scalar::Null
                } else {
                    Scalar::Double(result)
                }
            }
            None => Scalar::Null,
        },
        ResolvedProj::Round { input, scale, .. } => match round_row(table, row, input, scale) {
            Some(value) => Scalar::Double(value),
            None => Scalar::Null,
        },
        ResolvedProj::RoundDown { input, scale, .. } => {
            match round_down_row(table, row, input, scale) {
                Some(value) => Scalar::Double(value),
                None => Scalar::Null,
            }
        }
        ResolvedProj::RoundUp { input, scale, .. } => {
            match round_up_row(table, row, input, scale) {
                Some(value) => Scalar::Double(value),
                None => Scalar::Null,
            }
        }
        ResolvedProj::RoundHalfEven { input, scale, .. } => {
            match round_half_even_row(table, row, input, scale) {
                Some(value) => Scalar::Double(value),
                None => Scalar::Null,
            }
        }
        ResolvedProj::Coalesce {
            args, result_tag, ..
        } => coalesce_value(table, row, args, *result_tag),
        ResolvedProj::NullIf {
            args, result_tag, ..
        } => nullif_value(table, row, args, *result_tag),
        ResolvedProj::Cast {
            index, type_tag, ..
        } => cast_scalar(&table.columns[*index][row], *type_tag),
        ResolvedProj::DateAdd {
            period,
            stride,
            timestamp,
            ..
        } => dateadd_value(table, row, *period, stride, *timestamp),
        ResolvedProj::DateDiff {
            period, start, end, ..
        } => datediff_value(table, row, *period, start, end),
        ResolvedProj::Year { value, .. } => match datediff_micros(table, row, value) {
            Some(micros) => Scalar::Int(dateadd_parts(micros).0),
            None => Scalar::Null,
        },
        ResolvedProj::Month { value, .. } => match datediff_micros(table, row, value) {
            Some(micros) => Scalar::Int(dateadd_parts(micros).1 as i32),
            None => Scalar::Null,
        },
        ResolvedProj::Day { value, .. } => match datediff_micros(table, row, value) {
            Some(micros) => Scalar::Int(dateadd_parts(micros).2 as i32),
            None => Scalar::Null,
        },
        ResolvedProj::Hour { value, .. } => match datediff_micros(table, row, value) {
            Some(micros) => Scalar::Int((dateadd_parts(micros).3 / (3_600 * 1_000_000)) as i32),
            None => Scalar::Null,
        },
        ResolvedProj::Minute { value, .. } => match datediff_micros(table, row, value) {
            Some(micros) => Scalar::Int(((dateadd_parts(micros).3 / (60 * 1_000_000)) % 60) as i32),
            None => Scalar::Null,
        },
        ResolvedProj::Second { value, .. } => match datediff_micros(table, row, value) {
            Some(micros) => Scalar::Int(((dateadd_parts(micros).3 / 1_000_000) % 60) as i32),
            None => Scalar::Null,
        },
        ResolvedProj::Millis { value, .. } => match datediff_micros(table, row, value) {
            Some(micros) => Scalar::Int(((dateadd_parts(micros).3 / 1_000) % 1_000) as i32),
            None => Scalar::Null,
        },
        ResolvedProj::Micros { value, .. } => match datediff_micros(table, row, value) {
            Some(micros) => Scalar::Int((dateadd_parts(micros).3 % 1_000) as i32),
            None => Scalar::Null,
        },
        ResolvedProj::DayOfWeek { value, .. } => match datediff_micros(table, row, value) {
            Some(micros) => Scalar::Int(weekday_monday(micros)),
            None => Scalar::Null,
        },
        ResolvedProj::WeekOfYear { value, .. } => match datediff_micros(table, row, value) {
            Some(micros) => Scalar::Int(iso_week(micros)),
            None => Scalar::Null,
        },
        ResolvedProj::DateTrunc { unit, value, .. } => match datediff_micros(table, row, value) {
            Some(micros) => Scalar::Timestamp(date_trunc_micros(unit, micros)),
            None => Scalar::Null,
        },
        ResolvedProj::TimestampFloor {
            unit,
            stride,
            value,
            ..
        } => match datediff_micros(table, row, value) {
            Some(micros) => Scalar::Timestamp(timestamp_floor_micros(*unit, *stride, micros)),
            None => Scalar::Null,
        },
        ResolvedProj::TimestampCeil { unit, value, .. } => match datediff_micros(table, row, value)
        {
            Some(micros) => Scalar::Timestamp(timestamp_ceil_micros(*unit, micros)),
            None => Scalar::Null,
        },
        ResolvedProj::IsLeapYear { value, .. } => {
            let year = datediff_micros(table, row, value).map(|micros| dateadd_parts(micros).0);
            Scalar::Boolean(year.is_some_and(is_leap_year))
        }
        ResolvedProj::DaysInMonth { value, .. } => match datediff_micros(table, row, value) {
            Some(micros) => {
                let (year, month, _, _) = dateadd_parts(micros);
                Scalar::Int(days_in_month(year, month))
            }
            None => Scalar::Null,
        },
        ResolvedProj::ToStr { ops, value, .. } => match datediff_micros(table, row, value) {
            Some(micros) => Scalar::Text(format_to_str(ops, micros)),
            None => Scalar::Null,
        },
        ResolvedProj::Extract { part, value, .. } => match datediff_micros(table, row, value) {
            Some(micros) => extract_value(*part, micros),
            None => Scalar::Null,
        },
        ResolvedProj::Md5 { arg, .. } => match text_of(table, row, arg) {
            Some(text) => Scalar::Text(md5_hex(text.as_bytes())),
            None => Scalar::Null,
        },
        ResolvedProj::Sha1 { arg, .. } => match text_of(table, row, arg) {
            Some(text) => Scalar::Text(sha1_hex(text.as_bytes())),
            None => Scalar::Null,
        },
        ResolvedProj::Sha256 { arg, .. } => match text_of(table, row, arg) {
            Some(text) => Scalar::Text(sha256_hex(text.as_bytes())),
            None => Scalar::Null,
        },
        ResolvedProj::ToDate { arg, pattern, .. } => match text_of(table, row, arg) {
            Some(text) => match parse_timestamp_pattern(pattern, &text) {
                Some(micros) => {
                    let millis = micros / 1_000;
                    if millis == i64::MIN {
                        Scalar::Null
                    } else {
                        Scalar::Date(millis)
                    }
                }
                None => Scalar::Null,
            },
            None => Scalar::Null,
        },
        ResolvedProj::ToTimestamp { arg, pattern, .. } => match text_of(table, row, arg) {
            Some(text) => {
                let micros = match pattern {
                    Some(tokens) => parse_timestamp_pattern(tokens, &text),
                    None => parse_questdb_long(&text).filter(|micros| *micros != i64::MIN),
                };
                match micros {
                    Some(micros) if micros != i64::MIN => Scalar::Timestamp(micros),
                    _ => Scalar::Null,
                }
            }
            None => Scalar::Null,
        },
        ResolvedProj::DayOfWeekSundayFirst { value, .. } => {
            match datediff_micros(table, row, value) {
                Some(micros) => Scalar::Int(sunday_weekday(micros)),
                None => Scalar::Null,
            }
        }
        ResolvedProj::IsEndOfMonth { value, .. } => {
            let end = datediff_micros(table, row, value).is_some_and(|micros| {
                let (year, month, day, _) = dateadd_parts(micros);
                i32::try_from(day).unwrap_or(0) == days_in_month(year, month)
            });
            Scalar::Boolean(end)
        }
        ResolvedProj::Abs { input, .. } => abs_value(table, row, input),
        ResolvedProj::SizePretty { size, .. } => match count_of(table, row, size) {
            Some(size) if size != i64::MIN => Scalar::Text(size_pretty(size)),
            _ => Scalar::Null,
        },
        ResolvedProj::QuoteIdent { arg, .. } => match text_of(table, row, arg) {
            Some(text) => Scalar::Text(quote_ident(&text)),
            None => Scalar::Null,
        },
        ResolvedProj::Pad {
            value,
            width,
            fill,
            from_right,
            ..
        } => {
            let Some(text) = text_of(table, row, value) else {
                return Scalar::Null;
            };
            let Some(width) = count_of(table, row, width) else {
                return Scalar::Null;
            };
            let Ok(width) = i32::try_from(width) else {
                return Scalar::Null;
            };
            if width < 0 {
                return Scalar::Null;
            }
            let fill = match fill {
                None => " ".to_string(),
                Some(fill) => match text_of(table, row, fill) {
                    Some(fill) if !fill.is_empty() => fill,
                    _ => return Scalar::Null,
                },
            };
            Scalar::Text(pad_utf16(&text, width, &fill, *from_right))
        }
        ResolvedProj::SplitPart {
            value,
            delimiter,
            index,
            ..
        } => {
            let Some(index) = *index else {
                return Scalar::Null;
            };
            match (text_of(table, row, value), text_of(table, row, delimiter)) {
                (Some(value), Some(delimiter)) => {
                    Scalar::Text(split_part_utf16(&value, &delimiter, index))
                }
                _ => Scalar::Null,
            }
        }
        ResolvedProj::StrPos {
            value,
            needle,
            needle_null,
            ..
        } => {
            if *needle_null {
                Scalar::Null
            } else {
                match text_of(table, row, value) {
                    None => Scalar::Null,
                    Some(value) => match text_of(table, row, needle) {
                        None => Scalar::Null,
                        Some(needle) => Scalar::Int(strpos_utf16(&value, &needle)),
                    },
                }
            }
        }
        ResolvedProj::StartsWith { value, prefix, .. } => {
            let matched = match (text_of(table, row, value), text_of(table, row, prefix)) {
                (Some(value), Some(prefix)) => value.starts_with(&prefix),
                _ => false,
            };
            Scalar::Boolean(matched)
        }
        ResolvedProj::Replace { mode, .. } => match mode {
            ReplaceMode::Null => Scalar::Null,
            ReplaceMode::Empty => Scalar::Text(String::new()),
            ReplaceMode::Value(arg) => match text_of(table, row, arg) {
                Some(text) => Scalar::Text(text),
                None => Scalar::Null,
            },
            ReplaceMode::Run { value, old, new } => match text_of(table, row, value) {
                None => Scalar::Null,
                Some(value) if value.is_empty() => Scalar::Text(String::new()),
                Some(value) => match (text_of(table, row, old), text_of(table, row, new)) {
                    (Some(old), Some(new)) => Scalar::Text(replace_utf16(&value, &old, &new)),
                    _ => Scalar::Null,
                },
            },
        },
        ResolvedProj::Trim { arg, end, .. } => match text_of(table, row, arg) {
            Some(text) => Scalar::Text(trim_ascii_space(&text, *end)),
            None => Scalar::Null,
        },
    }
}

fn power_value(table: &Table, row: usize, base: &SqrtInput, exponent: &SqrtInput) -> Scalar {
    let Some(exponent) = sqrt_number(table, row, exponent) else {
        return Scalar::Null;
    };
    let base = match sqrt_number(table, row, base) {
        Some(value) => value,
        None => {
            if exponent == 0.0 {
                return Scalar::Double(1.0);
            }
            return Scalar::Null;
        }
    };
    let result = base.powf(exponent);
    if result.is_finite() {
        Scalar::Double(result)
    } else {
        Scalar::Null
    }
}

fn log_value(table: &Table, row: usize, input: &SqrtInput, function: fn(f64) -> f64) -> Scalar {
    match sqrt_number(table, row, input) {
        Some(value) => {
            let result = function(value);
            if result.is_nan() {
                Scalar::Null
            } else {
                Scalar::Double(result)
            }
        }
        None => Scalar::Null,
    }
}

fn sin_scalar(table: &Table, row: usize, input: &SinInput) -> Result<Scalar, Error> {
    real_apply(table, row, input, f64::sin)
}

fn cos_scalar(table: &Table, row: usize, input: &SinInput) -> Result<Scalar, Error> {
    real_apply(table, row, input, f64::cos)
}

fn tan_scalar(table: &Table, row: usize, input: &SinInput) -> Result<Scalar, Error> {
    real_apply(table, row, input, f64::tan)
}

fn asin_scalar(table: &Table, row: usize, input: &SinInput) -> Result<Scalar, Error> {
    real_apply(table, row, input, f64::asin)
}

fn acos_scalar(table: &Table, row: usize, input: &SinInput) -> Result<Scalar, Error> {
    real_apply(table, row, input, f64::acos)
}

fn atan_scalar(table: &Table, row: usize, input: &SinInput) -> Result<Scalar, Error> {
    real_apply(table, row, input, f64::atan)
}

fn degrees_scalar(table: &Table, row: usize, input: &SinInput) -> Result<Scalar, Error> {
    real_apply(table, row, input, degrees_of)
}

fn degrees_of(radians: f64) -> f64 {
    radians.to_degrees()
}

fn radians_scalar(table: &Table, row: usize, input: &SinInput) -> Result<Scalar, Error> {
    real_apply(table, row, input, radians_of)
}

fn radians_of(degrees: f64) -> f64 {
    degrees.to_radians()
}

fn cot_scalar(table: &Table, row: usize, input: &SinInput) -> Result<Scalar, Error> {
    real_apply(table, row, input, cot_of)
}

fn cot_of(radians: f64) -> f64 {
    let result = 1.0 / radians.tan();
    if result.is_finite() {
        result
    } else {
        f64::NAN
    }
}

fn atan2_scalar(table: &Table, row: usize, y: &SinInput, x: &SinInput) -> Result<Scalar, Error> {
    let y = sin_number(table, row, y)?;
    let x = sin_number(table, row, x)?;
    Ok(match (y, x) {
        (Some(y), Some(x)) => Scalar::Double(y.atan2(x)),
        _ => Scalar::Null,
    })
}

fn real_apply(
    table: &Table,
    row: usize,
    input: &SinInput,
    function: fn(f64) -> f64,
) -> Result<Scalar, Error> {
    Ok(match sin_number(table, row, input)? {
        Some(value) => Scalar::Double(function(value)),
        None => Scalar::Null,
    })
}

fn sin_number(table: &Table, row: usize, input: &SinInput) -> Result<Option<f64>, Error> {
    match input {
        SinInput::Null => Ok(None),
        SinInput::Number(number) => Ok(Some(*number)),
        SinInput::Column { index, tag } => sin_column(table, row, *index, *tag),
    }
}

fn sin_column(table: &Table, row: usize, index: usize, tag: i32) -> Result<Option<f64>, Error> {
    match &table.columns[index][row] {
        Scalar::Null => Ok(None),
        Scalar::Byte(number) => Ok(Some(f64::from(*number))),
        Scalar::Short(number) => Ok(Some(f64::from(*number))),
        Scalar::Int(number) => Ok(Some(f64::from(*number))),
        Scalar::Long(number) => Ok(Some(*number as f64)),
        Scalar::Float(number) => Ok(Some(f64::from(*number))),
        Scalar::Double(number) => Ok(Some(*number)),
        Scalar::Date(number) | Scalar::Timestamp(number) => Ok(Some(*number as f64)),
        Scalar::Char(unit) => {
            let ch = char::from_u32(u32::from(*unit)).unwrap_or('\u{0}');
            match parse_questdb_f64(&ch.to_string()) {
                Some(number) => Ok(Some(number)),
                None => Err(Error::new(format!(
                    "inconvertible value: {ch} [CHAR -> DOUBLE]"
                ))),
            }
        }
        Scalar::Text(text) => {
            let kind = if tag == qdb_types::TAG_VARCHAR {
                "VARCHAR"
            } else {
                "STRING"
            };
            match parse_questdb_f64(text) {
                Some(number) => Ok(Some(number)),
                None => Err(Error::new(format!(
                    "inconvertible value: `{text}` [{kind} -> DOUBLE]"
                ))),
            }
        }
        _ => Err(Error::new("internal: sin argument")),
    }
}

fn parse_questdb_f64(text: &str) -> Option<f64> {
    let trimmed = text.trim_matches(|ch: char| ch <= ' ');
    if trimmed.is_empty() {
        return None;
    }
    match trimmed {
        "NaN" | "+NaN" | "-NaN" => return Some(f64::NAN),
        "Infinity" | "+Infinity" => return Some(f64::INFINITY),
        "-Infinity" => return Some(f64::NEG_INFINITY),
        _ => {}
    }
    let body = if trimmed.len() > 1 {
        let bytes = trimmed.as_bytes();
        let last = bytes[bytes.len() - 1];
        if last == b'd' || last == b'D' {
            &trimmed[..trimmed.len() - 1]
        } else {
            trimmed
        }
    } else {
        trimmed
    };
    let value = body.parse::<f64>().ok()?;
    if !value.is_finite() {
        return None;
    }
    if value == 0.0 && !sin_significand_is_zero(body) {
        return None;
    }
    Some(value)
}

fn sin_significand_is_zero(body: &str) -> bool {
    let digits = body
        .trim_start_matches(['+', '-'])
        .split(['e', 'E'])
        .next()
        .unwrap_or("");
    digits.contains('0') && digits.chars().all(|ch| ch == '0' || ch == '.')
}

fn sqrt_number(table: &Table, row: usize, input: &SqrtInput) -> Option<f64> {
    match input {
        SqrtInput::Null => None,
        SqrtInput::Long(number) => Some(*number as f64),
        SqrtInput::Double(number) => Some(*number),
        SqrtInput::Column { index } => match &table.columns[*index][row] {
            Scalar::Null => None,
            Scalar::Byte(number) => Some(f64::from(*number)),
            Scalar::Short(number) => Some(f64::from(*number)),
            Scalar::Int(number) => Some(f64::from(*number)),
            Scalar::Long(number) => Some(*number as f64),
            Scalar::Float(number) => Some(f64::from(*number)),
            Scalar::Double(number) => Some(*number),
            _ => None,
        },
    }
}

fn sign_value(table: &Table, row: usize, input: &SignInput) -> Scalar {
    match input {
        SignInput::Byte(number) => Scalar::Byte(number.signum()),
        SignInput::Int(number) => Scalar::Int(number.signum()),
        SignInput::Long(number) => Scalar::Long(number.signum()),
        SignInput::Double(number) => Scalar::Double(sign_f64(*number)),
        SignInput::Column { index } => match &table.columns[*index][row] {
            Scalar::Null => Scalar::Null,
            Scalar::Byte(number) => Scalar::Byte(number.signum()),
            Scalar::Short(number) => Scalar::Short(number.signum()),
            Scalar::Int(number) => Scalar::Int(number.signum()),
            Scalar::Long(number) => Scalar::Long(number.signum()),
            Scalar::Float(number) => Scalar::Float(sign_f32(*number)),
            Scalar::Double(number) => Scalar::Double(sign_f64(*number)),
            _ => Scalar::Null,
        },
    }
}

fn sign_f64(value: f64) -> f64 {
    if value == 0.0 || value.is_nan() {
        0.0
    } else if value.is_sign_negative() {
        -1.0
    } else {
        1.0
    }
}

fn sign_f32(value: f32) -> f32 {
    if value.is_nan() || value == 0.0 {
        value
    } else if value.is_sign_negative() {
        -1.0
    } else {
        1.0
    }
}

fn ceil_value(table: &Table, row: usize, input: &FloorInput, wide: bool) -> Scalar {
    if wide {
        return match floor_f64(table, row, input) {
            Some(value) => Scalar::Double(value.ceil()),
            None => Scalar::Null,
        };
    }
    match floor_f32(table, row, input) {
        Some(value) => Scalar::Float(value.ceil()),
        None => Scalar::Null,
    }
}

fn floor_value(table: &Table, row: usize, input: &FloorInput, wide: bool) -> Scalar {
    if wide {
        return match floor_f64(table, row, input) {
            Some(value) => Scalar::Double(value.floor()),
            None => Scalar::Null,
        };
    }
    match floor_f32(table, row, input) {
        Some(value) => Scalar::Float(value.floor()),
        None => Scalar::Null,
    }
}

fn floor_f64(table: &Table, row: usize, input: &FloorInput) -> Option<f64> {
    match input {
        FloorInput::Null => None,
        FloorInput::Long(number) => Some(*number as f64),
        FloorInput::Double(number) => Some(*number),
        FloorInput::Column { index } => match &table.columns[*index][row] {
            Scalar::Null => None,
            Scalar::Long(number) => Some(*number as f64),
            Scalar::Double(number) => Some(*number),
            _ => None,
        },
    }
}

fn floor_f32(table: &Table, row: usize, input: &FloorInput) -> Option<f32> {
    match input {
        FloorInput::Null => None,
        FloorInput::Long(number) => Some(*number as f32),
        FloorInput::Double(_) => None,
        FloorInput::Column { index } => match &table.columns[*index][row] {
            Scalar::Null => None,
            Scalar::Byte(number) => Some(f32::from(*number)),
            Scalar::Short(number) => Some(f32::from(*number)),
            Scalar::Int(number) => Some(*number as f32),
            Scalar::Float(number) => Some(*number),
            _ => None,
        },
    }
}

fn round_row(table: &Table, row: usize, input: &RoundInput, scale: &RoundScale) -> Option<f64> {
    let scale = match scale {
        RoundScale::Null => return None,
        RoundScale::Zero => 0,
        RoundScale::Fixed(scale) => *scale,
        RoundScale::Column(index) => match &table.columns[*index][row] {
            Scalar::Null => return None,
            Scalar::Byte(number) => i32::from(*number),
            Scalar::Short(number) => i32::from(*number),
            Scalar::Int(number) => *number,
            _ => return None,
        },
    };
    let value = round_number(table, row, input)?;
    round_half_up(value, scale)
}

fn round_number(table: &Table, row: usize, input: &RoundInput) -> Option<f64> {
    match input {
        RoundInput::Null => None,
        RoundInput::Long(number) => Some(*number as f64),
        RoundInput::Double(number) => Some(*number),
        RoundInput::Column { index, .. } => match &table.columns[*index][row] {
            Scalar::Null => None,
            Scalar::Byte(number) => Some(f64::from(*number)),
            Scalar::Short(number) => Some(f64::from(*number)),
            Scalar::Int(number) => Some(f64::from(*number)),
            Scalar::Long(number) => Some(*number as f64),
            Scalar::Float(number) => Some(f64::from(*number)),
            Scalar::Double(number) => Some(*number),
            _ => None,
        },
    }
}

fn round_half_even_row(
    table: &Table,
    row: usize,
    input: &RoundInput,
    scale: &RoundScale,
) -> Option<f64> {
    let scale = match scale {
        RoundScale::Null => return None,
        RoundScale::Zero => 0,
        RoundScale::Fixed(scale) => *scale,
        RoundScale::Column(index) => match &table.columns[*index][row] {
            Scalar::Null => return None,
            Scalar::Byte(number) => i32::from(*number),
            Scalar::Short(number) => i32::from(*number),
            Scalar::Int(number) => *number,
            _ => return None,
        },
    };
    if !round_scale_in_range(scale) {
        return None;
    }
    let value = round_number(table, row, input)?;
    if !value.is_finite() {
        return None;
    }
    Some(round_half_even_value(value, scale))
}

fn round_half_even_value(value: f64, scale: i32) -> f64 {
    if value > 0.0 {
        round_half_even0(value, scale)
    } else {
        -round_half_even0(-value, scale)
    }
}

fn round_half_even0(value: f64, scale: i32) -> f64 {
    if scale > 0 {
        round_half_even_positive(value, scale)
    } else {
        round_half_even_negative(value, -scale)
    }
}

fn round_half_even_positive(value: f64, scale: i32) -> f64 {
    let factor = pow10(scale) as f64;
    let digits = (value * factor * pow10(2) as f64 + 1e-15) as i64;
    let remainder = digits % 100;
    if remainder < 50 || (remainder == 50 && (value * factor) as i64 & 1 == 0) {
        round_down_positive(value, scale)
    } else {
        round_up_positive(value, scale)
    }
}

fn round_half_even_negative(value: f64, scale: i32) -> f64 {
    let factor = pow10_neg(scale);
    let digits = (value * factor * pow10(2) as f64 + 1e-15) as i64;
    let remainder = digits % 100;
    if remainder < 50 || (remainder == 50 && (value * factor) as i64 & 1 == 0) {
        round_down_negative(value, scale)
    } else {
        round_up_negative(value, scale)
    }
}

fn round_up_row(table: &Table, row: usize, input: &RoundInput, scale: &RoundScale) -> Option<f64> {
    let scale = match scale {
        RoundScale::Null => return None,
        RoundScale::Zero => 0,
        RoundScale::Fixed(scale) => *scale,
        RoundScale::Column(index) => match &table.columns[*index][row] {
            Scalar::Null => return None,
            Scalar::Byte(number) => i32::from(*number),
            Scalar::Short(number) => i32::from(*number),
            Scalar::Int(number) => *number,
            _ => return None,
        },
    };
    if !round_down_scale_in_range(scale) {
        return None;
    }
    let value = round_number(table, row, input)?;
    if !value.is_finite() {
        return None;
    }
    let sign = value.to_bits() & (1_u64 << 63);
    let magnitude = if scale < 0 {
        round_up_negative(value.abs(), -scale)
    } else {
        round_up_positive(value.abs(), scale)
    };
    Some(f64::from_bits(magnitude.to_bits() | sign))
}

fn round_down_row(
    table: &Table,
    row: usize,
    input: &RoundInput,
    scale: &RoundScale,
) -> Option<f64> {
    let scale = match scale {
        RoundScale::Null => return None,
        RoundScale::Zero => 0,
        RoundScale::Fixed(scale) => *scale,
        RoundScale::Column(index) => match &table.columns[*index][row] {
            Scalar::Null => return None,
            Scalar::Byte(number) => i32::from(*number),
            Scalar::Short(number) => i32::from(*number),
            Scalar::Int(number) => *number,
            _ => return None,
        },
    };
    if !round_down_scale_in_range(scale) {
        return None;
    }
    let value = round_number(table, row, input)?;
    if !value.is_finite() {
        return None;
    }
    let sign = value.to_bits() & (1_u64 << 63);
    let magnitude = if scale < 0 {
        round_down_negative(value.abs(), -scale)
    } else {
        round_down_positive(value.abs(), scale)
    };
    Some(f64::from_bits(magnitude.to_bits() | sign))
}

fn round_scale_in_range(scale: i32) -> bool {
    scale > -18 && scale + 2 < 18
}

fn round_down_scale_in_range(scale: i32) -> bool {
    scale > -18 && scale < 18
}

fn round_half_up(value: f64, scale: i32) -> Option<f64> {
    if !value.is_finite() {
        return None;
    }
    if scale == 0 {
        return Some((value + 0.5).floor());
    }
    if !round_scale_in_range(scale) {
        return None;
    }
    let sign = value.to_bits() & (1_u64 << 63);
    let magnitude = if scale > 0 {
        round_half_up_positive(value.abs(), scale)
    } else {
        round_half_up_negative(value.abs(), -scale)
    };
    Some(f64::from_bits(magnitude.to_bits() | sign))
}

fn round_half_up_positive(value: f64, scale: i32) -> f64 {
    let factor = pow10(scale + 2) as f64;
    let digits = ((value + 1e-15) * factor) as i64;
    if digits % 100 < 50 {
        round_down_positive(value, scale)
    } else {
        round_up_positive(value, scale)
    }
}

fn round_half_up_negative(value: f64, scale: i32) -> f64 {
    let digits = (value * pow10_neg(scale) * pow10(2) as f64 + 1e-15) as i64;
    if digits % 100 < 50 {
        round_down_negative(value, scale)
    } else {
        round_up_negative(value, scale)
    }
}

fn round_down_positive(value: f64, scale: i32) -> f64 {
    ((value + 1e-15) * pow10(scale) as f64) as i64 as f64 * pow10_neg(scale)
}

fn round_up_positive(value: f64, scale: i32) -> f64 {
    (value * pow10(scale) as f64 + 1.0 - 1e-15) as i64 as f64 * pow10_neg(scale)
}

fn round_down_negative(value: f64, scale: i32) -> f64 {
    ((value + 1e-15) * pow10_neg(scale)) as i64 as f64 * pow10(scale) as f64
}

fn round_up_negative(value: f64, scale: i32) -> f64 {
    (value * pow10_neg(scale) + 1.0 - 1e-15) as i64 as f64 * pow10(scale) as f64
}

fn pow10(scale: i32) -> i64 {
    10i64.pow(scale as u32)
}

fn pow10_neg(scale: i32) -> f64 {
    10f64.powi(-scale)
}

fn abs_value(table: &Table, row: usize, input: &AbsInput) -> Scalar {
    match input {
        AbsInput::Null => Scalar::Null,
        AbsInput::Long(number) => match i32::try_from(*number) {
            Ok(number) => Scalar::Int(number.wrapping_abs()),
            Err(_) => Scalar::Long(number.wrapping_abs()),
        },
        AbsInput::Double(number) => Scalar::Double(number.abs()),
        AbsInput::Column { index, .. } => match &table.columns[*index][row] {
            Scalar::Null => Scalar::Null,
            Scalar::Byte(number) => Scalar::Short(i16::from(*number).wrapping_abs()),
            Scalar::Short(number) => Scalar::Short(number.wrapping_abs()),
            Scalar::Int(number) => Scalar::Int(number.wrapping_abs()),
            Scalar::Long(number) => Scalar::Long(number.wrapping_abs()),
            Scalar::Float(number) => Scalar::Double(f64::from(number.abs())),
            Scalar::Double(number) => Scalar::Double(number.abs()),
            _ => Scalar::Null,
        },
    }
}

fn size_pretty(size: i64) -> String {
    const SCALE: [char; 8] = ['B', 'K', 'M', 'G', 'T', 'P', 'E', 'Z'];
    let mut band = (63 - size.leading_zeros() as i32) / 10;
    if band < 0 {
        band = 0;
    }
    let scale = 1i64 << (band * 10);
    let value = (size as f32) / (scale as f32);
    let mut text = append_scaled_f32(value, 1);
    text.push(' ');
    text.push(SCALE[band as usize]);
    if band > 0 {
        text.push_str("iB");
    }
    text
}

fn append_scaled_f32(value: f32, scale: i32) -> String {
    if value.is_infinite() && value.is_sign_positive() {
        return "Infinity".to_string();
    }
    if value.is_infinite() {
        return "-Infinity".to_string();
    }
    if value.is_nan() {
        return "NaN".to_string();
    }
    let mut out = String::new();
    let mut magnitude = value;
    if magnitude.is_sign_negative() {
        out.push('-');
        magnitude = -magnitude;
    }
    let mut factor = 10i32.pow(scale as u32);
    let scaled = (magnitude * factor as f32 + 0.5) as i32;
    let mut target = scale + 1;
    while target < 11 {
        let Some(next) = factor.checked_mul(10) else {
            break;
        };
        if next > scaled {
            break;
        }
        factor = next;
        target += 1;
    }
    while target > 0 {
        if target == scale {
            out.push('.');
        }
        target -= 1;
        let digit = scaled / factor % 10;
        out.push(char::from(b'0' + digit as u8));
        factor /= 10;
    }
    out
}

fn quote_ident(text: &str) -> String {
    let plain = text
        .chars()
        .all(|ch| ch.is_alphabetic() || ch.is_ascii_digit() || ch == '_' || ch == '$');
    if plain {
        return text.to_string();
    }
    let mut quoted = String::from("\"");
    for ch in text.chars() {
        if ch == '"' {
            quoted.push('"');
        }
        quoted.push(ch);
    }
    quoted.push('"');
    quoted
}

fn pad_utf16(text: &str, width: i32, fill: &str, from_right: bool) -> String {
    let units: Vec<u16> = text.encode_utf16().collect();
    let width = width as usize;
    if width <= units.len() {
        let slice = if from_right {
            &units[units.len() - width..]
        } else {
            &units[..width]
        };
        return String::from_utf16(slice).unwrap_or_else(|_| String::from_utf16_lossy(slice));
    }
    let fill_units: Vec<u16> = fill.encode_utf16().collect();
    let need = width - units.len();
    let mut out = Vec::with_capacity(width);
    let copies = need / fill_units.len();
    let rest = need % fill_units.len();
    if from_right {
        out.extend_from_slice(&units);
    }
    for _ in 0..copies {
        out.extend_from_slice(&fill_units);
    }
    out.extend_from_slice(&fill_units[..rest]);
    if !from_right {
        out.extend_from_slice(&units);
    }
    String::from_utf16(&out).unwrap_or_else(|_| String::from_utf16_lossy(&out))
}

fn split_part_utf16(value: &str, delimiter: &str, index: i32) -> String {
    if index == 0 {
        return String::new();
    }
    let seq: Vec<u16> = value.encode_utf16().collect();
    let term: Vec<u16> = delimiter.encode_utf16().collect();
    let len = i32::try_from(seq.len()).unwrap_or(i32::MAX);
    let (start, end) = if index > 0 {
        let start = if index == 1 {
            0
        } else {
            let found = index_of_nth(&seq, 0, len, &term, index - 1);
            if found < 0 {
                return String::new();
            }
            found + term.len() as i32
        };
        let end = index_of_first(&seq, start, len, &term);
        (start, if end < 0 { len } else { end })
    } else {
        let end = if index == -1 {
            len
        } else {
            let found = index_of_nth(&seq, 0, len, &term, index + 1);
            if found < 0 {
                return String::new();
            }
            found
        };
        let found = index_of_nth(&seq, 0, end, &term, -1);
        let start = if found < 0 {
            0
        } else {
            found + term.len() as i32
        };
        (start, end)
    };
    utf16_slice(&seq, start, end)
}

fn index_of_first(seq: &[u16], lo: i32, hi: i32, term: &[u16]) -> i32 {
    let term_len = term.len() as i32;
    if term_len == 0 {
        return 0;
    }
    let first = term[0];
    let max = hi - term_len;
    let mut index = lo;
    while index <= max {
        if seq[index as usize] != first {
            loop {
                index += 1;
                if index > max || seq[index as usize] == first {
                    break;
                }
            }
        }
        if index <= max {
            let mut cursor = index + 1;
            let end = cursor + term_len - 1;
            let mut term_index = 1i32;
            while cursor < end && seq[cursor as usize] == term[term_index as usize] {
                term_index += 1;
                cursor += 1;
            }
            if cursor == end {
                return index;
            }
        }
        index += 1;
    }
    -1
}

fn index_of_nth(seq: &[u16], lo: i32, hi: i32, term: &[u16], occurrence: i32) -> i32 {
    let term_len = term.len() as i32;
    if term_len == 0 {
        return 0;
    }
    if occurrence == 0 {
        return -1;
    }
    let mut found = -1i32;
    let mut count = 0i32;
    if occurrence > 0 {
        let mut index = lo;
        while index < hi {
            if found == -1 {
                if hi - index < term_len {
                    return -1;
                }
                if seq[index as usize] == term[0] {
                    found = index;
                }
            } else if seq[index as usize] != term[(index - found) as usize] {
                index = found;
                found = -1;
            }
            if found != -1 && index - found == term_len - 1 {
                count += 1;
                if count == occurrence {
                    return found;
                }
                found = -1;
            }
            index += 1;
        }
    } else {
        let mut index = hi - 1;
        while index >= lo {
            if found == -1 {
                if index - lo + 1 < term_len {
                    return -1;
                }
                if seq[index as usize] == term[(term_len - 1) as usize] {
                    found = index;
                }
            } else if seq[index as usize] != term[(term_len - 1 + index - found) as usize] {
                index = found;
                found = -1;
            }
            if found != -1 && found - index == term_len - 1 {
                count -= 1;
                if count == occurrence {
                    return found + 1 - term_len;
                }
                found = -1;
            }
            index -= 1;
        }
    }
    -1
}

fn utf16_slice(units: &[u16], start: i32, end: i32) -> String {
    if start < 0 || end < start {
        return String::new();
    }
    let start = start as usize;
    let end = (end as usize).min(units.len());
    if start >= end || start > units.len() {
        return String::new();
    }
    let slice = &units[start..end];
    String::from_utf16(slice).unwrap_or_else(|_| String::from_utf16_lossy(slice))
}

fn strpos_utf16(value: &str, needle: &str) -> i32 {
    let value_units: Vec<u16> = value.encode_utf16().collect();
    let needle_units: Vec<u16> = needle.encode_utf16().collect();
    if needle_units.is_empty() {
        return 1;
    }
    if value_units.len() < needle_units.len() {
        return 0;
    }
    let last = value_units.len() - needle_units.len();
    for index in 0..=last {
        if value_units[index..index + needle_units.len()] == needle_units[..] {
            return i32::try_from(index + 1).unwrap_or(i32::MAX);
        }
    }
    0
}

fn replace_utf16(value: &str, term: &str, with: &str) -> String {
    if term.is_empty() {
        return value.to_string();
    }
    let value_units: Vec<u16> = value.encode_utf16().collect();
    let term_units: Vec<u16> = term.encode_utf16().collect();
    let with_units: Vec<u16> = with.encode_utf16().collect();
    if value_units.is_empty() || term_units.is_empty() {
        return value.to_string();
    }
    let mut out = Vec::new();
    let mut index = 0;
    while index < value_units.len() {
        let rest = &value_units[index..];
        if rest.starts_with(&term_units) {
            out.extend_from_slice(&with_units);
            index += term_units.len();
        } else if rest.len() < term_units.len() && rest[0] == term_units[0] {
            out.extend_from_slice(rest);
            break;
        } else {
            out.push(value_units[index]);
            index += 1;
        }
    }
    String::from_utf16(&out).unwrap_or_else(|_| String::from_utf16_lossy(&out))
}

fn trim_ascii_space(text: &str, end: TrimEnd) -> String {
    match end {
        TrimEnd::Both => text.trim_matches(' ').to_string(),
        TrimEnd::Left => text.trim_start_matches(' ').to_string(),
        TrimEnd::Right => text.trim_end_matches(' ').to_string(),
    }
}

fn substring_utf16(text: &str, raw_start: i64, len: i64) -> String {
    let Ok(raw_start) = i32::try_from(raw_start) else {
        return String::new();
    };
    let Ok(len) = i32::try_from(len) else {
        return String::new();
    };
    if len <= 0 {
        return String::new();
    }
    let units: Vec<u16> = text.encode_utf16().collect();
    let start = raw_start.wrapping_sub(1);
    let start = if start < 0 { 0 } else { start };
    let end = raw_start.wrapping_add(len).wrapping_sub(1);
    let str_len = i32::try_from(units.len()).unwrap_or(i32::MAX);
    let end = if end > str_len { str_len } else { end };
    if start >= end {
        return String::new();
    }
    let slice = &units[start as usize..end as usize];
    String::from_utf16(slice).unwrap_or_else(|_| String::from_utf16_lossy(slice))
}

fn count_of(table: &Table, row: usize, count: &CountArg) -> Option<i64> {
    match count {
        CountArg::Null => None,
        CountArg::Fixed(number) => Some(*number),
        CountArg::ColumnInt { index } => match &table.columns[*index][row] {
            Scalar::Null => None,
            value => as_i64(value).ok(),
        },
        CountArg::ColumnSymbol { index, keys } => {
            let value = &table.columns[*index][row];
            if value.is_null() {
                None
            } else {
                keys.iter()
                    .position(|key| key == value)
                    .map(|index| index as i64)
            }
        }
    }
}

fn take_chars(text: &str, count: i64, from_right: bool) -> String {
    let chars: Vec<char> = text.chars().collect();
    let len = chars.len() as i64;
    let mut count = count;
    if count < 0 {
        count += len;
    }
    if count < 0 {
        count = 0;
    }
    let count = usize::try_from(count)
        .unwrap_or(usize::MAX)
        .min(chars.len());
    let slice = if from_right {
        &chars[chars.len() - count..]
    } else {
        &chars[..count]
    };
    slice.iter().collect()
}

fn text_of(table: &Table, row: usize, arg: &ResolvedArg) -> Option<String> {
    match arg {
        ResolvedArg::Null => None,
        ResolvedArg::Text(text) => Some(text.clone()),
        ResolvedArg::Column { index, .. } => match &table.columns[*index][row] {
            Scalar::Text(text) => Some(text.clone()),
            Scalar::Char(0) => None,
            Scalar::Char(unit) => char::from_u32(u32::from(*unit)).map(|unit| unit.to_string()),
            _ => None,
        },
    }
}

fn text_length(table: &Table, row: usize, arg: &ResolvedArg, bytes: bool) -> i32 {
    let text = match arg {
        ResolvedArg::Null => None,
        ResolvedArg::Text(text) => Some(text.as_str()),
        ResolvedArg::Column { index, tag } => match &table.columns[*index][row] {
            Scalar::Text(text) => Some(text.as_str()),
            Scalar::Char(0) => None,
            Scalar::Char(unit) => {
                let Some(ch) = char::from_u32(u32::from(*unit)) else {
                    return -1;
                };
                return if bytes {
                    i32::try_from(ch.len_utf8()).unwrap_or(i32::MAX)
                } else {
                    1
                };
            }
            _ if *tag == qdb_types::TAG_CHAR => None,
            _ => None,
        },
    };
    match text {
        Some(text) if bytes => i32::try_from(text.len()).unwrap_or(i32::MAX),
        Some(text) => i32::try_from(text.chars().count()).unwrap_or(i32::MAX),
        None => -1,
    }
}

/// QuestDB `concat` stringifies each argument and skips a SQL `NULL` literal or a text null.
fn cast_concat(value: &Scalar, tag: i32) -> String {
    match tag {
        qdb_types::TAG_STRING | qdb_types::TAG_SYMBOL | qdb_types::TAG_VARCHAR => match value {
            Scalar::Text(text) => text.clone(),
            _ => String::new(),
        },
        qdb_types::TAG_CHAR => match value {
            Scalar::Char(unit) => char::from_u32(u32::from(*unit))
                .map(|unit| unit.to_string())
                .unwrap_or_default(),
            _ => String::new(),
        },
        qdb_types::TAG_BOOLEAN => match value {
            Scalar::Boolean(bit) => {
                if *bit {
                    "true".to_string()
                } else {
                    "false".to_string()
                }
            }
            _ => String::new(),
        },
        qdb_types::TAG_BYTE
        | qdb_types::TAG_SHORT
        | qdb_types::TAG_INT
        | qdb_types::TAG_LONG
        | qdb_types::TAG_DATE => match value {
            Scalar::Null => "null".to_string(),
            Scalar::Byte(number) => number.to_string(),
            Scalar::Short(number) => number.to_string(),
            Scalar::Int(number) => number.to_string(),
            Scalar::Long(number) => number.to_string(),
            Scalar::Date(number) => number.to_string(),
            _ => "null".to_string(),
        },
        qdb_types::TAG_FLOAT | qdb_types::TAG_DOUBLE => match value {
            Scalar::Float(number) => format_f64(f64::from(*number)),
            Scalar::Double(number) => format_f64(*number),
            _ => "NaN".to_string(),
        },
        qdb_types::TAG_TIMESTAMP => match value {
            Scalar::Timestamp(micros) => format_timestamp_micros(*micros),
            _ => String::new(),
        },
        _ => String::new(),
    }
}

pub fn render_tsv(result: &QueryResult) -> String {
    let mut out = result.columns.join("\t");
    out.push('\n');
    for row in &result.rows {
        for (index, value) in row.iter().enumerate() {
            if index > 0 {
                out.push('\t');
            }
            out.push_str(&value.to_string());
        }
        out.push('\n');
    }
    out
}

fn execute_aggregate(
    table: &Table,
    query: &Query,
    aggregate: &AggregateExpr,
) -> Result<QueryResult, Error> {
    for order in &query.order_by {
        if !order.column.eq_ignore_ascii_case(&aggregate.label) {
            return Err(Error::new(format!(
                "ORDER BY expressions must appear in select list. Invalid column: {}",
                order.column
            )));
        }
    }
    let input = aggregate_input(table, aggregate)?;
    let mut accumulator = start_accumulator(aggregate, &input);
    for row in 0..table.row_count() {
        if let Some(filter) = &query.filter {
            if !row_matches(table, row, filter)? {
                continue;
            }
        }
        feed(&mut accumulator, &table.columns, row, &input)?;
    }
    let mut row_ids = vec![0];
    if let Some(limit) = query.limit {
        if limit.lo < 0 && limit.hi > 0 && limit_follows_timestamp_order(table, query)? {
            return Err(Error::new("LIMIT <negative>, <positive> is not allowed"));
        }
        apply_limit(&mut row_ids, limit.lo, limit.hi);
    }
    let rows = if row_ids.is_empty() {
        Vec::new()
    } else {
        vec![vec![accumulator_value(&accumulator)?]]
    };
    Ok(QueryResult {
        columns: vec![aggregate.label.clone()],
        rows,
    })
}

fn execute_group(
    table: &Table,
    query: &Query,
    grouped: Option<&GroupedSelect>,
    aggregate: &AggregateExpr,
) -> Result<QueryResult, Error> {
    let group_name = query
        .group_by
        .as_deref()
        .ok_or_else(|| Error::new("unsupported: aggregate mixed with other select expressions"))?;
    let key_index = if let Some(grouped) = grouped {
        let select_index = table
            .column_index(&grouped.key)
            .ok_or_else(|| Error::new(format!("Invalid column: {}", grouped.key)))?;
        let group_index = table
            .column_index(group_name)
            .ok_or_else(|| Error::new(format!("Invalid column: {group_name}")))?;
        if select_index != group_index {
            return Err(Error::new(
                "column must appear in GROUP BY clause or aggregate function",
            ));
        }
        select_index
    } else {
        table
            .column_index(group_name)
            .ok_or_else(|| Error::new(format!("Invalid column: {group_name}")))?
    };
    for order in &query.order_by {
        let by_aggregate = order.column.eq_ignore_ascii_case(&aggregate.label);
        let by_key = order.column.eq_ignore_ascii_case(group_name);
        if !by_aggregate && !by_key {
            return Err(Error::new(format!(
                "ORDER BY expressions must appear in select list. Invalid column: {}",
                order.column
            )));
        }
    }
    let input = aggregate_input(table, aggregate)?;
    if aggregate.func == AggFunc::CountDistinct
        && matches!(
            input.tag,
            qdb_types::TAG_BOOLEAN | qdb_types::TAG_FLOAT | qdb_types::TAG_DOUBLE
        )
    {
        return Err(Error::new(format!(
            "there is no matching function `count_distinct` with the argument types: ({})",
            qdb_types::type_name(input.tag)
        )));
    }
    let value_tag = aggregate_order_tag(&input);
    let mut groups: Vec<(Scalar, Accumulator)> = Vec::new();
    for row in 0..table.row_count() {
        if let Some(filter) = &query.filter {
            if !row_matches(table, row, filter)? {
                continue;
            }
        }
        let key = table.columns[key_index][row].clone();
        if let Some(group) = groups.iter_mut().find(|(found, _)| found == &key) {
            feed(&mut group.1, &table.columns, row, &input)?;
        } else {
            let mut accumulator = start_accumulator(aggregate, &input);
            feed(&mut accumulator, &table.columns, row, &input)?;
            groups.push((key, accumulator));
        }
    }
    for (_, accumulator) in &groups {
        accumulator_value(accumulator)?;
    }
    let tag = table.meta.columns[key_index].tag;
    groups.sort_by(|left, right| {
        for order in &query.order_by {
            let mut ordering = if order.column.eq_ignore_ascii_case(&aggregate.label) {
                compare_asc(&left.1.finish(), &right.1.finish(), value_tag)
            } else {
                compare_asc(&left.0, &right.0, tag)
            };
            if order.descending {
                ordering = ordering.reverse();
            }
            if ordering != Ordering::Equal {
                return ordering;
            }
        }
        Ordering::Equal
    });
    let mut row_ids: Vec<usize> = (0..groups.len()).collect();
    if let Some(limit) = query.limit {
        if limit.lo < 0 && limit.hi > 0 && limit_follows_timestamp_order(table, query)? {
            return Err(Error::new("LIMIT <negative>, <positive> is not allowed"));
        }
        apply_limit(&mut row_ids, limit.lo, limit.hi);
    }
    let columns = match grouped {
        Some(grouped) if grouped.key_at == 0 => {
            vec![grouped.key.clone(), aggregate.label.clone()]
        }
        Some(grouped) => vec![aggregate.label.clone(), grouped.key.clone()],
        None => vec![aggregate.label.clone()],
    };
    let mut rows = Vec::new();
    for index in row_ids {
        let (key, accumulator) = &groups[index];
        let value = accumulator_value(accumulator)?;
        rows.push(match grouped {
            Some(grouped) if grouped.key_at == 0 => vec![key.clone(), value],
            Some(_) => vec![value, key.clone()],
            None => vec![value],
        });
    }
    Ok(QueryResult { columns, rows })
}

struct AggColumn {
    index: Option<usize>,
    tag: i32,
    func: AggFunc,
    /// Symbol texts in key order. `sum` of a symbol adds that key.
    symbol_keys: Vec<Scalar>,
    delimiter: char,
    pair_index: Option<usize>,
    pair_tag: i32,
    /// Significant digits for `approx_median` and `approx_percentile`. One when omitted.
    precision: i32,
    /// Percentile in the closed interval `0.0..=1.0`. `approx_median` uses `0.5`.
    percentile: f64,
}

#[derive(Clone, Copy)]
enum MomentKind {
    Skew,
    SkewPop,
    KurtosisPop,
}

enum Accumulator {
    Count(i64),
    Value(Option<Scalar>),
    Average {
        total: Option<Scalar>,
        count: i64,
    },
    StdDev {
        mean: f64,
        m2: f64,
        count: i64,
        deviation: bool,
        population: bool,
    },
    Distinct(Vec<Scalar>),
    Kahan {
        sum: f64,
        compensation: f64,
        count: i64,
    },
    Neumaier {
        sum: f64,
        compensation: f64,
        count: i64,
    },
    StringAgg {
        text: String,
        delimiter: char,
        has_value: bool,
        distinct: bool,
        seen: Vec<String>,
    },
    Covar {
        mean_y: f64,
        mean_x: f64,
        sum_xy: f64,
        count: i64,
        population: bool,
    },
    Vwap {
        notional: f64,
        volume: f64,
    },
    WeightedAvg {
        notional: f64,
        volume: f64,
        started: bool,
    },
    WeightedStdDev {
        w_sum: f64,
        w_sum2: f64,
        mean: f64,
        s: f64,
        started: bool,
        frequency: bool,
    },
    Twap {
        samples: Vec<(i64, f64)>,
    },
    Sparkline {
        values: Vec<f64>,
        params: Option<SparkParams>,
    },
    Corr {
        mean_y: f64,
        sum_y: f64,
        mean_x: f64,
        sum_x: f64,
        sum_xy: f64,
        count: i64,
        kind: PairKind,
    },
    BoolAnd {
        value: bool,
        count: i64,
    },
    BoolOr {
        value: bool,
        count: i64,
    },
    BitAnd {
        bits: Option<i64>,
        tag: i32,
    },
    BitOr {
        bits: Option<i64>,
        tag: i32,
    },
    BitXor {
        bits: Option<i64>,
        tag: i32,
    },
    GeoMean {
        sum_ln: f64,
        count: i64,
        invalid: bool,
    },
    Skewness {
        mean: f64,
        m2: f64,
        m3: f64,
        m4: f64,
        count: i64,
        kind: MomentKind,
    },
    Mode {
        seen: Vec<(Scalar, i64)>,
    },
    ApproxMedian {
        floating: bool,
        histogram: HdrHistogram,
        samples: Vec<f64>,
        percentile: f64,
    },
    ArgMax {
        value: Scalar,
        key: Option<ArgKey>,
        min: bool,
    },
}

enum ArgKey {
    Long(i64),
    Double(f64),
}

#[derive(Clone, Copy)]
enum PairKind {
    Corr,
    Slope,
    Intercept,
    R2,
}

impl Accumulator {
    fn start(func: AggFunc) -> Self {
        match func {
            AggFunc::Count => Self::Count(0),
            AggFunc::Min
            | AggFunc::Max
            | AggFunc::Sum
            | AggFunc::First
            | AggFunc::Last
            | AggFunc::FirstNotNull
            | AggFunc::LastNotNull => Self::Value(None),
            AggFunc::BitAnd => Self::BitAnd {
                bits: None,
                tag: qdb_types::TAG_LONG,
            },
            AggFunc::BitOr => Self::BitOr {
                bits: None,
                tag: qdb_types::TAG_LONG,
            },
            AggFunc::BitXor => Self::BitXor {
                bits: None,
                tag: qdb_types::TAG_LONG,
            },
            AggFunc::GeoMean => Self::GeoMean {
                sum_ln: 0.0,
                count: 0,
                invalid: false,
            },
            AggFunc::Skewness | AggFunc::SkewnessPop | AggFunc::KurtosisPop => Self::Skewness {
                mean: 0.0,
                m2: 0.0,
                m3: 0.0,
                m4: 0.0,
                count: 0,
                kind: match func {
                    AggFunc::SkewnessPop => MomentKind::SkewPop,
                    AggFunc::KurtosisPop => MomentKind::KurtosisPop,
                    _ => MomentKind::Skew,
                },
            },
            AggFunc::Mode => Self::Mode { seen: Vec::new() },
            AggFunc::ApproxMedian | AggFunc::ApproxPercentile => Self::ApproxMedian {
                floating: false,
                histogram: HdrHistogram::new(1),
                samples: Vec::new(),
                percentile: 0.5,
            },
            AggFunc::ArgMax | AggFunc::ArgMin => Self::ArgMax {
                value: Scalar::Null,
                key: None,
                min: func == AggFunc::ArgMin,
            },
            AggFunc::Avg => Self::Average {
                total: None,
                count: 0,
            },
            AggFunc::StdDev
            | AggFunc::Variance
            | AggFunc::VarSamp
            | AggFunc::VarPop
            | AggFunc::StdDevPop
            | AggFunc::StdDevSamp => Self::StdDev {
                mean: 0.0,
                m2: 0.0,
                count: 0,
                deviation: matches!(
                    func,
                    AggFunc::StdDev | AggFunc::StdDevPop | AggFunc::StdDevSamp
                ),
                population: matches!(func, AggFunc::VarPop | AggFunc::StdDevPop),
            },
            AggFunc::CountDistinct | AggFunc::ApproxCountDistinct => Self::Distinct(Vec::new()),
            AggFunc::KSum => Self::Kahan {
                sum: 0.0,
                compensation: 0.0,
                count: 0,
            },
            AggFunc::NSum => Self::Neumaier {
                sum: 0.0,
                compensation: 0.0,
                count: 0,
            },
            AggFunc::StringAgg | AggFunc::StringDistinctAgg => Self::StringAgg {
                text: String::new(),
                delimiter: '\0',
                has_value: false,
                distinct: func == AggFunc::StringDistinctAgg,
                seen: Vec::new(),
            },
            AggFunc::Vwap => Self::Vwap {
                notional: 0.0,
                volume: 0.0,
            },
            AggFunc::WeightedAvg => Self::WeightedAvg {
                notional: 0.0,
                volume: 0.0,
                started: false,
            },
            AggFunc::WeightedStdDev | AggFunc::WeightedStdDevFreq => Self::WeightedStdDev {
                w_sum: 0.0,
                w_sum2: 0.0,
                mean: 0.0,
                s: 0.0,
                started: false,
                frequency: func == AggFunc::WeightedStdDevFreq,
            },
            AggFunc::Twap => Self::Twap {
                samples: Vec::new(),
            },
            AggFunc::Sparkline => Self::Sparkline {
                values: Vec::new(),
                params: None,
            },
            AggFunc::CovarPop | AggFunc::CovarSamp => Self::Covar {
                mean_y: 0.0,
                mean_x: 0.0,
                sum_xy: 0.0,
                count: 0,
                population: func == AggFunc::CovarPop,
            },
            AggFunc::Corr | AggFunc::RegrSlope | AggFunc::RegrIntercept | AggFunc::RegrR2 => {
                Self::Corr {
                    mean_y: 0.0,
                    sum_y: 0.0,
                    mean_x: 0.0,
                    sum_x: 0.0,
                    sum_xy: 0.0,
                    count: 0,
                    kind: match func {
                        AggFunc::RegrSlope => PairKind::Slope,
                        AggFunc::RegrIntercept => PairKind::Intercept,
                        AggFunc::RegrR2 => PairKind::R2,
                        _ => PairKind::Corr,
                    },
                }
            }
            AggFunc::BoolAnd => Self::BoolAnd {
                value: true,
                count: 0,
            },
            AggFunc::BoolOr => Self::BoolOr {
                value: false,
                count: 0,
            },
        }
    }

    fn finish(&self) -> Scalar {
        match self {
            Self::Count(total) => Scalar::Long(*total),
            Self::Distinct(seen) => Scalar::Long(seen.len() as i64),
            Self::Value(Some(value)) => value.clone(),
            Self::Value(None)
            | Self::Average { count: 0, .. }
            | Self::StdDev { count: 0, .. }
            | Self::Kahan { count: 0, .. }
            | Self::Neumaier { count: 0, .. } => Scalar::Null,
            Self::Average {
                total: Some(total),
                count,
            } => average_of(total, *count),
            Self::Average { total: None, .. } => Scalar::Null,
            Self::StdDev {
                m2,
                count,
                deviation,
                population,
                ..
            } => {
                let mut result = if *population && *count > 0 {
                    *m2 / (*count as f64)
                } else if !*population && *count > 1 {
                    *m2 / (*count - 1) as f64
                } else {
                    return Scalar::Null;
                };
                if *deviation {
                    result = result.sqrt();
                }
                if result.is_finite() {
                    Scalar::Double(result)
                } else {
                    Scalar::Null
                }
            }
            Self::Kahan { sum, count, .. } => {
                if *count > 0 && sum.is_finite() {
                    Scalar::Double(*sum)
                } else {
                    Scalar::Null
                }
            }
            Self::Neumaier {
                sum,
                compensation,
                count,
            } => {
                let result = *sum + *compensation;
                if *count > 0 && result.is_finite() {
                    Scalar::Double(result)
                } else {
                    Scalar::Null
                }
            }
            Self::StringAgg {
                text, has_value, ..
            } => {
                if *has_value {
                    Scalar::Text(text.clone())
                } else {
                    Scalar::Null
                }
            }
            Self::Twap { samples } => twap_scalar(samples),
            Self::Sparkline { values, params } => {
                sparkline_scalar(values, *params).unwrap_or(Scalar::Null)
            }
            Self::Vwap { notional, volume } => {
                if *volume > 0.0 {
                    let result = *notional / *volume;
                    if result.is_finite() {
                        Scalar::Double(result)
                    } else {
                        Scalar::Null
                    }
                } else {
                    Scalar::Null
                }
            }
            Self::WeightedAvg {
                notional, volume, ..
            } => {
                let result = *notional / *volume;
                if result.is_finite() {
                    Scalar::Double(result)
                } else {
                    Scalar::Null
                }
            }
            Self::WeightedStdDev {
                w_sum,
                w_sum2,
                s,
                frequency,
                ..
            } => weighted_stddev_scalar(*w_sum, *w_sum2, *s, *frequency),
            Self::Covar {
                sum_xy,
                count,
                population,
                ..
            } => {
                let divisor = if *population { *count } else { *count - 1 };
                if divisor > 0 {
                    let result = *sum_xy / (divisor as f64);
                    if result.is_finite() {
                        Scalar::Double(result)
                    } else {
                        Scalar::Null
                    }
                } else {
                    Scalar::Null
                }
            }
            Self::Corr {
                mean_y,
                sum_y,
                mean_x,
                sum_x,
                sum_xy,
                count,
                kind,
            } => match kind {
                PairKind::Slope => slope_result(*sum_xy, *sum_x, *count),
                PairKind::Intercept => intercept_result(*mean_y, *mean_x, *sum_xy, *sum_x, *count),
                PairKind::R2 => r2_result(*sum_xy, *sum_y, *sum_x, *count),
                PairKind::Corr => corr_result(*sum_xy, *sum_y, *sum_x, *count),
            },
            Self::Skewness {
                m2,
                m3,
                m4,
                count,
                kind,
                ..
            } => match kind {
                MomentKind::KurtosisPop => kurtosis_pop_scalar(*m2, *m4, *count),
                MomentKind::SkewPop => skewness_pop_scalar(*m2, *m3, *count),
                MomentKind::Skew => skewness_scalar(*m2, *m3, *count),
            },
            Self::Mode { seen } => mode_scalar(seen),
            Self::ApproxMedian {
                floating,
                histogram,
                samples,
                percentile,
            } => {
                let point = *percentile * 100.0;
                if *floating {
                    double_at(samples, point)
                } else {
                    histogram.value_at(point)
                }
            }
            Self::ArgMax { value, key, .. } => {
                if key.is_none() {
                    Scalar::Null
                } else {
                    value.clone()
                }
            }
            Self::GeoMean {
                sum_ln,
                count,
                invalid,
            } => {
                if *count == 0 || *invalid {
                    Scalar::Null
                } else {
                    Scalar::Double((*sum_ln / *count as f64).exp())
                }
            }
            Self::BitAnd { bits, tag } | Self::BitOr { bits, tag } | Self::BitXor { bits, tag } => {
                bit_and_scalar(*bits, *tag)
            }
            Self::BoolAnd { value, count } | Self::BoolOr { value, count } => {
                if *count == 0 {
                    Scalar::Boolean(false)
                } else {
                    Scalar::Boolean(*value)
                }
            }
        }
    }
}

fn aggregate_input(table: &Table, aggregate: &AggregateExpr) -> Result<AggColumn, Error> {
    let Some(name) = &aggregate.column else {
        return Ok(AggColumn {
            index: None,
            tag: qdb_types::TAG_LONG,
            func: aggregate.func,
            symbol_keys: Vec::new(),
            delimiter: '\0',
            pair_index: None,
            pair_tag: qdb_types::TAG_DOUBLE,
            precision: 1,
            percentile: 0.5,
        });
    };
    let index = table
        .column_index(name)
        .ok_or_else(|| Error::new(format!("Invalid column: {name}")))?;
    let tag = table.meta.columns[index].tag;
    if aggregate.func == AggFunc::Sparkline {
        if let Some(extra) = &aggregate.fourth_type {
            let mut types = vec![qdb_types::type_name(tag).to_string()];
            for token in extra.split(", ") {
                if let Some(column) = token.strip_prefix("col:") {
                    let other = table
                        .column_index(column)
                        .ok_or_else(|| Error::new(format!("Invalid column: {column}")))?;
                    types.push(qdb_types::type_name(table.meta.columns[other].tag).to_string());
                } else {
                    types.push(token.to_string());
                }
            }
            return Err(Error::new(format!(
                "there is no matching function `sparkline` with the argument types: ({})",
                types.join(", ")
            )));
        }
        if matches!(tag, qdb_types::TAG_BOOLEAN | qdb_types::TAG_SYMBOL) {
            return Err(Error::new(format!(
                "there is no matching function `sparkline` with the argument types: ({})",
                qdb_types::type_name(tag)
            )));
        }
    }
    if matches!(aggregate.func, AggFunc::FirstNotNull | AggFunc::LastNotNull) {
        let fname = null_agg_name(aggregate.func);
        if let Some(extra) = &aggregate.extra {
            let second = match extra {
                AggregateExtra::Type(kind) => kind.clone(),
                AggregateExtra::Column(name) => {
                    let other = table
                        .column_index(name)
                        .ok_or_else(|| Error::new(format!("Invalid column: {name}")))?;
                    qdb_types::type_name(table.meta.columns[other].tag).to_string()
                }
            };
            return Err(Error::new(format!(
                "there is no matching function `{fname}` with the argument types: ({}, {second})",
                qdb_types::type_name(tag)
            )));
        }
        if tag == qdb_types::TAG_BOOLEAN {
            return Err(Error::new(format!(
                "there is no matching function `{fname}` with the argument types: (BOOLEAN)"
            )));
        }
    }
    if matches!(
        aggregate.func,
        AggFunc::BitAnd | AggFunc::BitOr | AggFunc::BitXor | AggFunc::Mode
    ) {
        let fname = if aggregate.func == AggFunc::Mode {
            "mode"
        } else {
            bit_agg_name(aggregate.func)
        };
        if let Some(extra) = &aggregate.extra {
            let second = match extra {
                AggregateExtra::Type(kind) => kind.clone(),
                AggregateExtra::Column(name) => {
                    let other = table
                        .column_index(name)
                        .ok_or_else(|| Error::new(format!("Invalid column: {name}")))?;
                    qdb_types::type_name(table.meta.columns[other].tag).to_string()
                }
            };
            return Err(Error::new(format!(
                "there is no matching function `{fname}` with the argument types: ({}, {second})",
                qdb_types::type_name(tag)
            )));
        }
        if aggregate.func != AggFunc::Mode
            && matches!(
                tag,
                qdb_types::TAG_BOOLEAN | qdb_types::TAG_FLOAT | qdb_types::TAG_DOUBLE
            )
        {
            return Err(Error::new(format!(
                "there is no matching function `{fname}` with the argument types: ({})",
                qdb_types::type_name(tag)
            )));
        }
    }
    if matches!(aggregate.func, AggFunc::BoolAnd | AggFunc::BoolOr) && tag != qdb_types::TAG_BOOLEAN
    {
        let fname = match aggregate.func {
            AggFunc::BoolOr => "bool_or",
            _ => "bool_and",
        };
        return Err(Error::new(format!(
            "argument type mismatch for function `{fname}` at #1 expected: BOOLEAN, actual: {}",
            qdb_types::type_name(tag)
        )));
    }
    if matches!(
        aggregate.func,
        AggFunc::StdDev
            | AggFunc::Variance
            | AggFunc::VarSamp
            | AggFunc::VarPop
            | AggFunc::StdDevPop
            | AggFunc::StdDevSamp
            | AggFunc::KSum
            | AggFunc::NSum
    ) && matches!(tag, qdb_types::TAG_BOOLEAN | qdb_types::TAG_SYMBOL)
    {
        let fname = moment_name(aggregate.func);
        return Err(Error::new(format!(
            "argument type mismatch for function `{fname}` at #1 expected: DOUBLE, actual: {}",
            qdb_types::type_name(tag)
        )));
    }
    if matches!(
        aggregate.func,
        AggFunc::GeoMean | AggFunc::Skewness | AggFunc::SkewnessPop | AggFunc::KurtosisPop
    ) && matches!(tag, qdb_types::TAG_BOOLEAN | qdb_types::TAG_SYMBOL)
    {
        let fname = match aggregate.func {
            AggFunc::Skewness => "skewness",
            AggFunc::SkewnessPop => "skewness_pop",
            AggFunc::KurtosisPop => "kurtosis_pop",
            _ => "geomean",
        };
        return Err(Error::new(format!(
            "argument type mismatch for function `{fname}` at #1 expected: DOUBLE, actual: {}",
            qdb_types::type_name(tag)
        )));
    }
    if aggregate.func == AggFunc::ApproxCountDistinct {
        reject_approx_count_distinct(tag, aggregate)?;
    }
    let delimiter = if matches!(
        aggregate.func,
        AggFunc::StringAgg | AggFunc::StringDistinctAgg
    ) {
        let fname = if aggregate.func == AggFunc::StringDistinctAgg {
            "string_distinct_agg"
        } else {
            "string_agg"
        };
        string_agg_delimiter(table, tag, aggregate, fname)?
    } else {
        '\0'
    };
    let (pair_index, pair_tag) = if matches!(
        aggregate.func,
        AggFunc::CovarPop
            | AggFunc::CovarSamp
            | AggFunc::Corr
            | AggFunc::RegrSlope
            | AggFunc::RegrIntercept
            | AggFunc::RegrR2
            | AggFunc::Vwap
            | AggFunc::WeightedAvg
            | AggFunc::WeightedStdDev
            | AggFunc::WeightedStdDevFreq
    ) {
        covar_pair(table, tag, aggregate)?
    } else if aggregate.func == AggFunc::Twap {
        twap_pair(table, tag, aggregate)?
    } else if matches!(aggregate.func, AggFunc::ArgMax | AggFunc::ArgMin) {
        arg_max_pair(table, tag, aggregate)?
    } else {
        (None, qdb_types::TAG_DOUBLE)
    };
    if matches!(aggregate.func, AggFunc::Count | AggFunc::Sum) && tag == qdb_types::TAG_BOOLEAN {
        let name = match aggregate.func {
            AggFunc::Sum => "sum",
            _ => "count",
        };
        return Err(Error::new(format!(
            "there is no matching function `{name}` with the argument types: (BOOLEAN)"
        )));
    }
    let symbol_keys = if matches!(
        aggregate.func,
        AggFunc::Sum | AggFunc::Avg | AggFunc::BitAnd | AggFunc::BitOr | AggFunc::BitXor
    ) && tag == qdb_types::TAG_SYMBOL
    {
        let mut keys = Vec::new();
        for value in &table.columns[index] {
            if value.is_null() || keys.contains(value) {
                continue;
            }
            keys.push(value.clone());
        }
        keys
    } else if aggregate.func == AggFunc::ArgMax
        && pair_tag == qdb_types::TAG_SYMBOL
        && matches!(
            tag,
            qdb_types::TAG_STRING | qdb_types::TAG_SYMBOL | qdb_types::TAG_VARCHAR
        )
    {
        let mut keys = Vec::new();
        if let Some(pair_index) = pair_index {
            for value in &table.columns[pair_index] {
                if value.is_null() || keys.contains(value) {
                    continue;
                }
                keys.push(value.clone());
            }
        }
        keys
    } else {
        Vec::new()
    };
    let (precision, percentile) = match aggregate.func {
        AggFunc::ApproxMedian => (median_precision(table, tag, aggregate)?, 0.5),
        AggFunc::ApproxPercentile => percentile_spec(table, tag, aggregate)?,
        _ => (1, 0.5),
    };
    Ok(AggColumn {
        index: Some(index),
        tag,
        func: aggregate.func,
        symbol_keys,
        delimiter,
        pair_index,
        pair_tag,
        precision,
        percentile,
    })
}

fn aggregate_order_tag(input: &AggColumn) -> i32 {
    match input.func {
        AggFunc::Count | AggFunc::CountDistinct | AggFunc::ApproxCountDistinct => {
            qdb_types::TAG_LONG
        }
        AggFunc::StringAgg | AggFunc::StringDistinctAgg if input.tag == qdb_types::TAG_VARCHAR => {
            qdb_types::TAG_VARCHAR
        }
        AggFunc::StringAgg | AggFunc::StringDistinctAgg => qdb_types::TAG_STRING,
        AggFunc::Sum if input.tag == qdb_types::TAG_FLOAT => qdb_types::TAG_FLOAT,
        AggFunc::Sum if input.tag == qdb_types::TAG_DOUBLE => qdb_types::TAG_DOUBLE,
        AggFunc::Sum => qdb_types::TAG_LONG,
        AggFunc::Avg
        | AggFunc::StdDev
        | AggFunc::Variance
        | AggFunc::VarSamp
        | AggFunc::VarPop
        | AggFunc::StdDevPop
        | AggFunc::StdDevSamp
        | AggFunc::KSum
        | AggFunc::NSum
        | AggFunc::CovarPop
        | AggFunc::Vwap
        | AggFunc::WeightedAvg
        | AggFunc::WeightedStdDev
        | AggFunc::WeightedStdDevFreq
        | AggFunc::Twap
        | AggFunc::CovarSamp
        | AggFunc::Corr
        | AggFunc::RegrSlope
        | AggFunc::RegrIntercept
        | AggFunc::RegrR2
        | AggFunc::GeoMean
        | AggFunc::Skewness
        | AggFunc::SkewnessPop
        | AggFunc::KurtosisPop => qdb_types::TAG_DOUBLE,
        AggFunc::Sparkline => qdb_types::TAG_VARCHAR,
        AggFunc::Mode => mode_result_tag(input.tag),
        AggFunc::ApproxMedian | AggFunc::ApproxPercentile => qdb_types::TAG_DOUBLE,
        AggFunc::ArgMax => arg_max_result_tag(input.tag, input.pair_tag),
        AggFunc::ArgMin => arg_min_result_tag(input.tag, input.pair_tag),
        AggFunc::BoolAnd | AggFunc::BoolOr => qdb_types::TAG_BOOLEAN,
        AggFunc::BitAnd | AggFunc::BitOr | AggFunc::BitXor => bit_and_result_tag(input.tag),
        AggFunc::FirstNotNull | AggFunc::LastNotNull
            if matches!(input.tag, qdb_types::TAG_BYTE | qdb_types::TAG_SHORT) =>
        {
            qdb_types::TAG_INT
        }
        AggFunc::FirstNotNull | AggFunc::LastNotNull => input.tag,
        AggFunc::Min | AggFunc::Max if input.tag == qdb_types::TAG_BOOLEAN => qdb_types::TAG_DOUBLE,
        AggFunc::Min | AggFunc::Max | AggFunc::First | AggFunc::Last => input.tag,
    }
}

fn contribution(
    columns: &[Vec<Scalar>],
    row: usize,
    input: &AggColumn,
) -> Result<Option<Scalar>, Error> {
    let Some(index) = input.index else {
        return Ok(Some(Scalar::Long(1)));
    };
    let value = &columns[index][row];
    let skipped =
        value.is_null() || (input.tag == qdb_types::TAG_CHAR && matches!(value, Scalar::Char(0)));
    match input.func {
        AggFunc::First | AggFunc::Last => Ok(Some(value.clone())),
        AggFunc::Sparkline => {
            if value.is_null() {
                return Ok(None);
            }
            geomean_addend(value, input, "sparkline")
        }
        _ if skipped => Ok(None),
        AggFunc::FirstNotNull | AggFunc::LastNotNull
            if matches!(input.tag, qdb_types::TAG_BYTE | qdb_types::TAG_SHORT) =>
        {
            Ok(Some(Scalar::Int(as_i64(value)? as i32)))
        }
        AggFunc::FirstNotNull | AggFunc::LastNotNull => Ok(Some(value.clone())),
        AggFunc::BitAnd | AggFunc::BitOr | AggFunc::BitXor => {
            bit_and_addend(value, input, bit_agg_name(input.func))
        }
        AggFunc::GeoMean => geomean_addend(value, input, "geomean"),
        AggFunc::Skewness => geomean_addend(value, input, "skewness"),
        AggFunc::SkewnessPop => geomean_addend(value, input, "skewness_pop"),
        AggFunc::KurtosisPop => geomean_addend(value, input, "kurtosis_pop"),
        AggFunc::Mode => mode_addend(value, input),
        AggFunc::ApproxMedian | AggFunc::ApproxPercentile => median_addend(value, input),
        AggFunc::Count => Ok(Some(Scalar::Long(1))),
        AggFunc::CountDistinct => Ok(Some(value.clone())),
        AggFunc::ApproxCountDistinct => approx_distinct_value(value, input),
        AggFunc::StringAgg | AggFunc::StringDistinctAgg => {
            Ok(Some(Scalar::Text(scalar_text(value))))
        }
        AggFunc::Min | AggFunc::Max if input.tag == qdb_types::TAG_BOOLEAN => {
            let Scalar::Boolean(bit) = value else {
                return Ok(None);
            };
            Ok(Some(Scalar::Double(if *bit { 1.0 } else { 0.0 })))
        }
        AggFunc::Min | AggFunc::Max => Ok(Some(value.clone())),
        AggFunc::Sum => sum_addend(value, input),
        AggFunc::Avg => avg_addend(value, input),
        AggFunc::BoolAnd | AggFunc::BoolOr => match value {
            Scalar::Boolean(bit) => Ok(Some(Scalar::Boolean(*bit))),
            _ => Ok(None),
        },
        AggFunc::StdDev
        | AggFunc::Variance
        | AggFunc::VarSamp
        | AggFunc::VarPop
        | AggFunc::StdDevPop
        | AggFunc::StdDevSamp
        | AggFunc::KSum
        | AggFunc::NSum => stddev_addend(value, input),
        AggFunc::CovarPop
        | AggFunc::CovarSamp
        | AggFunc::Corr
        | AggFunc::RegrSlope
        | AggFunc::RegrIntercept
        | AggFunc::RegrR2
        | AggFunc::ArgMax
        | AggFunc::ArgMin
        | AggFunc::Vwap
        | AggFunc::WeightedAvg
        | AggFunc::WeightedStdDev
        | AggFunc::WeightedStdDevFreq
        | AggFunc::Twap => Ok(None),
    }
}

fn sum_addend(value: &Scalar, input: &AggColumn) -> Result<Option<Scalar>, Error> {
    if value.is_null() || (input.tag == qdb_types::TAG_CHAR && matches!(value, Scalar::Char(0))) {
        return Ok(None);
    }
    match input.tag {
        qdb_types::TAG_BYTE | qdb_types::TAG_SHORT | qdb_types::TAG_INT | qdb_types::TAG_LONG => {
            Ok(Some(Scalar::Long(as_i64(value)?)))
        }
        qdb_types::TAG_DATE => match value {
            Scalar::Date(millis) => Ok(Some(Scalar::Long(*millis))),
            _ => Err(Error::new("internal: date column value")),
        },
        qdb_types::TAG_TIMESTAMP => match value {
            Scalar::Timestamp(micros) => Ok(Some(Scalar::Long(*micros))),
            _ => Err(Error::new("internal: timestamp column value")),
        },
        qdb_types::TAG_FLOAT => match value {
            Scalar::Float(number) => Ok(Some(Scalar::Float(*number))),
            _ => Err(Error::new("internal: float column value")),
        },
        qdb_types::TAG_DOUBLE => match value {
            Scalar::Double(number) => Ok(Some(Scalar::Double(*number))),
            _ => Err(Error::new("internal: double column value")),
        },
        qdb_types::TAG_SYMBOL => {
            let key = input
                .symbol_keys
                .iter()
                .position(|found| found == value)
                .ok_or_else(|| Error::new("internal: symbol key"))?;
            Ok(Some(Scalar::Long(i64::try_from(key).unwrap_or(i64::MAX))))
        }
        qdb_types::TAG_CHAR => Err(Error::new(format!(
            "inconvertible value: {} [CHAR -> SHORT]",
            scalar_text(value)
        ))),
        qdb_types::TAG_STRING => Err(Error::new(format!(
            "inconvertible value: `{}` [STRING -> DOUBLE]",
            scalar_text(value)
        ))),
        qdb_types::TAG_VARCHAR => Err(Error::new(format!(
            "inconvertible value: `{}` [VARCHAR -> DOUBLE]",
            scalar_text(value)
        ))),
        _ => Err(Error::new(format!(
            "unsupported: sum of column type {}",
            input.tag
        ))),
    }
}

fn scalar_text(value: &Scalar) -> String {
    match value {
        Scalar::Text(text) => text.clone(),
        Scalar::Char(unit) => char::from_u32(u32::from(*unit))
            .map(|unit| unit.to_string())
            .unwrap_or_default(),
        _ => value.to_string(),
    }
}

fn feed(
    accumulator: &mut Accumulator,
    columns: &[Vec<Scalar>],
    row: usize,
    input: &AggColumn,
) -> Result<(), Error> {
    if input.func == AggFunc::Vwap {
        let price_index = input
            .index
            .ok_or_else(|| Error::new("internal: vwap column"))?;
        let weight_index = input
            .pair_index
            .ok_or_else(|| Error::new("internal: vwap weight"))?;
        let price = covar_value(&columns[price_index][row], input.tag)?;
        let weight = covar_value(&columns[weight_index][row], input.pair_tag)?;
        if let (Some(price), Some(weight)) = (price, weight) {
            update_vwap(accumulator, price, weight);
        }
        return Ok(());
    }
    if input.func == AggFunc::WeightedAvg {
        let price_index = input
            .index
            .ok_or_else(|| Error::new("internal: weighted_avg column"))?;
        let weight_index = input
            .pair_index
            .ok_or_else(|| Error::new("internal: weighted_avg weight"))?;
        let price = weighted_avg_value(&columns[price_index][row], input.tag)?;
        let weight = weighted_avg_value(&columns[weight_index][row], input.pair_tag)?;
        update_weighted_avg(accumulator, price, weight);
        return Ok(());
    }
    if matches!(
        input.func,
        AggFunc::WeightedStdDev | AggFunc::WeightedStdDevFreq
    ) {
        let price_index = input
            .index
            .ok_or_else(|| Error::new("internal: weighted_stddev column"))?;
        let weight_index = input
            .pair_index
            .ok_or_else(|| Error::new("internal: weighted_stddev weight"))?;
        let price = weighted_avg_value(&columns[price_index][row], input.tag)?;
        let weight = weighted_avg_value(&columns[weight_index][row], input.pair_tag)?;
        update_weighted_stddev(accumulator, price, weight);
        return Ok(());
    }
    if input.func == AggFunc::Twap {
        let price_index = input
            .index
            .ok_or_else(|| Error::new("internal: twap column"))?;
        let ts_index = input
            .pair_index
            .ok_or_else(|| Error::new("internal: twap timestamp"))?;
        let price = covar_value(&columns[price_index][row], input.tag)?;
        let timestamp = match &columns[ts_index][row] {
            Scalar::Timestamp(micros) => Some(*micros),
            _ => None,
        };
        if let (Some(price), Some(timestamp)) = (price, timestamp) {
            if let Accumulator::Twap { samples } = accumulator {
                samples.push((timestamp, price));
            }
        }
        return Ok(());
    }
    if matches!(
        input.func,
        AggFunc::CovarPop
            | AggFunc::CovarSamp
            | AggFunc::Corr
            | AggFunc::RegrSlope
            | AggFunc::RegrIntercept
            | AggFunc::RegrR2
    ) {
        let y_index = input
            .index
            .ok_or_else(|| Error::new("internal: covar column"))?;
        let x_index = input
            .pair_index
            .ok_or_else(|| Error::new("internal: covar pair"))?;
        let y = covar_value(&columns[y_index][row], input.tag)?;
        let x = covar_value(&columns[x_index][row], input.pair_tag)?;
        if let (Some(y), Some(x)) = (y, x) {
            if matches!(
                input.func,
                AggFunc::Corr | AggFunc::RegrSlope | AggFunc::RegrIntercept | AggFunc::RegrR2
            ) {
                update_corr(accumulator, y, x);
            } else {
                update_covar(accumulator, y, x);
            }
        }
        return Ok(());
    }
    if matches!(input.func, AggFunc::ArgMax | AggFunc::ArgMin) {
        update_arg_max(accumulator, columns, row, input)?;
        return Ok(());
    }
    absorb(accumulator, contribution(columns, row, input)?, input.func);
    Ok(())
}

fn covar_pair(
    table: &Table,
    tag: i32,
    aggregate: &AggregateExpr,
) -> Result<(Option<usize>, i32), Error> {
    reject_covar_type(tag)?;
    let name = aggregate
        .pair
        .as_deref()
        .ok_or_else(|| Error::new("internal: covar pair"))?;
    let index = table
        .column_index(name)
        .ok_or_else(|| Error::new(format!("Invalid column: {name}")))?;
    let pair_tag = table.meta.columns[index].tag;
    reject_covar_type(pair_tag)?;
    Ok((Some(index), pair_tag))
}

fn reject_covar_type(tag: i32) -> Result<(), Error> {
    if matches!(tag, qdb_types::TAG_BOOLEAN | qdb_types::TAG_SYMBOL) {
        return Err(Error::new(format!(
            "expression type mismatch, expected: DOUBLE, actual: {}",
            qdb_types::type_name(tag)
        )));
    }
    Ok(())
}

fn covar_value(value: &Scalar, tag: i32) -> Result<Option<f64>, Error> {
    if value.is_null() || (tag == qdb_types::TAG_CHAR && matches!(value, Scalar::Char(0))) {
        return Ok(None);
    }
    let number = match tag {
        qdb_types::TAG_BYTE
        | qdb_types::TAG_SHORT
        | qdb_types::TAG_INT
        | qdb_types::TAG_LONG
        | qdb_types::TAG_FLOAT
        | qdb_types::TAG_DOUBLE => as_f64(value)?,
        qdb_types::TAG_DATE => match value {
            Scalar::Date(millis) => *millis as f64,
            _ => return Err(Error::new("internal: date column value")),
        },
        qdb_types::TAG_TIMESTAMP => match value {
            Scalar::Timestamp(micros) => *micros as f64,
            _ => return Err(Error::new("internal: timestamp column value")),
        },
        qdb_types::TAG_STRING | qdb_types::TAG_VARCHAR => {
            let text = scalar_text(value);
            let parsed = parse_questdb_f64(&text).filter(|number| number.is_finite());
            let Some(number) = parsed else {
                let kind = qdb_types::type_name(tag);
                return Err(Error::new(format!(
                    "inconvertible value: `{text}` [{kind} -> DOUBLE]"
                )));
            };
            number
        }
        qdb_types::TAG_CHAR => {
            let text = scalar_text(value);
            let parsed = parse_questdb_f64(&text).filter(|number| number.is_finite());
            let Some(number) = parsed else {
                return Err(Error::new(format!(
                    "inconvertible value: {text} [CHAR -> DOUBLE]"
                )));
            };
            number
        }
        _ => {
            return Err(Error::new(format!(
                "expression type mismatch, expected: DOUBLE, actual: {}",
                qdb_types::type_name(tag)
            )));
        }
    };
    if number.is_finite() {
        Ok(Some(number))
    } else {
        Ok(None)
    }
}

const SPARK_CHARS: [char; 8] = ['▁', '▂', '▃', '▄', '▅', '▆', '▇', '█'];

fn accumulator_value(accumulator: &Accumulator) -> Result<Scalar, Error> {
    if let Accumulator::Sparkline { values, params } = accumulator {
        sparkline_scalar(values, *params)
    } else {
        Ok(accumulator.finish())
    }
}

fn sparkline_scalar(values: &[f64], params: Option<SparkParams>) -> Result<Scalar, Error> {
    if values.is_empty() {
        return Ok(Scalar::Null);
    }
    let (user_min, user_max, width) = match params {
        Some(params) => {
            let width = match params.width {
                Some(width) if width >= 1 => width as usize,
                _ => return Err(Error::new("width must be a positive integer")),
            };
            (
                params.min_bits.map(f64::from_bits),
                params.max_bits.map(f64::from_bits),
                width,
            )
        }
        None => (None, None, values.len()),
    };
    if let (Some(min), Some(max)) = (user_min, user_max) {
        if min > max {
            return Err(Error::new(format!(
                "sparkline() min must not exceed max [min={}, max={}]",
                spark_bound_text(min),
                spark_bound_text(max)
            )));
        }
    }
    let mut min = values[0];
    let mut max = values[0];
    for value in &values[1..] {
        if *value < min {
            min = *value;
        }
        if *value > max {
            max = *value;
        }
    }
    if let Some(bound) = user_min {
        min = bound;
    }
    if let Some(bound) = user_max {
        max = bound;
    }
    let range = max - min;
    let mut text = String::new();
    if width >= values.len() {
        for value in values {
            text.push(spark_char(*value, min, range));
        }
    } else {
        let bucket = values.len() as f64 / width as f64;
        for index in 0..width {
            let from = (index as f64 * bucket) as usize;
            let to = ((index + 1) as f64 * bucket) as usize;
            let mut sum = 0.0;
            for value in &values[from..to] {
                sum += *value;
            }
            let average = sum / (to - from) as f64;
            text.push(spark_char(average, min, range));
        }
    }
    Ok(Scalar::Text(text))
}

fn spark_bound_text(value: f64) -> String {
    format!("{value:?}")
}

fn spark_char(value: f64, min: f64, range: f64) -> char {
    if range == 0.0 {
        return SPARK_CHARS[SPARK_CHARS.len() - 1];
    }
    let upper = min + range;
    let clamped = min.max(upper.min(value));
    let index = ((clamped - min) / range * (SPARK_CHARS.len() - 1) as f64) as i32;
    let index = if index < 0 { 0 } else { index as usize };
    SPARK_CHARS[index.min(SPARK_CHARS.len() - 1)]
}

fn twap_pair(
    table: &Table,
    tag: i32,
    aggregate: &AggregateExpr,
) -> Result<(Option<usize>, i32), Error> {
    reject_covar_type(tag)?;
    let name = aggregate
        .pair
        .as_deref()
        .ok_or_else(|| Error::new("internal: twap timestamp"))?;
    let index = table
        .column_index(name)
        .ok_or_else(|| Error::new(format!("Invalid column: {name}")))?;
    if index as i32 != table.meta.timestamp_index {
        return Err(Error::new(
            "twap() requires the table's designated timestamp as the second argument",
        ));
    }
    Ok((Some(index), table.meta.columns[index].tag))
}

fn twap_scalar(samples: &[(i64, f64)]) -> Scalar {
    if samples.is_empty() {
        return Scalar::Null;
    }
    if samples.len() == 1 {
        return Scalar::Double(samples[0].1);
    }
    let mut weighted = 0.0;
    let mut price_sum = samples[0].1;
    let first = samples[0].0;
    let mut previous_ts = first;
    let mut previous_price = samples[0].1;
    for &(timestamp, price) in &samples[1..] {
        weighted += previous_price * ((timestamp - previous_ts) as f64);
        price_sum += price;
        previous_ts = timestamp;
        previous_price = price;
    }
    let duration = previous_ts - first;
    let result = if duration > 0 {
        weighted / (duration as f64)
    } else {
        price_sum / (samples.len() as f64)
    };
    if result.is_finite() {
        Scalar::Double(result)
    } else {
        Scalar::Null
    }
}

fn weighted_avg_value(value: &Scalar, tag: i32) -> Result<Option<f64>, Error> {
    if tag == qdb_types::TAG_CHAR && matches!(value, Scalar::Char(0)) {
        return Err(Error::new("inconvertible value: \0 [CHAR -> DOUBLE]"));
    }
    covar_value(value, tag)
}

fn weighted_stddev_scalar(w_sum: f64, w_sum2: f64, s: f64, frequency: bool) -> Scalar {
    let divisor = if frequency {
        w_sum - 1.0
    } else {
        w_sum - w_sum2 / w_sum
    };
    if divisor <= 0.0 {
        return Scalar::Null;
    }
    let result = (s / divisor).sqrt();
    if result.is_finite() {
        Scalar::Double(result)
    } else {
        Scalar::Null
    }
}

fn update_weighted_stddev(accumulator: &mut Accumulator, sample: Option<f64>, weight: Option<f64>) {
    let Accumulator::WeightedStdDev {
        w_sum,
        w_sum2,
        mean,
        s,
        started,
        ..
    } = accumulator
    else {
        return;
    };
    let pair = match (sample, weight) {
        (Some(sample), Some(weight))
            if sample.is_finite() && weight.is_finite() && weight != 0.0 =>
        {
            Some((sample, weight))
        }
        _ => None,
    };
    if !*started {
        *started = true;
        match pair {
            Some((_, weight)) if weight < 0.0 => {
                *w_sum = f64::NAN;
                *w_sum2 = f64::NAN;
                *mean = f64::NAN;
                *s = f64::NAN;
            }
            Some((sample, weight)) => {
                *w_sum = weight;
                *w_sum2 = weight * weight;
                *mean = sample;
                *s = 0.0;
            }
            None => {
                *w_sum = 0.0;
                *w_sum2 = 0.0;
                *mean = 0.0;
                *s = 0.0;
            }
        }
        return;
    }
    let Some((sample, weight)) = pair else {
        return;
    };
    if weight < 0.0 {
        *w_sum = f64::NAN;
        *w_sum2 = f64::NAN;
        *mean = f64::NAN;
        *s = f64::NAN;
        return;
    }
    *w_sum += weight;
    *w_sum2 += weight * weight;
    let mean_old = *mean;
    *mean += (weight / *w_sum) * (sample - mean_old);
    *s += weight * (sample - mean_old) * (sample - *mean);
}

fn update_weighted_avg(accumulator: &mut Accumulator, price: Option<f64>, weight: Option<f64>) {
    let Accumulator::WeightedAvg {
        notional,
        volume,
        started,
    } = accumulator
    else {
        return;
    };
    let product = match (price, weight) {
        (Some(price), Some(weight)) if price.is_finite() && weight.is_finite() && weight != 0.0 => {
            Some((price * weight, weight))
        }
        _ => None,
    };
    if !*started {
        *started = true;
        if let Some((product, weight)) = product {
            *notional = product;
            *volume = weight;
        } else {
            *notional = 0.0;
            *volume = 0.0;
        }
    } else if let Some((product, weight)) = product {
        *notional += product;
        *volume += weight;
    }
}

fn update_vwap(accumulator: &mut Accumulator, price: f64, weight: f64) {
    let Accumulator::Vwap { notional, volume } = accumulator else {
        return;
    };
    if price.is_finite() && weight.is_finite() && weight > 0.0 {
        if *volume == 0.0 {
            *notional = price * weight;
        } else {
            *notional += price * weight;
        }
        *volume += weight;
    }
}

fn update_covar(accumulator: &mut Accumulator, y: f64, x: f64) {
    let Accumulator::Covar {
        mean_y,
        mean_x,
        sum_xy,
        count,
        ..
    } = accumulator
    else {
        return;
    };
    *count += 1;
    let old_mean_y = *mean_y;
    *mean_y += (y - *mean_y) / (*count as f64);
    *mean_x += (x - *mean_x) / (*count as f64);
    *sum_xy += (y - old_mean_y) * (x - *mean_x);
}

fn update_corr(accumulator: &mut Accumulator, y: f64, x: f64) {
    let Accumulator::Corr {
        mean_y,
        sum_y,
        mean_x,
        sum_x,
        sum_xy,
        count,
        ..
    } = accumulator
    else {
        return;
    };
    *count += 1;
    let old_mean_y = *mean_y;
    *mean_y += (y - *mean_y) / (*count as f64);
    *sum_y += (y - *mean_y) * (y - old_mean_y);
    let old_mean_x = *mean_x;
    *mean_x += (x - *mean_x) / (*count as f64);
    *sum_x += (x - *mean_x) * (x - old_mean_x);
    *sum_xy += (y - old_mean_y) * (x - *mean_x);
}

fn r2_result(sum_xy: f64, sum_y: f64, sum_x: f64, count: i64) -> Scalar {
    if count <= 0 || sum_x == 0.0 {
        return Scalar::Null;
    }
    if sum_y == 0.0 {
        return Scalar::Double(1.0);
    }
    let result = (sum_xy * sum_xy) / (sum_x * sum_y);
    if result.is_finite() {
        Scalar::Double(result)
    } else {
        Scalar::Null
    }
}

fn intercept_result(mean_y: f64, mean_x: f64, sum_xy: f64, sum_x: f64, count: i64) -> Scalar {
    if count <= 0 || sum_x == 0.0 {
        return Scalar::Null;
    }
    let result = mean_y - mean_x * (sum_xy / sum_x);
    if result.is_finite() {
        Scalar::Double(result)
    } else {
        Scalar::Null
    }
}

fn slope_result(sum_xy: f64, sum_x: f64, count: i64) -> Scalar {
    if count <= 0 || sum_x == 0.0 {
        return Scalar::Null;
    }
    let result = sum_xy / sum_x;
    if result.is_finite() {
        Scalar::Double(result)
    } else {
        Scalar::Null
    }
}

fn corr_result(sum_xy: f64, sum_y: f64, sum_x: f64, count: i64) -> Scalar {
    if count <= 1 {
        return Scalar::Null;
    }
    let prod = sum_y * sum_x;
    let split = !prod.is_finite() || (prod == 0.0 && sum_y != 0.0 && sum_x != 0.0);
    let denom = if split {
        sum_y.sqrt() * sum_x.sqrt()
    } else {
        prod.sqrt()
    };
    if denom == 0.0 {
        return Scalar::Null;
    }
    let result = (sum_xy / denom).clamp(-1.0, 1.0);
    if result.is_finite() {
        Scalar::Double(result)
    } else {
        Scalar::Null
    }
}

fn start_accumulator(aggregate: &AggregateExpr, input: &AggColumn) -> Accumulator {
    let mut accumulator = Accumulator::start(aggregate.func);
    if let Accumulator::Sparkline { params, .. } = &mut accumulator {
        if aggregate.precision_more {
            *params = Some(SparkParams {
                min_bits: match aggregate.third_value {
                    Some(Scalar::Double(number)) => Some(number.to_bits()),
                    _ => None,
                },
                max_bits: match aggregate.separator {
                    Some(Scalar::Double(number)) => Some(number.to_bits()),
                    _ => None,
                },
                width: match aggregate.precision {
                    Some(Scalar::Long(number)) => i32::try_from(number).ok(),
                    _ => None,
                },
            });
        }
    }
    if let Accumulator::StringAgg { delimiter, .. } = &mut accumulator {
        *delimiter = input.delimiter;
    }
    if let Accumulator::BitAnd { tag, .. }
    | Accumulator::BitOr { tag, .. }
    | Accumulator::BitXor { tag, .. } = &mut accumulator
    {
        *tag = bit_and_result_tag(input.tag);
    }
    if let Accumulator::ApproxMedian {
        floating,
        histogram,
        percentile,
        ..
    } = &mut accumulator
    {
        *floating = matches!(
            input.tag,
            qdb_types::TAG_FLOAT
                | qdb_types::TAG_DOUBLE
                | qdb_types::TAG_STRING
                | qdb_types::TAG_VARCHAR
        );
        *histogram = HdrHistogram::new(input.precision);
        *percentile = input.percentile;
    }
    accumulator
}

fn string_agg_delimiter(
    table: &Table,
    tag: i32,
    aggregate: &AggregateExpr,
    fname: &str,
) -> Result<char, Error> {
    if let Some(column) = &aggregate.separator_column {
        let other = table
            .column_index(column)
            .ok_or_else(|| Error::new(format!("Invalid column: {column}")))?;
        let other_tag = table.meta.columns[other].tag;
        return Err(Error::new(format!(
            "there is no matching function `{fname}` with the argument types: ({}, {})",
            qdb_types::type_name(tag),
            qdb_types::type_name(other_tag)
        )));
    }
    if let Some(more) = &aggregate.separator_more {
        let second = aggregate
            .separator
            .as_ref()
            .map(separator_type_name)
            .unwrap_or("CHAR");
        return Err(Error::new(format!(
            "there is no matching function `{fname}` with the argument types: ({}, {second}, {})",
            qdb_types::type_name(tag),
            separator_type_name(more)
        )));
    }
    let Some(separator) = &aggregate.separator else {
        return Err(Error::new(format!(
            "there is no matching function `{fname}` with the argument types: ({})",
            qdb_types::type_name(tag)
        )));
    };
    let second = separator_type_name(separator);
    let supported = matches!(
        tag,
        qdb_types::TAG_STRING
            | qdb_types::TAG_VARCHAR
            | qdb_types::TAG_SYMBOL
            | qdb_types::TAG_CHAR
    );
    if !supported || second != "CHAR" {
        return Err(Error::new(format!(
            "there is no matching function `{fname}` with the argument types: ({}, {second})",
            qdb_types::type_name(tag)
        )));
    }
    Ok(match separator {
        Scalar::Text(text) => text.chars().next().unwrap_or('\0'),
        _ => '\0',
    })
}

fn separator_type_name(value: &Scalar) -> &'static str {
    match value {
        Scalar::Null => "CHAR",
        Scalar::Text(text) if text.chars().count() <= 1 => "CHAR",
        _ => "STRING",
    }
}

fn reject_approx_count_distinct(tag: i32, aggregate: &AggregateExpr) -> Result<(), Error> {
    let supported = matches!(
        tag,
        qdb_types::TAG_BYTE
            | qdb_types::TAG_SHORT
            | qdb_types::TAG_INT
            | qdb_types::TAG_LONG
            | qdb_types::TAG_DATE
            | qdb_types::TAG_TIMESTAMP
            | qdb_types::TAG_SYMBOL
            | qdb_types::TAG_STRING
            | qdb_types::TAG_VARCHAR
            | qdb_types::TAG_CHAR
    );
    if aggregate.precision_more {
        let second = aggregate
            .precision
            .as_ref()
            .map(precision_type_name)
            .unwrap_or("INT");
        return Err(Error::new(format!(
            "there is no matching function `approx_count_distinct` with the argument types: ({}, {second}, INT)",
            qdb_types::type_name(tag)
        )));
    }
    if !supported {
        let message = match &aggregate.precision {
            Some(precision) => format!(
                "there is no matching function `approx_count_distinct` with the argument types: ({}, {})",
                qdb_types::type_name(tag),
                precision_type_name(precision)
            ),
            None => format!(
                "there is no matching function `approx_count_distinct` with the argument types: ({})",
                qdb_types::type_name(tag)
            ),
        };
        return Err(Error::new(message));
    }
    if let Some(precision) = &aggregate.precision {
        let in_range = matches!(precision, Scalar::Long(number) if (4..=18).contains(number));
        if !in_range {
            if matches!(precision, Scalar::Double(_)) {
                return Err(Error::new(format!(
                    "there is no matching function `approx_count_distinct` with the argument types: ({}, DOUBLE)",
                    qdb_types::type_name(tag)
                )));
            }
            return Err(Error::new("precision must be between 4 and 18"));
        }
    }
    Ok(())
}

fn precision_type_name(value: &Scalar) -> &'static str {
    match value {
        Scalar::Double(_) => "DOUBLE",
        Scalar::Long(number) if *number > i64::from(i32::MIN) && *number <= i64::from(i32::MAX) => {
            "INT"
        }
        Scalar::Null => "INT",
        _ => "LONG",
    }
}

fn approx_distinct_value(value: &Scalar, input: &AggColumn) -> Result<Option<Scalar>, Error> {
    match input.tag {
        qdb_types::TAG_STRING | qdb_types::TAG_VARCHAR => {
            let text = scalar_text(value);
            let Some(number) = parse_integer_text(&text) else {
                let kind = qdb_types::type_name(input.tag);
                return Err(Error::new(format!(
                    "inconvertible value: `{text}` [{kind} -> LONG]"
                )));
            };
            Ok(Some(Scalar::Long(number)))
        }
        qdb_types::TAG_CHAR => {
            let text = scalar_text(value);
            let parsed = parse_integer_text(&text).and_then(|number| i32::try_from(number).ok());
            let Some(number) = parsed else {
                return Err(Error::new(format!(
                    "inconvertible value: {text} [CHAR -> INT]"
                )));
            };
            Ok(Some(Scalar::Int(number)))
        }
        _ => Ok(Some(value.clone())),
    }
}

fn parse_integer_text(text: &str) -> Option<i64> {
    let mut bytes = text.as_bytes();
    let mut negative = false;
    if bytes.first() == Some(&b'+') {
        bytes = &bytes[1..];
    } else if bytes.first() == Some(&b'-') {
        negative = true;
        bytes = &bytes[1..];
    }
    if bytes.is_empty() || bytes.iter().any(|byte| !byte.is_ascii_digit()) {
        return None;
    }
    let magnitude = std::str::from_utf8(bytes).ok()?.parse::<i64>().ok()?;
    if negative {
        magnitude.checked_neg()
    } else {
        Some(magnitude)
    }
}

fn bit_and_result_tag(tag: i32) -> i32 {
    match tag {
        qdb_types::TAG_BYTE => qdb_types::TAG_BYTE,
        qdb_types::TAG_SHORT | qdb_types::TAG_CHAR => qdb_types::TAG_SHORT,
        qdb_types::TAG_INT | qdb_types::TAG_SYMBOL => qdb_types::TAG_INT,
        _ => qdb_types::TAG_LONG,
    }
}

fn bit_and_scalar(bits: Option<i64>, tag: i32) -> Scalar {
    let Some(bits) = bits else {
        return match tag {
            qdb_types::TAG_BYTE => Scalar::Byte(0),
            qdb_types::TAG_SHORT => Scalar::Short(0),
            _ => Scalar::Null,
        };
    };
    match tag {
        qdb_types::TAG_BYTE => Scalar::Byte(bits as i8),
        qdb_types::TAG_SHORT => Scalar::Short(bits as i16),
        qdb_types::TAG_INT => Scalar::Int(bits as i32),
        _ => Scalar::Long(bits),
    }
}

fn bit_agg_name(func: AggFunc) -> &'static str {
    match func {
        AggFunc::BitOr => "bit_or",
        AggFunc::BitXor => "bit_xor",
        _ => "bit_and",
    }
}

fn bit_and_addend(value: &Scalar, input: &AggColumn, fname: &str) -> Result<Option<Scalar>, Error> {
    let bits = match input.tag {
        qdb_types::TAG_BYTE | qdb_types::TAG_SHORT | qdb_types::TAG_INT | qdb_types::TAG_LONG => {
            as_i64(value)?
        }
        qdb_types::TAG_DATE => match value {
            Scalar::Date(millis) => *millis,
            _ => return Err(Error::new("internal: date column value")),
        },
        qdb_types::TAG_TIMESTAMP => match value {
            Scalar::Timestamp(micros) => *micros,
            _ => return Err(Error::new("internal: timestamp column value")),
        },
        qdb_types::TAG_SYMBOL => {
            let key = input
                .symbol_keys
                .iter()
                .position(|found| found == value)
                .ok_or_else(|| Error::new("internal: symbol key"))?;
            i64::from(i32::try_from(key).unwrap_or(i32::MAX))
        }
        qdb_types::TAG_CHAR => {
            let text = scalar_text(value);
            let parsed = parse_integer_text(&text).and_then(|number| i16::try_from(number).ok());
            let Some(number) = parsed else {
                return Err(Error::new(format!(
                    "inconvertible value: {text} [CHAR -> SHORT]"
                )));
            };
            i64::from(number)
        }
        qdb_types::TAG_STRING | qdb_types::TAG_VARCHAR => {
            let text = scalar_text(value);
            let Some(number) = parse_integer_text(&text) else {
                let kind = qdb_types::type_name(input.tag);
                return Err(Error::new(format!(
                    "inconvertible value: `{text}` [{kind} -> LONG]"
                )));
            };
            number
        }
        _ => {
            return Err(Error::new(format!(
                "there is no matching function `{fname}` with the argument types: ({})",
                qdb_types::type_name(input.tag)
            )));
        }
    };
    Ok(Some(Scalar::Long(bits)))
}

fn null_agg_name(func: AggFunc) -> &'static str {
    match func {
        AggFunc::LastNotNull => "last_not_null",
        _ => "first_not_null",
    }
}

fn moment_name(func: AggFunc) -> &'static str {
    match func {
        AggFunc::Variance => "variance",
        AggFunc::VarSamp => "var_samp",
        AggFunc::VarPop => "var_pop",
        AggFunc::StdDevPop => "stddev_pop",
        AggFunc::StdDevSamp => "stddev_samp",
        AggFunc::KSum => "ksum",
        AggFunc::NSum => "nsum",
        _ => "stddev",
    }
}

fn stddev_addend(value: &Scalar, input: &AggColumn) -> Result<Option<Scalar>, Error> {
    let number = match input.tag {
        qdb_types::TAG_BYTE
        | qdb_types::TAG_SHORT
        | qdb_types::TAG_INT
        | qdb_types::TAG_LONG
        | qdb_types::TAG_FLOAT
        | qdb_types::TAG_DOUBLE => as_f64(value)?,
        qdb_types::TAG_DATE => match value {
            Scalar::Date(millis) => *millis as f64,
            _ => return Err(Error::new("internal: date column value")),
        },
        qdb_types::TAG_TIMESTAMP => match value {
            Scalar::Timestamp(micros) => *micros as f64,
            _ => return Err(Error::new("internal: timestamp column value")),
        },
        qdb_types::TAG_STRING | qdb_types::TAG_VARCHAR => {
            let text = scalar_text(value);
            let parsed = parse_questdb_f64(&text).filter(|number| number.is_finite());
            let Some(number) = parsed else {
                let kind = qdb_types::type_name(input.tag);
                return Err(Error::new(format!(
                    "inconvertible value: `{text}` [{kind} -> DOUBLE]"
                )));
            };
            number
        }
        qdb_types::TAG_CHAR => {
            let text = scalar_text(value);
            let parsed = parse_questdb_f64(&text).filter(|number| number.is_finite());
            let Some(number) = parsed else {
                return Err(Error::new(format!(
                    "inconvertible value: {text} [CHAR -> DOUBLE]"
                )));
            };
            number
        }
        _ => {
            let fname = moment_name(input.func);
            return Err(Error::new(format!(
                "argument type mismatch for function `{fname}` at #1 expected: DOUBLE, actual: {}",
                qdb_types::type_name(input.tag)
            )));
        }
    };
    if number.is_finite() {
        Ok(Some(Scalar::Double(number)))
    } else {
        Ok(None)
    }
}

fn arg_max_pair(
    table: &Table,
    tag: i32,
    aggregate: &AggregateExpr,
) -> Result<(Option<usize>, i32), Error> {
    let first = qdb_types::type_name(tag).to_string();
    if let Some(kind) = &aggregate.third_type {
        let second = match &aggregate.pair {
            Some(name) => median_column_type(table, name)?,
            None => "UNKNOWN".to_string(),
        };
        let third = percentile_shown_type(table, kind)?;
        return Err(arg_types(aggregate.func, &[first, second, third]));
    }
    let Some(name) = &aggregate.pair else {
        return Err(arg_types(aggregate.func, &[first]));
    };
    let other = table
        .column_index(name)
        .ok_or_else(|| Error::new(format!("Invalid column: {name}")))?;
    let key_tag = table.meta.columns[other].tag;
    if matches!(tag, qdb_types::TAG_BOOLEAN) || matches!(key_tag, qdb_types::TAG_BOOLEAN) {
        return Err(arg_types(
            aggregate.func,
            &[first, qdb_types::type_name(key_tag).to_string()],
        ));
    }
    Ok((Some(other), key_tag))
}

fn arg_types(func: AggFunc, parts: &[String]) -> Error {
    let name = if func == AggFunc::ArgMin {
        "arg_min"
    } else {
        "arg_max"
    };
    Error::new(format!(
        "there is no matching function `{name}` with the argument types: ({})",
        parts.join(", ")
    ))
}

fn arg_min_result_tag(value: i32, key: i32) -> i32 {
    match value {
        qdb_types::TAG_STRING => qdb_types::TAG_DOUBLE,
        qdb_types::TAG_VARCHAR | qdb_types::TAG_SYMBOL => qdb_types::TAG_CHAR,
        _ => arg_max_result_tag(value, key),
    }
}

fn arg_max_result_tag(value: i32, key: i32) -> i32 {
    if matches!(
        value,
        qdb_types::TAG_STRING | qdb_types::TAG_SYMBOL | qdb_types::TAG_VARCHAR
    ) {
        return qdb_types::TAG_VARCHAR;
    }
    if value == qdb_types::TAG_CHAR {
        return qdb_types::TAG_CHAR;
    }
    if matches!(value, qdb_types::TAG_DATE | qdb_types::TAG_TIMESTAMP) {
        return qdb_types::TAG_TIMESTAMP;
    }
    let value_float = matches!(value, qdb_types::TAG_FLOAT | qdb_types::TAG_DOUBLE);
    if matches!(key, qdb_types::TAG_DATE | qdb_types::TAG_TIMESTAMP) {
        return if value_float {
            qdb_types::TAG_DOUBLE
        } else {
            qdb_types::TAG_LONG
        };
    }
    if matches!(
        key,
        qdb_types::TAG_FLOAT
            | qdb_types::TAG_DOUBLE
            | qdb_types::TAG_STRING
            | qdb_types::TAG_VARCHAR
    ) {
        return if value_float {
            qdb_types::TAG_DOUBLE
        } else {
            qdb_types::TAG_LONG
        };
    }
    if key == qdb_types::TAG_LONG {
        return qdb_types::TAG_DOUBLE;
    }
    if value == qdb_types::TAG_LONG {
        qdb_types::TAG_LONG
    } else {
        qdb_types::TAG_DOUBLE
    }
}

fn update_arg_max(
    accumulator: &mut Accumulator,
    columns: &[Vec<Scalar>],
    row: usize,
    input: &AggColumn,
) -> Result<(), Error> {
    let Accumulator::ArgMax { value, key, min } = accumulator else {
        return Ok(());
    };
    let min = *min;
    let value_index = input
        .index
        .ok_or_else(|| Error::new("internal: arg_max column"))?;
    let key_index = input
        .pair_index
        .ok_or_else(|| Error::new("internal: arg_max key"))?;
    let Some(next_key) = arg_key(&columns[key_index][row], input)? else {
        return Ok(());
    };
    if key
        .as_ref()
        .is_none_or(|best| arg_key_beats(&next_key, best, min))
    {
        *value = arg_value(&columns[value_index][row], input, min)?;
        *key = Some(next_key);
    }
    Ok(())
}

fn arg_key_beats(next: &ArgKey, best: &ArgKey, min: bool) -> bool {
    match (next, best) {
        (ArgKey::Long(left), ArgKey::Long(right)) => {
            if min {
                left < right
            } else {
                left > right
            }
        }
        (ArgKey::Double(left), ArgKey::Double(right)) => {
            if min {
                left < right
            } else {
                left > right
            }
        }
        _ => false,
    }
}

fn arg_key(value: &Scalar, input: &AggColumn) -> Result<Option<ArgKey>, Error> {
    if value.is_null() {
        return Ok(None);
    }
    match input.pair_tag {
        qdb_types::TAG_BYTE | qdb_types::TAG_SHORT | qdb_types::TAG_INT | qdb_types::TAG_LONG => {
            Ok(Some(ArgKey::Long(as_i64(value)?)))
        }
        qdb_types::TAG_DATE => match value {
            Scalar::Date(millis) => Ok(Some(ArgKey::Long(*millis))),
            _ => Err(Error::new("internal: date column value")),
        },
        qdb_types::TAG_TIMESTAMP => match value {
            Scalar::Timestamp(micros) => Ok(Some(ArgKey::Long(*micros))),
            _ => Err(Error::new("internal: timestamp column value")),
        },
        qdb_types::TAG_FLOAT | qdb_types::TAG_DOUBLE => Ok(Some(ArgKey::Double(as_f64(value)?))),
        qdb_types::TAG_SYMBOL => {
            if input.symbol_keys.is_empty() {
                return Err(Error::new(format!(
                    "inconvertible value: `{}` [SYMBOL -> TIMESTAMP_NS]",
                    scalar_text(value)
                )));
            }
            let index = input
                .symbol_keys
                .iter()
                .position(|found| found == value)
                .ok_or_else(|| Error::new("internal: symbol key"))?;
            Ok(Some(ArgKey::Long(i64::try_from(index).unwrap_or(i64::MAX))))
        }
        qdb_types::TAG_STRING | qdb_types::TAG_VARCHAR => {
            let text = scalar_text(value);
            let kind = qdb_types::type_name(input.pair_tag);
            let Some(number) = parse_questdb_f64(&text).filter(|number| number.is_finite()) else {
                return Err(Error::new(format!(
                    "inconvertible value: `{text}` [{kind} -> DOUBLE]"
                )));
            };
            Ok(Some(ArgKey::Double(number)))
        }
        qdb_types::TAG_CHAR => {
            let text = scalar_text(value);
            let Some(number) = parse_integer_text(&text) else {
                let target = if input.func == AggFunc::ArgMin {
                    "LONG"
                } else {
                    "INT"
                };
                return Err(Error::new(format!(
                    "inconvertible value: {text} [CHAR -> {target}]"
                )));
            };
            Ok(Some(ArgKey::Long(number)))
        }
        _ => Err(arg_types(
            input.func,
            &[
                qdb_types::type_name(input.tag).to_string(),
                qdb_types::type_name(input.pair_tag).to_string(),
            ],
        )),
    }
}

fn arg_value(value: &Scalar, input: &AggColumn, min: bool) -> Result<Scalar, Error> {
    if value.is_null() {
        return Ok(Scalar::Null);
    }
    if min {
        match input.tag {
            qdb_types::TAG_STRING => {
                let text = scalar_text(value);
                let Some(number) = parse_questdb_f64(&text).filter(|number| number.is_finite())
                else {
                    return Err(Error::new(format!(
                        "inconvertible value: `{text}` [STRING -> DOUBLE]"
                    )));
                };
                return Ok(Scalar::Double(number));
            }
            qdb_types::TAG_VARCHAR => {
                let text = scalar_text(value);
                let mut chars = text.chars();
                let Some(unit) = chars.next().filter(|_| chars.next().is_none()) else {
                    return Err(Error::new(format!(
                        "inconvertible value: `{text}` [VARCHAR -> CHAR]"
                    )));
                };
                return Ok(Scalar::Char(utf16_unit(unit)));
            }
            qdb_types::TAG_SYMBOL => {
                let text = scalar_text(value);
                let unit = text.chars().next().map(utf16_unit).unwrap_or(0);
                return Ok(Scalar::Char(unit));
            }
            _ => {}
        }
    }
    let result = if min {
        arg_min_result_tag(input.tag, input.pair_tag)
    } else {
        arg_max_result_tag(input.tag, input.pair_tag)
    };
    Ok(match result {
        qdb_types::TAG_VARCHAR => Scalar::Text(scalar_text(value)),
        qdb_types::TAG_CHAR => value.clone(),
        qdb_types::TAG_TIMESTAMP => match value {
            Scalar::Timestamp(micros) => Scalar::Timestamp(*micros),
            Scalar::Date(millis) => Scalar::Timestamp(millis.saturating_mul(1000)),
            _ => Scalar::Null,
        },
        qdb_types::TAG_LONG => match input.tag {
            qdb_types::TAG_DATE => match value {
                Scalar::Date(millis) => Scalar::Long(*millis),
                _ => Scalar::Null,
            },
            qdb_types::TAG_TIMESTAMP => match value {
                Scalar::Timestamp(micros) => Scalar::Long(*micros),
                _ => Scalar::Null,
            },
            _ => as_i64(value).map(Scalar::Long).unwrap_or(Scalar::Null),
        },
        _ => as_f64(value).map(Scalar::Double).unwrap_or(Scalar::Null),
    })
}

fn utf16_unit(unit: char) -> u16 {
    let mut encoded = [0; 2];
    unit.encode_utf16(&mut encoded)[0]
}

fn percentile_spec(
    table: &Table,
    tag: i32,
    aggregate: &AggregateExpr,
) -> Result<(i32, f64), Error> {
    let first = qdb_types::type_name(tag).to_string();
    let second = match (&aggregate.extra, &aggregate.precision) {
        (Some(AggregateExtra::Type(kind)), _) => kind.clone(),
        (Some(AggregateExtra::Column(name)), _) => median_column_type(table, name)?,
        (None, Some(number)) => median_number_type(number).to_string(),
        (None, None) => {
            return Err(percentile_types(&[first]));
        }
    };
    let mut parts = vec![first.clone(), second];
    if let Some(kind) = &aggregate.third_type {
        parts.push(percentile_shown_type(table, kind)?);
    }
    if let Some(kind) = &aggregate.fourth_type {
        parts.push(percentile_shown_type(table, kind)?);
    }
    let acceptable = !matches!(tag, qdb_types::TAG_BOOLEAN | qdb_types::TAG_SYMBOL);
    if !acceptable || aggregate.fourth_type.is_some() {
        return Err(percentile_types(&parts));
    }
    let third_is_precision = match aggregate.third_type.as_deref() {
        None => true,
        Some("NULL") => true,
        Some("INT") => aggregate.third_value.is_some(),
        Some(_) => false,
    };
    if !third_is_precision {
        return Err(percentile_types(&parts));
    }
    if matches!(aggregate.extra, Some(AggregateExtra::Column(_))) {
        return Err(Error::new(
            "percentile must be a constant or runtime constant",
        ));
    }
    let Some(number) = &aggregate.precision else {
        return Err(Error::new("percentile must be between 0.0 and 1.0"));
    };
    let value = match number {
        Scalar::Double(value) => *value,
        Scalar::Long(value) => *value as f64,
        _ => return Err(Error::new("percentile must be between 0.0 and 1.0")),
    };
    if !(0.0..=1.0).contains(&value) {
        return Err(Error::new("percentile must be between 0.0 and 1.0"));
    }
    let Some(kind) = aggregate.third_type.as_deref() else {
        return Ok((1, value));
    };
    if kind == "NULL" {
        return Err(Error::new("precision must be between 0 and 5"));
    }
    let Some(Scalar::Long(digits)) = aggregate.third_value else {
        return Err(percentile_types(&parts));
    };
    if !(0..=5).contains(&digits) {
        return Err(Error::new("precision must be between 0 and 5"));
    }
    Ok((digits as i32, value))
}

fn percentile_shown_type(table: &Table, kind: &str) -> Result<String, Error> {
    if matches!(kind, "NULL" | "INT" | "LONG" | "DOUBLE") {
        return Ok(kind.to_string());
    }
    median_column_type(table, kind)
}

fn percentile_types(parts: &[String]) -> Error {
    Error::new(format!(
        "there is no matching function `approx_percentile` with the argument types: ({})",
        parts.join(", ")
    ))
}

fn median_precision(table: &Table, tag: i32, aggregate: &AggregateExpr) -> Result<i32, Error> {
    if let Some(third) = &aggregate.third_type {
        let second = match &aggregate.extra {
            Some(AggregateExtra::Type(kind)) => kind.clone(),
            Some(AggregateExtra::Column(name)) => median_column_type(table, name)?,
            None => match &aggregate.precision {
                Some(number) => median_number_type(number).to_string(),
                None => "UNKNOWN".to_string(),
            },
        };
        let third = third.clone();
        return Err(Error::new(format!(
            "there is no matching function `approx_median` with the argument types: ({}, {second}, {third})",
            qdb_types::type_name(tag)
        )));
    }
    if let Some(extra) = &aggregate.extra {
        let second = match extra {
            AggregateExtra::Type(kind) => kind.clone(),
            AggregateExtra::Column(name) => median_column_type(table, name)?,
        };
        return Err(Error::new(format!(
            "there is no matching function `approx_median` with the argument types: ({}, {second})",
            qdb_types::type_name(tag)
        )));
    }
    if matches!(tag, qdb_types::TAG_BOOLEAN | qdb_types::TAG_SYMBOL) {
        return Err(Error::new(format!(
            "there is no matching function `approx_median` with the argument types: ({})",
            qdb_types::type_name(tag)
        )));
    }
    let Some(precision) = &aggregate.precision else {
        return Ok(1);
    };
    let digits = match precision {
        Scalar::Long(value) => *value,
        _ => return Err(Error::new("precision must be between 0 and 5")),
    };
    if !(0..=5).contains(&digits) {
        return Err(Error::new("precision must be between 0 and 5"));
    }
    Ok(digits as i32)
}

fn median_column_type(table: &Table, name: &str) -> Result<String, Error> {
    let other = table
        .column_index(name)
        .ok_or_else(|| Error::new(format!("Invalid column: {name}")))?;
    Ok(qdb_types::type_name(table.meta.columns[other].tag).to_string())
}

fn median_number_type(number: &Scalar) -> &'static str {
    match number {
        Scalar::Double(_) => "DOUBLE",
        Scalar::Long(value) if i32::try_from(*value).is_ok() => "INT",
        Scalar::Long(_) => "LONG",
        _ => "DOUBLE",
    }
}

fn median_addend(value: &Scalar, input: &AggColumn) -> Result<Option<Scalar>, Error> {
    match input.tag {
        qdb_types::TAG_BYTE | qdb_types::TAG_SHORT | qdb_types::TAG_INT | qdb_types::TAG_LONG => {
            let number = as_i64(value)?;
            if number < 0 {
                return Err(Error::new("Histogram recorded value cannot be negative."));
            }
            Ok(Some(Scalar::Long(number)))
        }
        qdb_types::TAG_DATE => match value {
            Scalar::Date(millis) => {
                if *millis < 0 {
                    return Err(Error::new("Histogram recorded value cannot be negative."));
                }
                Ok(Some(Scalar::Long(*millis)))
            }
            _ => Err(Error::new("internal: date column value")),
        },
        qdb_types::TAG_TIMESTAMP => match value {
            Scalar::Timestamp(micros) => {
                if *micros < 0 {
                    return Err(Error::new("Histogram recorded value cannot be negative."));
                }
                Ok(Some(Scalar::Long(*micros)))
            }
            _ => Err(Error::new("internal: timestamp column value")),
        },
        qdb_types::TAG_FLOAT | qdb_types::TAG_DOUBLE => {
            let number = as_f64(value)?;
            if number < 0.0 {
                return Err(Error::new("Negative values cannot be recorded"));
            }
            Ok(Some(Scalar::Double(if number == 0.0 {
                0.0
            } else {
                number
            })))
        }
        qdb_types::TAG_STRING | qdb_types::TAG_VARCHAR => {
            let text = scalar_text(value);
            let parsed = parse_questdb_f64(&text).filter(|number| number.is_finite());
            let Some(number) = parsed else {
                let kind = qdb_types::type_name(input.tag);
                return Err(Error::new(format!(
                    "inconvertible value: `{text}` [{kind} -> DOUBLE]"
                )));
            };
            if number < 0.0 {
                return Err(Error::new("Negative values cannot be recorded"));
            }
            Ok(Some(Scalar::Double(if number == 0.0 {
                0.0
            } else {
                number
            })))
        }
        qdb_types::TAG_CHAR => {
            let text = scalar_text(value);
            let parsed = parse_integer_text(&text);
            let Some(number) = parsed else {
                return Err(Error::new(format!(
                    "inconvertible value: {text} [CHAR -> LONG]"
                )));
            };
            if number < 0 {
                return Err(Error::new("Histogram recorded value cannot be negative."));
            }
            Ok(Some(Scalar::Long(number)))
        }
        _ => Err(Error::new(format!(
            "there is no matching function `approx_median` with the argument types: ({})",
            qdb_types::type_name(input.tag)
        ))),
    }
}

fn double_at(samples: &[f64], percentile: f64) -> Scalar {
    if samples.is_empty() {
        return Scalar::Null;
    }
    let mut values = samples.to_vec();
    values.sort_by(|left, right| left.partial_cmp(right).unwrap_or(std::cmp::Ordering::Equal));
    let requested = next_down(percentile).clamp(0.0, 100.0);
    let count_at = ((requested * values.len() as f64) / 100.0).ceil().max(1.0) as usize;
    Scalar::Double(values[count_at - 1])
}

fn next_down(value: f64) -> f64 {
    if value.is_nan() || value == f64::NEG_INFINITY {
        return value;
    }
    if value == 0.0 {
        return f64::from_bits(1).copysign(-1.0);
    }
    let bits = value.to_bits();
    if value > 0.0 {
        f64::from_bits(bits - 1)
    } else {
        f64::from_bits(bits + 1)
    }
}

struct HdrHistogram {
    digits: i32,
    counts: Vec<i64>,
    highest: i64,
    total: i64,
    unit_magnitude: i32,
    sub_bucket_half_count: i32,
    sub_bucket_half_count_magnitude: i32,
    sub_bucket_mask: i64,
    leading_zero_count_base: i32,
}

impl HdrHistogram {
    fn new(digits: i32) -> Self {
        let mut histogram = Self {
            digits,
            counts: Vec::new(),
            highest: 1000,
            total: 0,
            unit_magnitude: 0,
            sub_bucket_half_count: 1,
            sub_bucket_half_count_magnitude: 0,
            sub_bucket_mask: 0,
            leading_zero_count_base: 0,
        };
        histogram.derive();
        histogram.establish(1000);
        histogram
            .counts
            .resize(histogram.counts.capacity().max(1), 0);
        let length = histogram.length_for(1000);
        histogram.counts.resize(length, 0);
        histogram
    }

    fn derive(&mut self) {
        let largest = 2.0 * 10f64.powi(self.digits);
        self.unit_magnitude = 0;
        let magnitude = (largest.ln() / 2f64.ln()).ceil() as i32;
        let half_magnitude = magnitude - 1;
        let sub_bucket_count = 1i32 << magnitude;
        self.sub_bucket_half_count = sub_bucket_count / 2;
        self.sub_bucket_half_count_magnitude = half_magnitude;
        self.sub_bucket_mask = (i64::from(sub_bucket_count) - 1) << self.unit_magnitude;
        self.leading_zero_count_base = 64 - self.unit_magnitude - magnitude;
    }

    fn length_for(&self, highest: i64) -> usize {
        let sub_bucket_count = self.sub_bucket_half_count * 2;
        let mut smallest = i64::from(sub_bucket_count);
        let mut buckets = 1;
        while smallest <= highest {
            if smallest > i64::MAX / 2 {
                buckets += 1;
                break;
            }
            smallest <<= 1;
            buckets += 1;
        }
        ((buckets + 1) * self.sub_bucket_half_count) as usize
    }

    fn establish(&mut self, highest: i64) {
        let length = self.length_for(highest);
        self.highest = highest;
        if self.counts.len() < length {
            self.counts.resize(length, 0);
        }
    }

    fn record(&mut self, value: i64) -> Result<(), Error> {
        if value < 0 {
            return Err(Error::new("Histogram recorded value cannot be negative."));
        }
        let mut index = self.counts_index(value);
        if index < 0 || index >= self.counts.len() as i32 {
            self.establish(value);
            index = self.counts_index(value);
            self.highest =
                self.highest_equivalent(self.value_from_slot(self.counts.len() as i32 - 1));
        }
        if index >= 0 && (index as usize) < self.counts.len() {
            self.counts[index as usize] += 1;
            self.total += 1;
        }
        Ok(())
    }

    fn value_at(&self, percentile: f64) -> Scalar {
        if self.total == 0 {
            return Scalar::Null;
        }
        let requested = next_down(percentile).clamp(0.0, 100.0);
        let mut count_at = ((requested * self.total as f64) / 100.0).ceil() as i64;
        if count_at < 1 {
            count_at = 1;
        }
        let mut seen = 0i64;
        for (index, count) in self.counts.iter().enumerate() {
            seen += *count;
            if seen >= count_at {
                let raw = self.value_from_slot(index as i32);
                let value = if percentile == 0.0 {
                    self.lowest_equivalent(raw)
                } else {
                    self.highest_equivalent(raw)
                };
                return Scalar::Double(value as f64);
            }
        }
        Scalar::Double(0.0)
    }

    fn counts_index(&self, value: i64) -> i32 {
        let bucket = self.bucket_index(value);
        let sub = self.sub_bucket_index(value, bucket);
        let base = (bucket + 1) << self.sub_bucket_half_count_magnitude;
        let offset = sub - self.sub_bucket_half_count;
        base + offset
    }

    fn bucket_index(&self, value: i64) -> i32 {
        self.leading_zero_count_base - (value | self.sub_bucket_mask).leading_zeros() as i32
    }

    fn sub_bucket_index(&self, value: i64, bucket: i32) -> i32 {
        (value >> (bucket + self.unit_magnitude)) as i32
    }

    fn value_from_parts(&self, bucket: i32, sub: i32) -> i64 {
        i64::from(sub) << (bucket + self.unit_magnitude)
    }

    fn value_from_slot(&self, index: i32) -> i64 {
        let mut bucket = (index >> self.sub_bucket_half_count_magnitude) - 1;
        let mut sub = (index & (self.sub_bucket_half_count - 1)) + self.sub_bucket_half_count;
        if bucket < 0 {
            sub -= self.sub_bucket_half_count;
            bucket = 0;
        }
        self.value_from_parts(bucket, sub)
    }

    fn lowest_equivalent(&self, value: i64) -> i64 {
        let bucket = self.bucket_index(value);
        let sub = self.sub_bucket_index(value, bucket);
        self.value_from_parts(bucket, sub)
    }

    fn highest_equivalent(&self, value: i64) -> i64 {
        let bucket = self.bucket_index(value);
        let sub = self.sub_bucket_index(value, bucket);
        let lowest = self.value_from_parts(bucket, sub);
        let width = 1i64 << (self.unit_magnitude + bucket);
        lowest + width - 1
    }
}

fn mode_result_tag(tag: i32) -> i32 {
    match tag {
        qdb_types::TAG_BYTE
        | qdb_types::TAG_SHORT
        | qdb_types::TAG_INT
        | qdb_types::TAG_LONG
        | qdb_types::TAG_DATE
        | qdb_types::TAG_TIMESTAMP => qdb_types::TAG_LONG,
        qdb_types::TAG_FLOAT | qdb_types::TAG_DOUBLE => qdb_types::TAG_DOUBLE,
        qdb_types::TAG_CHAR | qdb_types::TAG_STRING => qdb_types::TAG_STRING,
        qdb_types::TAG_VARCHAR => qdb_types::TAG_VARCHAR,
        qdb_types::TAG_BOOLEAN => qdb_types::TAG_BOOLEAN,
        _ => tag,
    }
}

fn mode_scalar(seen: &[(Scalar, i64)]) -> Scalar {
    let mut best: Option<&(Scalar, i64)> = None;
    for item in seen {
        if best.is_none_or(|(_, count)| item.1 > *count) {
            best = Some(item);
        }
    }
    best.map(|(value, _)| value.clone()).unwrap_or(Scalar::Null)
}

fn mode_addend(value: &Scalar, input: &AggColumn) -> Result<Option<Scalar>, Error> {
    let scalar = match input.tag {
        qdb_types::TAG_BYTE | qdb_types::TAG_SHORT | qdb_types::TAG_INT | qdb_types::TAG_LONG => {
            Scalar::Long(as_i64(value)?)
        }
        qdb_types::TAG_DATE => match value {
            Scalar::Date(millis) => Scalar::Long(*millis),
            _ => return Err(Error::new("internal: date column value")),
        },
        qdb_types::TAG_TIMESTAMP => match value {
            Scalar::Timestamp(micros) => Scalar::Long(*micros),
            _ => return Err(Error::new("internal: timestamp column value")),
        },
        qdb_types::TAG_FLOAT => match value {
            Scalar::Float(number) => Scalar::Double(f64::from(*number)),
            _ => return Err(Error::new("internal: float column value")),
        },
        qdb_types::TAG_CHAR => Scalar::Text(char_text(value)?),
        _ => value.clone(),
    };
    Ok(Some(scalar))
}

fn kurtosis_pop_scalar(m2: f64, m4: f64, count: i64) -> Scalar {
    if count < 1 || m2 == 0.0 {
        return Scalar::Null;
    }
    let n = count as f64;
    let result = n * m4 / (m2 * m2) - 3.0;
    if result.is_finite() {
        Scalar::Double(result)
    } else {
        Scalar::Null
    }
}

fn skewness_pop_scalar(m2: f64, m3: f64, count: i64) -> Scalar {
    if count < 1 || m2 == 0.0 {
        return Scalar::Null;
    }
    let n = count as f64;
    let result = n.sqrt() * m3 / (m2 * m2.sqrt());
    if result.is_finite() {
        Scalar::Double(result)
    } else {
        Scalar::Null
    }
}

fn skewness_scalar(m2: f64, m3: f64, count: i64) -> Scalar {
    if count < 3 || m2 == 0.0 {
        return Scalar::Null;
    }
    let n = count as f64;
    let result = (n * (n - 1.0).sqrt() / (n - 2.0)) * m3 / (m2 * m2.sqrt());
    if result.is_finite() {
        Scalar::Double(result)
    } else {
        Scalar::Null
    }
}

fn geomean_addend(value: &Scalar, input: &AggColumn, fname: &str) -> Result<Option<Scalar>, Error> {
    let number = match input.tag {
        qdb_types::TAG_BYTE
        | qdb_types::TAG_SHORT
        | qdb_types::TAG_INT
        | qdb_types::TAG_LONG
        | qdb_types::TAG_FLOAT
        | qdb_types::TAG_DOUBLE => as_f64(value)?,
        qdb_types::TAG_DATE => match value {
            Scalar::Date(millis) => *millis as f64,
            _ => return Err(Error::new("internal: date column value")),
        },
        qdb_types::TAG_TIMESTAMP => match value {
            Scalar::Timestamp(micros) => *micros as f64,
            _ => return Err(Error::new("internal: timestamp column value")),
        },
        qdb_types::TAG_STRING | qdb_types::TAG_VARCHAR => {
            let text = scalar_text(value);
            let parsed = parse_questdb_f64(&text).filter(|number| number.is_finite());
            let Some(number) = parsed else {
                let kind = qdb_types::type_name(input.tag);
                return Err(Error::new(format!(
                    "inconvertible value: `{text}` [{kind} -> DOUBLE]"
                )));
            };
            number
        }
        qdb_types::TAG_CHAR => {
            let text = scalar_text(value);
            let parsed = parse_questdb_f64(&text).filter(|number| number.is_finite());
            let Some(number) = parsed else {
                return Err(Error::new(format!(
                    "inconvertible value: {text} [CHAR -> DOUBLE]"
                )));
            };
            number
        }
        _ => {
            return Err(Error::new(format!(
                "argument type mismatch for function `{fname}` at #1 expected: DOUBLE, actual: {}",
                qdb_types::type_name(input.tag)
            )));
        }
    };
    if number.is_finite() {
        Ok(Some(Scalar::Double(number)))
    } else {
        Ok(None)
    }
}

fn avg_addend(value: &Scalar, input: &AggColumn) -> Result<Option<Scalar>, Error> {
    if input.tag == qdb_types::TAG_BOOLEAN {
        let Scalar::Boolean(bit) = value else {
            return Ok(None);
        };
        return Ok(Some(Scalar::Double(if *bit { 1.0 } else { 0.0 })));
    }
    sum_addend(value, input)
}

fn average_of(total: &Scalar, count: i64) -> Scalar {
    let sum = match total {
        Scalar::Long(value) => *value as f64,
        Scalar::Float(value) => f64::from(*value),
        Scalar::Double(value) => *value,
        _ => return Scalar::Null,
    };
    Scalar::Double(sum / count as f64)
}

fn add_sum(left: &Scalar, right: &Scalar) -> Scalar {
    match (left, right) {
        (Scalar::Long(left), Scalar::Long(right)) => Scalar::Long(left.wrapping_add(*right)),
        (Scalar::Float(left), Scalar::Float(right)) => Scalar::Float(*left + *right),
        (Scalar::Double(left), Scalar::Double(right)) => Scalar::Double(*left + *right),
        _ => left.clone(),
    }
}

fn absorb(accumulator: &mut Accumulator, next: Option<Scalar>, func: AggFunc) {
    let Some(next) = next else {
        return;
    };
    match accumulator {
        Accumulator::Count(total) => *total += 1,
        Accumulator::Distinct(seen) => {
            if !seen.contains(&next) {
                seen.push(next);
            }
        }
        Accumulator::Value(current) if func == AggFunc::First || func == AggFunc::FirstNotNull => {
            if current.is_none() {
                *current = Some(next);
            }
        }
        Accumulator::Value(current) if func == AggFunc::Last || func == AggFunc::LastNotNull => {
            *current = Some(next);
        }
        Accumulator::Value(current) if func == AggFunc::Sum => {
            *current = Some(match current.take() {
                None => next,
                Some(kept) => add_sum(&kept, &next),
            });
        }
        Accumulator::Average { total, count } => {
            *count += 1;
            *total = Some(match total.take() {
                None => next,
                Some(kept) => add_sum(&kept, &next),
            });
        }
        Accumulator::StdDev {
            mean, m2, count, ..
        } => {
            let Scalar::Double(value) = next else {
                return;
            };
            if !value.is_finite() {
                return;
            }
            *count += 1;
            let old_mean = *mean;
            *mean += (value - *mean) / (*count as f64);
            *m2 += (value - *mean) * (value - old_mean);
        }
        Accumulator::Kahan {
            sum,
            compensation,
            count,
        } => {
            let Scalar::Double(value) = next else {
                return;
            };
            if !value.is_finite() {
                return;
            }
            if *count == 0 {
                *sum = value;
                *compensation = 0.0;
                *count = 1;
                return;
            }
            let y = value - *compensation;
            let t = *sum + y;
            *compensation = (t - *sum) - y;
            *sum = t;
            *count += 1;
        }
        Accumulator::Neumaier {
            sum,
            compensation,
            count,
        } => {
            let Scalar::Double(value) = next else {
                return;
            };
            if !value.is_finite() {
                return;
            }
            let total = *sum + value;
            if sum.abs() >= value.abs() {
                *compensation += (*sum - total) + value;
            } else {
                *compensation += (value - total) + *sum;
            }
            *sum = total;
            *count += 1;
        }
        Accumulator::StringAgg {
            text,
            delimiter,
            has_value,
            distinct,
            seen,
        } => {
            let Scalar::Text(piece) = next else {
                return;
            };
            if *distinct && seen.iter().any(|item| item == &piece) {
                return;
            }
            if *distinct {
                seen.push(piece.clone());
            }
            if *has_value {
                text.push(*delimiter);
            }
            text.push_str(&piece);
            *has_value = true;
        }
        Accumulator::Covar { .. }
        | Accumulator::Corr { .. }
        | Accumulator::Vwap { .. }
        | Accumulator::WeightedAvg { .. }
        | Accumulator::WeightedStdDev { .. }
        | Accumulator::Twap { .. } => {}
        Accumulator::BoolAnd { value, count } => {
            let Scalar::Boolean(bit) = next else {
                return;
            };
            if *count == 0 || *value {
                *value = bit;
            }
            *count += 1;
        }
        Accumulator::BitAnd { bits, .. } => {
            let Scalar::Long(next) = next else {
                return;
            };
            *bits = Some(bits.map(|current| current & next).unwrap_or(next));
        }
        Accumulator::BitOr { bits, .. } => {
            let Scalar::Long(next) = next else {
                return;
            };
            *bits = Some(bits.map(|current| current | next).unwrap_or(next));
        }
        Accumulator::BitXor { bits, .. } => {
            let Scalar::Long(next) = next else {
                return;
            };
            *bits = Some(bits.map(|current| current ^ next).unwrap_or(next));
        }
        Accumulator::GeoMean {
            sum_ln,
            count,
            invalid,
        } => {
            let Scalar::Double(next) = next else {
                return;
            };
            *count += 1;
            if *invalid || !next.is_finite() || next <= 0.0 {
                *invalid = true;
            } else {
                *sum_ln += next.ln();
            }
        }
        Accumulator::Sparkline { values, .. } => {
            let Scalar::Double(value) = next else {
                return;
            };
            if value.is_finite() {
                values.push(value);
            }
        }
        Accumulator::Skewness {
            mean,
            m2,
            m3,
            m4,
            count,
            ..
        } => {
            let Scalar::Double(value) = next else {
                return;
            };
            if !value.is_finite() {
                return;
            }
            *count += 1;
            let n = *count as f64;
            let delta = value - *mean;
            let delta_n = delta / n;
            let delta_n2 = delta_n * delta_n;
            let term1 = delta * delta_n * (n - 1.0);
            let new_m4 = *m4 + term1 * delta_n2 * (n * n - 3.0 * n + 3.0) + 6.0 * delta_n2 * *m2
                - 4.0 * delta_n * *m3;
            let new_m3 = *m3 + term1 * delta_n * (n - 2.0) - 3.0 * delta_n * *m2;
            *m2 += term1;
            *m3 = new_m3;
            *m4 = new_m4;
            *mean += delta_n;
        }
        Accumulator::Mode { seen } => {
            if let Some((_, count)) = seen.iter_mut().find(|(found, _)| found == &next) {
                *count += 1;
            } else {
                seen.push((next, 1));
            }
        }
        Accumulator::ApproxMedian {
            floating,
            histogram,
            samples,
            ..
        } => {
            if *floating {
                let Scalar::Double(value) = next else {
                    return;
                };
                samples.push(value);
            } else {
                let Scalar::Long(value) = next else {
                    return;
                };
                let _ = histogram.record(value);
            }
        }
        Accumulator::BoolOr { value, count } => {
            let Scalar::Boolean(bit) = next else {
                return;
            };
            if *count == 0 || !*value {
                *value = bit;
            }
            *count += 1;
        }
        Accumulator::Value(current) => match current {
            None => *current = Some(next),
            Some(kept) => {
                let replace = matches!(
                    (func, agg_cmp(kept, &next)),
                    (AggFunc::Min, Ordering::Greater) | (AggFunc::Max, Ordering::Less)
                );
                if replace {
                    *current = Some(next);
                }
            }
        },
        Accumulator::ArgMax { .. } => {}
    }
}

/// `min` and `max` treat `-0.0` and `0.0` as equal and keep the value already chosen.
fn agg_cmp(left: &Scalar, right: &Scalar) -> Ordering {
    match (left, right) {
        (Scalar::Float(left), Scalar::Float(right)) => {
            left.partial_cmp(right).unwrap_or(Ordering::Equal)
        }
        (Scalar::Double(left), Scalar::Double(right)) => {
            left.partial_cmp(right).unwrap_or(Ordering::Equal)
        }
        _ => compare_values(left, right),
    }
}

fn limit_follows_timestamp_order(table: &Table, query: &Query) -> Result<bool, Error> {
    // A single designated-timestamp key uses the ordered scan. Any other key
    // list, including `ts` plus another column, uses the sort path.
    let [order] = query.order_by.as_slice() else {
        return Ok(query.order_by.is_empty());
    };
    let Some(index) = table.column_index(&order.column) else {
        return Ok(false);
    };
    Ok(index as i32 == table.meta.timestamp_index)
}

fn apply_limit(row_ids: &mut Vec<usize>, mut lo: i64, mut hi: i64) {
    // `ORDER BY` a non-timestamp column keeps the last `|lo|` rows when `hi` is positive.
    if lo < 0 && hi > 0 {
        hi = 0;
    }
    if lo > hi && (lo ^ hi) >= 0 {
        std::mem::swap(&mut lo, &mut hi);
    }
    let len = i64::try_from(row_ids.len()).unwrap_or(i64::MAX);
    let (start, end) = if lo >= 0 && hi >= 0 {
        (lo, hi)
    } else if lo < 0 {
        (len.saturating_add(lo).max(0), len.saturating_add(hi))
    } else {
        (lo, len.saturating_add(hi))
    };
    let start = start.max(0);
    let end = end.min(len);
    if start >= end {
        row_ids.clear();
        return;
    }
    let start = usize::try_from(start).unwrap_or(0);
    let end = usize::try_from(end).unwrap_or(row_ids.len());
    row_ids.drain(end..);
    row_ids.drain(..start);
}

fn row_matches(table: &Table, row: usize, filter: &Filter) -> Result<bool, Error> {
    let index = table
        .column_index(&filter.column)
        .ok_or_else(|| Error::new(format!("unknown column `{}`", filter.column)))?;
    let left = &table.columns[index][row];
    let tag = table.meta.columns[index].tag;
    sql_cmp(left, tag, filter.op, &filter.literal)
}

fn sql_cmp(left: &Scalar, tag: i32, op: CmpOp, literal: &Scalar) -> Result<bool, Error> {
    if matches!(literal, Scalar::Null) {
        return Ok(match op {
            CmpOp::Eq => left.is_null(),
            CmpOp::NotEq => !left.is_null(),
            CmpOp::Lt | CmpOp::Gt | CmpOp::LtEq | CmpOp::GtEq => false,
        });
    }
    if left.is_null() {
        return Ok(false);
    }
    let ordering = match tag {
        qdb_types::TAG_BOOLEAN => cmp_bool(left, literal)?,
        qdb_types::TAG_BYTE | qdb_types::TAG_SHORT | qdb_types::TAG_INT | qdb_types::TAG_LONG => {
            cmp_i64(as_i64(left)?, as_i64(literal)?)?
        }
        qdb_types::TAG_FLOAT | qdb_types::TAG_DOUBLE => cmp_f64(as_f64(left)?, as_f64(literal)?)?,
        qdb_types::TAG_CHAR => cmp_text(&char_text(left)?, &expect_text(literal)?)?,
        qdb_types::TAG_STRING | qdb_types::TAG_SYMBOL | qdb_types::TAG_VARCHAR => {
            cmp_text(&expect_text(left)?, &expect_text(literal)?)?
        }
        qdb_types::TAG_TIMESTAMP => {
            let right = timestamp_from_literal(literal)?
                .ok_or_else(|| Error::new("NULL timestamp already handled"))?;
            let Scalar::Timestamp(left) = left else {
                return Err(Error::new("internal: timestamp column value"));
            };
            left.cmp(&right)
        }
        qdb_types::TAG_DATE => {
            let right = date_from_literal(literal)?
                .ok_or_else(|| Error::new("NULL date already handled"))?;
            let Scalar::Date(left) = left else {
                return Err(Error::new("internal: date column value"));
            };
            left.cmp(&right)
        }
        other => {
            return Err(Error::new(format!(
                "unsupported comparison on type tag {other}"
            )))
        }
    };
    Ok(match op {
        CmpOp::Eq => ordering == Ordering::Equal,
        CmpOp::NotEq => ordering != Ordering::Equal,
        CmpOp::Lt => ordering == Ordering::Less,
        CmpOp::Gt => ordering == Ordering::Greater,
        CmpOp::LtEq => ordering != Ordering::Greater,
        CmpOp::GtEq => ordering != Ordering::Less,
    })
}

fn cmp_bool(left: &Scalar, literal: &Scalar) -> Result<Ordering, Error> {
    let Scalar::Boolean(left) = left else {
        return Err(Error::new("internal: boolean column value"));
    };
    let Scalar::Boolean(right) = literal else {
        return Err(Error::new("unsupported boolean comparison"));
    };
    Ok(left.cmp(right))
}

fn cmp_i64(left: i64, right: i64) -> Result<Ordering, Error> {
    Ok(left.cmp(&right))
}

fn cmp_f64(left: f64, right: f64) -> Result<Ordering, Error> {
    left.partial_cmp(&right)
        .ok_or_else(|| Error::new("unsupported numeric comparison"))
}

fn cmp_text(left: &str, right: &str) -> Result<Ordering, Error> {
    Ok(left.cmp(right))
}

fn as_i64(value: &Scalar) -> Result<i64, Error> {
    match value {
        Scalar::Byte(v) => Ok(i64::from(*v)),
        Scalar::Short(v) => Ok(i64::from(*v)),
        Scalar::Int(v) => Ok(i64::from(*v)),
        Scalar::Long(v) => Ok(*v),
        _ => Err(Error::new(
            "unsupported numeric literal for an integer column",
        )),
    }
}

fn as_f64(value: &Scalar) -> Result<f64, Error> {
    match value {
        Scalar::Byte(v) => Ok(f64::from(*v)),
        Scalar::Short(v) => Ok(f64::from(*v)),
        Scalar::Int(v) => Ok(f64::from(*v)),
        Scalar::Long(v) => Ok(*v as f64),
        Scalar::Float(v) => Ok(f64::from(*v)),
        Scalar::Double(v) => Ok(*v),
        _ => Err(Error::new(
            "unsupported numeric literal for a floating column",
        )),
    }
}

fn expect_text(value: &Scalar) -> Result<String, Error> {
    match value {
        Scalar::Text(text) => Ok(text.clone()),
        Scalar::Char(unit) => char_from_unit(*unit).map(|c| c.to_string()),
        _ => Err(Error::new("unsupported text comparison")),
    }
}

fn char_text(value: &Scalar) -> Result<String, Error> {
    match value {
        Scalar::Char(0) => Ok(String::new()),
        Scalar::Char(unit) => char_from_unit(*unit).map(|c| c.to_string()),
        _ => Err(Error::new("internal: char column value")),
    }
}

fn char_from_unit(unit: u16) -> Result<char, Error> {
    char::from_u32(u32::from(unit)).ok_or_else(|| Error::new(format!("invalid UTF-16 char {unit}")))
}

/// Ascending order from QuestDB 10.1.0. Integer, string, symbol, date and
/// timestamp nulls sort first. Float and double nulls sort last, above every
/// finite value, and `-0.0` sorts before `0.0`.
fn compare_asc(left: &Scalar, right: &Scalar, tag: i32) -> Ordering {
    let nulls_last = matches!(tag, qdb_types::TAG_FLOAT | qdb_types::TAG_DOUBLE);
    match (left.is_null(), right.is_null()) {
        (true, true) => Ordering::Equal,
        (true, false) => {
            if nulls_last {
                Ordering::Greater
            } else {
                Ordering::Less
            }
        }
        (false, true) => {
            if nulls_last {
                Ordering::Less
            } else {
                Ordering::Greater
            }
        }
        (false, false) => compare_values(left, right),
    }
}

fn compare_values(left: &Scalar, right: &Scalar) -> Ordering {
    match (left, right) {
        (Scalar::Boolean(a), Scalar::Boolean(b)) => a.cmp(b),
        (Scalar::Byte(a), Scalar::Byte(b)) => a.cmp(b),
        (Scalar::Short(a), Scalar::Short(b)) => a.cmp(b),
        (Scalar::Char(a), Scalar::Char(b)) => a.cmp(b),
        (Scalar::Int(a), Scalar::Int(b)) => a.cmp(b),
        (Scalar::Long(a), Scalar::Long(b)) => a.cmp(b),
        (Scalar::Float(a), Scalar::Float(b)) => a.total_cmp(b),
        (Scalar::Double(a), Scalar::Double(b)) => a.total_cmp(b),
        (Scalar::Date(a), Scalar::Date(b)) => a.cmp(b),
        (Scalar::Timestamp(a), Scalar::Timestamp(b)) => a.cmp(b),
        (Scalar::Text(a), Scalar::Text(b)) => a.cmp(b),
        _ => Ordering::Equal,
    }
}

