    #[test]
    fn not_matches_captured_exec() {
        let sensors = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h1");
        let days = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h2");
        let cases = [
            (
                sensors.clone(),
                "SELECT not(ok) FROM sensors",
                "expected/nt_ok.tsv",
            ),
            (
                sensors.clone(),
                "SELECT not(null) FROM sensors LIMIT 1",
                "expected/nt_null.tsv",
            ),
            (
                sensors.clone(),
                "SELECT NOT(ok) FROM sensors LIMIT 1",
                "expected/nt_case.tsv",
            ),
            (
                sensors.clone(),
                "SELECT not(ok) FROM sensors WHERE id = 1",
                "expected/nt_where.tsv",
            ),
            (
                sensors.clone(),
                "SELECT not(ok) FROM sensors ORDER BY not(ok)",
                "expected/nt_order.tsv",
            ),
            (
                sensors.clone(),
                "SELECT not(ok) FROM sensors ORDER BY not(ok) DESC",
                "expected/nt_desc.tsv",
            ),
            (
                sensors.clone(),
                "SELECT not(ok) FROM sensors LIMIT 0",
                "expected/nt_lim0.tsv",
            ),
            (
                sensors.clone(),
                "SELECT not(1, ok) FROM sensors",
                "expected/nt_last.tsv",
            ),
            (
                sensors.clone(),
                "SELECT not(missing, ok) FROM sensors",
                "expected/nt_ignore.tsv",
            ),
            (
                sensors.clone(),
                "SELECT not(ok, null) FROM sensors",
                "expected/nt_const.tsv",
            ),
            (
                sensors.clone(),
                "SELECT not(note, ok) FROM sensors",
                "expected/nt_ok.tsv",
            ),
            (
                sensors.clone(),
                "SELECT not(null, null) FROM sensors LIMIT 1",
                "expected/nt_null.tsv",
            ),
            (
                days.clone(),
                "SELECT not(null) FROM days ORDER BY ts",
                "expected/nt_days.tsv",
            ),
        ];
        for (root, sql, file) in cases {
            let result = execute(&root, sql).unwrap();
            let expected = std::fs::read_to_string(root.join(file)).unwrap();
            assert_eq!(render_tsv(&result), expected, "{sql}");
        }
        let err = execute(&sensors, "SELECT not() FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("too few arguments for 'not' [found=0,expected=1]"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT not(1) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "argument type mismatch for function `not` at #1 expected: BOOLEAN, actual: INT"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT not(1, 2) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "argument type mismatch for function `not` at #1 expected: BOOLEAN, actual: INT"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT not(missing, 1) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "argument type mismatch for function `not` at #1 expected: BOOLEAN, actual: INT"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT not(id) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "argument type mismatch for function `not` at #1 expected: BOOLEAN, actual: LONG"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT not(-2147483648) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "argument type mismatch for function `not` at #1 expected: BOOLEAN, actual: LONG"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT not(note) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "argument type mismatch for function `not` at #1 expected: BOOLEAN, actual: STRING"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT not('a') FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "argument type mismatch for function `not` at #1 expected: BOOLEAN, actual: CHAR"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT not('') FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "argument type mismatch for function `not` at #1 expected: BOOLEAN, actual: STRING"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT not(1.5) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "argument type mismatch for function `not` at #1 expected: BOOLEAN, actual: DOUBLE"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT not(location) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "argument type mismatch for function `not` at #1 expected: BOOLEAN, actual: SYMBOL"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT not(missing) FROM sensors").unwrap_err();
        assert!(
            err.message.contains("Invalid column: missing"),
            "{}",
            err.message
        );
    }

    #[test]
    fn stddev_matches_captured_exec() {
        let sensors = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h1");
        let days = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h2");
        let cases = [
            (
                sensors.clone(),
                "SELECT stddev(reading) FROM sensors",
                "expected/sd_read.tsv",
            ),
            (
                sensors.clone(),
                "SELECT stddev(id) FROM sensors",
                "expected/sd_id.tsv",
            ),
            (
                sensors.clone(),
                "SELECT stddev(score) FROM sensors",
                "expected/sd_score.tsv",
            ),
            (
                sensors.clone(),
                "SELECT stddev(b) FROM sensors",
                "expected/sd_byte.tsv",
            ),
            (
                sensors.clone(),
                "SELECT stddev(code) FROM sensors",
                "expected/sd_short.tsv",
            ),
            (
                sensors.clone(),
                "SELECT stddev(flags) FROM sensors",
                "expected/sd_flags.tsv",
            ),
            (
                sensors.clone(),
                "SELECT stddev(ts) FROM sensors",
                "expected/sd_ts.tsv",
            ),
            (
                sensors.clone(),
                "SELECT stddev(reading) FROM sensors WHERE id = 1",
                "expected/sd_one.tsv",
            ),
            (
                sensors.clone(),
                "SELECT stddev(reading) FROM sensors WHERE id > 100",
                "expected/sd_none.tsv",
            ),
            (
                sensors.clone(),
                "SELECT stddev(reading) FROM sensors WHERE id = -1",
                "expected/sd_neg.tsv",
            ),
            (
                sensors.clone(),
                "SELECT STDDEV(reading) FROM sensors",
                "expected/sd_case.tsv",
            ),
            (
                sensors.clone(),
                "SELECT stddev(reading) FROM sensors LIMIT 0",
                "expected/sd_lim0.tsv",
            ),
            (
                sensors.clone(),
                "SELECT stddev(reading) FROM sensors GROUP BY location ORDER BY location",
                "expected/sd_grp.tsv",
            ),
            (
                sensors.clone(),
                "SELECT stddev(id) FROM sensors GROUP BY location ORDER BY location",
                "expected/sd_grp_id.tsv",
            ),
            (
                sensors.clone(),
                "SELECT stddev(reading) FROM sensors WHERE location = 'madrid'",
                "expected/sd_where.tsv",
            ),
            (
                days.clone(),
                "SELECT stddev(id) FROM days",
                "expected/sd_days.tsv",
            ),
            (
                days.clone(),
                "SELECT stddev(id) FROM days GROUP BY location ORDER BY location",
                "expected/sd_days_grp.tsv",
            ),
        ];
        for (root, sql, file) in cases {
            let result = execute(&root, sql).unwrap();
            let expected = std::fs::read_to_string(root.join(file)).unwrap();
            assert_eq!(render_tsv(&result), expected, "{sql}");
        }
        let err = execute(&sensors, "SELECT stddev() FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("function `stddev` requires arguments: stddev(DOUBLE)"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT stddev(reading, 1) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "wrong number of arguments for function `stddev`; expected: 1, provided: 2"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT stddev(*) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("too few arguments for '*' [found=0,expected=2]"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT stddev(missing) FROM sensors").unwrap_err();
        assert!(
            err.message.contains("Invalid column: missing"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT stddev(ok) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "argument type mismatch for function `stddev` at #1 expected: DOUBLE, actual: BOOLEAN"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT stddev(location) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "argument type mismatch for function `stddev` at #1 expected: DOUBLE, actual: SYMBOL"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT stddev(note) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("inconvertible value: `alpha` [STRING -> DOUBLE]"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT stddev(tag) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("inconvertible value: `v1` [VARCHAR -> DOUBLE]"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT stddev(ch) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("inconvertible value: A [CHAR -> DOUBLE]"),
            "{}",
            err.message
        );
    }

