    #[test]
    fn geomean_matches_captured_exec() {
        let sensors = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h1");
        let days = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h2");
        let cases = [
            (
                &sensors,
                "SELECT geomean(reading) FROM sensors",
                "expected/gm_read.tsv",
            ),
            (
                &sensors,
                "SELECT geomean(reading) FROM sensors WHERE id = 1",
                "expected/gm_one.tsv",
            ),
            (
                &sensors,
                "SELECT geomean(reading) FROM sensors WHERE id > 100",
                "expected/gm_none.tsv",
            ),
            (
                &sensors,
                "SELECT geomean(score) FROM sensors WHERE id = 1",
                "expected/gm_score.tsv",
            ),
            (
                &sensors,
                "SELECT geomean(score) FROM sensors WHERE score > 0",
                "expected/gm_pos.tsv",
            ),
            (
                &sensors,
                "SELECT geomean(flags) FROM sensors WHERE flags > 0",
                "expected/gm_flags.tsv",
            ),
            (
                &sensors,
                "SELECT geomean(b) FROM sensors WHERE b > 0",
                "expected/gm_byte.tsv",
            ),
            (
                &sensors,
                "SELECT geomean(id) FROM sensors WHERE id > 0",
                "expected/gm_idpos.tsv",
            ),
            (
                &sensors,
                "SELECT geomean(reading) FROM sensors GROUP BY location ORDER BY location",
                "expected/gm_grp.tsv",
            ),
            (
                &sensors,
                "SELECT geomean(score) FROM sensors WHERE id = 1 GROUP BY location ORDER BY location",
                "expected/gm_one_grp.tsv",
            ),
            (
                &sensors,
                "SELECT geomean(reading) FROM sensors LIMIT 0",
                "expected/gm_lim0.tsv",
            ),
            (
                &sensors,
                "SELECT GEOMEAN(reading) FROM sensors WHERE id = 1",
                "expected/gm_case.tsv",
            ),
            (
                &sensors,
                "SELECT geomean(day) FROM sensors",
                "expected/gm_day.tsv",
            ),
            (
                &sensors,
                "SELECT geomean(reading) FROM sensors WHERE id = 2",
                "expected/gm_nullread.tsv",
            ),
            (
                &sensors,
                "SELECT geomean(score) FROM sensors WHERE id = 2",
                "expected/gm_neg.tsv",
            ),
            (
                &sensors,
                "SELECT geomean(flags) FROM sensors WHERE id = 1",
                "expected/gm_flag1.tsv",
            ),
            (
                &sensors,
                "SELECT geomean(b) FROM sensors WHERE id = 1",
                "expected/gm_byte1.tsv",
            ),
            (
                &days,
                "SELECT geomean(id) FROM days",
                "expected/gm_days.tsv",
            ),
            (
                &days,
                "SELECT geomean(id) FROM days GROUP BY location ORDER BY location",
                "expected/gm_days_grp.tsv",
            ),
        ];
        for (dir, sql, file) in cases {
            let result = execute(dir, sql).unwrap();
            let expected = std::fs::read_to_string(dir.join(file)).unwrap();
            assert_eq!(render_tsv(&result), expected, "{sql}");
        }
        let err = execute(&sensors, "SELECT geomean() FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("function `geomean` requires arguments: geomean(DOUBLE)"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT geomean(reading, 1) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "wrong number of arguments for function `geomean`; expected: 1, provided: 2"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT geomean(*) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("too few arguments for '*' [found=0,expected=2]"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT geomean(missing) FROM sensors").unwrap_err();
        assert!(
            err.message.contains("Invalid column: missing"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT geomean(ok) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "argument type mismatch for function `geomean` at #1 expected: DOUBLE, actual: BOOLEAN"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT geomean(location) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "argument type mismatch for function `geomean` at #1 expected: DOUBLE, actual: SYMBOL"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT geomean(note) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("inconvertible value: `alpha` [STRING -> DOUBLE]"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT geomean(ch) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("inconvertible value: A [CHAR -> DOUBLE]"),
            "{}",
            err.message
        );
    }

    #[test]
    fn twap_matches_captured_exec() {
        let sensors = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h1");
        let days = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h2");
        let cases = [
            (
                &sensors,
                "SELECT twap(reading, ts) FROM sensors",
                "expected/tw_read.tsv",
            ),
            (
                &sensors,
                "SELECT twap(reading, ts) FROM sensors WHERE id = 1",
                "expected/tw_one.tsv",
            ),
            (
                &sensors,
                "SELECT twap(reading, ts) FROM sensors WHERE id > 100",
                "expected/tw_none.tsv",
            ),
            (
                &sensors,
                "SELECT twap(reading, ts) FROM sensors WHERE id = -1",
                "expected/tw_neg.tsv",
            ),
            (
                &sensors,
                "SELECT twap(score, ts) FROM sensors",
                "expected/tw_score.tsv",
            ),
            (
                &sensors,
                "SELECT twap(id, ts) FROM sensors",
                "expected/tw_id.tsv",
            ),
            (
                &sensors,
                "SELECT twap(b, ts) FROM sensors",
                "expected/tw_byte.tsv",
            ),
            (
                &sensors,
                "SELECT twap(flags, ts) FROM sensors",
                "expected/tw_flags.tsv",
            ),
            (
                &sensors,
                "SELECT twap(reading, ts) FROM sensors GROUP BY location ORDER BY location",
                "expected/tw_grp.tsv",
            ),
            (
                &sensors,
                "SELECT twap(reading, ts) FROM sensors LIMIT 0",
                "expected/tw_lim0.tsv",
            ),
            (
                &sensors,
                "SELECT TWAP(reading, ts) FROM sensors",
                "expected/tw_case.tsv",
            ),
            (
                &days,
                "SELECT twap(id, ts) FROM days",
                "expected/tw_days.tsv",
            ),
            (
                &days,
                "SELECT twap(id, ts) FROM days GROUP BY location ORDER BY location",
                "expected/tw_days_grp.tsv",
            ),
        ];
        for (dir, sql, file) in cases {
            let result = execute(dir, sql).unwrap();
            let expected = std::fs::read_to_string(dir.join(file)).unwrap();
            assert_eq!(render_tsv(&result), expected, "{sql}");
        }
        let err = execute(&sensors, "SELECT twap() FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("function `twap` requires arguments: twap(DOUBLE, TIMESTAMP)"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT twap(reading) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "wrong number of arguments for function `twap`; expected: 2, provided: 1"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT twap(reading, ts, id) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "wrong number of arguments for function `twap`; expected: 2, provided: 3"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT twap(*) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("too few arguments for '*' [found=0,expected=2]"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT twap(missing, ts) FROM sensors").unwrap_err();
        assert!(
            err.message.contains("Invalid column: missing"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT twap(reading, missing) FROM sensors").unwrap_err();
        assert!(
            err.message.contains("Invalid column: missing"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT twap(reading, flags) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "twap() requires the table's designated timestamp as the second argument"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT twap(reading, day) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "twap() requires the table's designated timestamp as the second argument"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT twap(ok, ts) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("expression type mismatch, expected: DOUBLE, actual: BOOLEAN"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT twap(note, ts) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("inconvertible value: `alpha` [STRING -> DOUBLE]"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT twap(location, ts) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("expression type mismatch, expected: DOUBLE, actual: SYMBOL"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT twap(ch, ts) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("inconvertible value: A [CHAR -> DOUBLE]"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT twap(tag, ts) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("inconvertible value: `v1` [VARCHAR -> DOUBLE]"),
            "{}",
            err.message
        );
        let err = execute(
            &sensors,
            "SELECT twap(reading, ts) FROM sensors ORDER BY ts DESC",
        )
        .unwrap_err();
        assert!(
            err.message
                .contains("ORDER BY expressions must appear in select list. Invalid column: ts"),
            "{}",
            err.message
        );
    }

    #[test]
    fn sparkline_matches_captured_exec() {
        let sensors = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h1");
        let days = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/h2");
        let cases = [
            (
                &sensors,
                "SELECT sparkline(flags) FROM sensors",
                "expected/sl_flags.tsv",
            ),
            (
                &sensors,
                "SELECT sparkline(flags) FROM sensors WHERE id = 1",
                "expected/sl_one.tsv",
            ),
            (
                &sensors,
                "SELECT sparkline(flags) FROM sensors WHERE id > 100",
                "expected/sl_none.tsv",
            ),
            (
                &sensors,
                "SELECT sparkline(reading) FROM sensors",
                "expected/sl_read.tsv",
            ),
            (
                &sensors,
                "SELECT sparkline(score) FROM sensors",
                "expected/sl_score.tsv",
            ),
            (
                &sensors,
                "SELECT sparkline(b) FROM sensors",
                "expected/sl_byte.tsv",
            ),
            (
                &sensors,
                "SELECT sparkline(id) FROM sensors",
                "expected/sl_id.tsv",
            ),
            (
                &sensors,
                "SELECT sparkline(code) FROM sensors",
                "expected/sl_code.tsv",
            ),
            (
                &sensors,
                "SELECT sparkline(day) FROM sensors",
                "expected/sl_day.tsv",
            ),
            (
                &sensors,
                "SELECT sparkline(ts) FROM sensors",
                "expected/sl_ts.tsv",
            ),
            (
                &sensors,
                "SELECT sparkline(flags) FROM sensors GROUP BY location ORDER BY location",
                "expected/sl_grp.tsv",
            ),
            (
                &sensors,
                "SELECT sparkline(flags) FROM sensors LIMIT 0",
                "expected/sl_lim0.tsv",
            ),
            (
                &sensors,
                "SELECT SPARKLINE(flags) FROM sensors",
                "expected/sl_case.tsv",
            ),
            (
                &sensors,
                "SELECT sparkline(flags, 0, 42, 2) FROM sensors",
                "expected/sl_width.tsv",
            ),
            (
                &sensors,
                "SELECT sparkline(flags, 0, 100, 2) FROM sensors",
                "expected/sl_wide.tsv",
            ),
            (
                &sensors,
                "SELECT sparkline(reading, 0, 1.5, 2) FROM sensors",
                "expected/sl_read_w.tsv",
            ),
            (
                &sensors,
                "SELECT sparkline(flags, 0, 42, 10) FROM sensors",
                "expected/sl_full.tsv",
            ),
            (
                &sensors,
                "SELECT sparkline(flags, null, null, 3) FROM sensors",
                "expected/sl_auto.tsv",
            ),
            (
                &sensors,
                "SELECT sparkline(flags) FROM sensors WHERE id = -1",
                "expected/sl_neg.tsv",
            ),
            (
                &days,
                "SELECT sparkline(id) FROM days",
                "expected/sl_days.tsv",
            ),
            (
                &days,
                "SELECT sparkline(id) FROM days GROUP BY location ORDER BY location",
                "expected/sl_days_grp.tsv",
            ),
        ];
        for (dir, sql, file) in cases {
            let result = execute(dir, sql).unwrap();
            let expected = std::fs::read_to_string(dir.join(file)).unwrap();
            assert_eq!(render_tsv(&result), expected, "{sql}");
        }
        let err = execute(&sensors, "SELECT sparkline() FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("function `sparkline` requires arguments"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT sparkline(flags, 1) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "there is no matching function `sparkline` with the argument types: (INT, INT)"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT sparkline(flags, 1, 2) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "there is no matching function `sparkline` with the argument types: (INT, INT, INT)"
            ),
            "{}",
            err.message
        );
        let err = execute(
            &sensors,
            "SELECT sparkline(flags, 0, 42, 2, 1) FROM sensors",
        )
        .unwrap_err();
        assert!(
            err.message.contains(
                "there is no matching function `sparkline` with the argument types: (INT, INT, INT, INT, INT)"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT sparkline(flags, reading) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "there is no matching function `sparkline` with the argument types: (INT, DOUBLE)"
            ),
            "{}",
            err.message
        );
        let err =
            execute(&sensors, "SELECT sparkline(flags, 0, 42, 2.5) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "there is no matching function `sparkline` with the argument types: (INT, INT, INT, DOUBLE)"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT sparkline(*) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("too few arguments for '*' [found=0,expected=2]"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT sparkline(missing) FROM sensors").unwrap_err();
        assert!(
            err.message.contains("Invalid column: missing"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT sparkline(ok) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "there is no matching function `sparkline` with the argument types: (BOOLEAN)"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT sparkline(location) FROM sensors").unwrap_err();
        assert!(
            err.message.contains(
                "there is no matching function `sparkline` with the argument types: (SYMBOL)"
            ),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT sparkline(note) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("inconvertible value: `alpha` [STRING -> DOUBLE]"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT sparkline(ch) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("inconvertible value: A [CHAR -> DOUBLE]"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT sparkline(tag) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("inconvertible value: `v1` [VARCHAR -> DOUBLE]"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT sparkline(ch) FROM sensors WHERE id = 2").unwrap_err();
        assert!(
            err.message
                .contains("inconvertible value: \0 [CHAR -> DOUBLE]"),
            "{}",
            err.message
        );
        let err =
            execute(&sensors, "SELECT sparkline(flags, 'a', 42, 2) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("inconvertible value: a [CHAR -> DOUBLE]"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT sparkline(flags, 0, 42, 0) FROM sensors").unwrap_err();
        assert!(
            err.message.contains("width must be a positive integer"),
            "{}",
            err.message
        );
        let err = execute(
            &sensors,
            "SELECT sparkline(flags, 0, 42, null) FROM sensors",
        )
        .unwrap_err();
        assert!(
            err.message.contains("width must be a positive integer"),
            "{}",
            err.message
        );
        let err = execute(&sensors, "SELECT sparkline(flags, 5, 1, 2) FROM sensors").unwrap_err();
        assert!(
            err.message
                .contains("sparkline() min must not exceed max [min=5.0, max=1.0]"),
            "{}",
            err.message
        );
        let result = execute(
            &sensors,
            "SELECT sparkline(flags, 0, 42, 0) FROM sensors WHERE id > 100",
        )
        .unwrap();
        assert_eq!(render_tsv(&result), "sparkline(flags, 0, 42, 0)\nNULL\n");
    }

